// 2. Coalesced Global Memory Accesses for both A and B.
// 3. Shared Memory Padding to avoid bank conflicts.

__global__ void matmul_ab_t_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int M, int N, int K) {

    // Tile size (BLOCK_SIZE)
    const int BS = 32;

    // Block and Thread indices
    int bx = blockIdx.x; // Block index for N (columns of C)
    int by = blockIdx.y; // Block index for M (rows of C)
    int tx = threadIdx.x; // Thread index within block (col)
    int ty = threadIdx.y; // Thread index within block (row)

