    int row = by * BS + ty;
    int col = bx * BS + tx;

    // Accumulator
    float val = 0.0f;

    // Shared memory buffers
    // Padding [33] instead of [32] to avoid bank conflicts during transposed access
    __shared__ float sA[32][33];
    __shared__ float sB[32][33];

    // Loop over the K dimension in chunks of BS
    for (int k = 0; k < K; k += BS) {

        // 1. Load tile from A into shared memory
        // We need A[row, k...k+BS].
        // Global read: A[row * K + (k + tx)]
        // Since 'row' is constant for a warp (assuming warp along x for visualization, though mapped to ty here),
        // and 'tx' varies, we are reading contiguous memory (k+tx). This is coalesced.
        if (row < M && (k + tx) < K) {
            sA[ty][tx] = A[row * K + (k + tx)];
        } else {
            sA[ty][tx] = 0.0f;
        }

        // 2. Load tile from B into shared memory
        // We need B rows corresponding to the columns of C we are computing.
        // The block covers C columns [bx*BS ... bx*BS+BS].
        // So we need B rows [bx*BS ... bx*BS+BS].
