        long long n = idx / ((long long)C * H * W);
        long long c = (idx / ((long long)H * W)) % C;
        long long h = (idx / W) % H;
        long long w = idx % W;

        int C_per_G = C / G;
        int group_idx = c / C_per_G;

        // Index into the mean/rstd buffers
        int group_buffer_idx = n * G + group_idx;

        float mean = mean_buffer[group_buffer_idx];
        float rstd = rstd_buffer[group_buffer_idx];

        float x_val = x[idx];
        float gamma_val = gamma[c]; // gamma and beta are per-channel
        float beta_val = beta[c];

        float normalized_val = (x_val - mean) * rstd;
        out[idx] = gamma_val * normalized_val + beta_val;
