    int batch_id = blockIdx.x;
    int tid = threadIdx.x;

    // Calculate pointers for the current row
    const float* row_x = x + batch_id * dim;
    float* row_out = out + batch_id * dim;

    float sum_sq = 0.0f;

    // 1. Compute Sum of Squares (Grid-Stride Loop logic within block)
    // Using __ldg for read-only data cache optimization
    for (int i = tid; i < dim; i += blockDim.x) {
        float val = __ldg(&row_x[i]);
        sum_sq += val * val;
