#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void min_reduce_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                  int outer_size, int reduce_size, int inner_size) {
    // We flatten the parallelization domain to the total number of output elements.
    // Each thread is responsible for computing one output value.
    // The input tensor is logically viewed as (outer, reduce, inner).
    // The output tensor is logically viewed as (outer, inner).

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output_elements = outer_size * inner_size;

    if (idx < total_output_elements) {
        // Map linear index 'idx' back to (outer_index, inner_index) coordinates
        // idx = o * inner_size + i
        int i = idx % inner_size;
        int o = idx / inner_size;

        float min_val = FLT_MAX;

        // Calculate the starting offset in the input tensor for this thread.
        // We iterate over the 'reduce' dimension (size = reduce_size).
        // The flattened input index is: o * (reduce_size * inner_size) + r * inner_size + i
        // We use 'long long' for the offset to prevent overflow for large tensors (approx > 2GB).
        long long input_offset = (long long)o * reduce_size * inner_size + i;

