#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::min, though fminf is better for floats
#include <limits>    // For std::numeric_limits

// Helper function to get linear index for a 3D tensor, considering strides
__device__ __forceinline__ int get_linear_idx(int d0, int d1, int d2,
                                              int stride0, int stride1, int stride2) {
    return d0 * stride0 + d1 * stride1 + d2 * stride2;
}

__global__ void min_reduction_kernel(const float* x, float* out,
                                     int S0, int S1, int S2,
                                     int stride0, int stride1, int stride2,
                                     int dim,
                                     int reduced_dim_size, // Size of the dimension being reduced
                                     int output_numel) {
    // Each block is responsible for computing one element of the output tensor.
    int output_idx = blockIdx.x;

    // Guard against out-of-bounds block indices if num_blocks is not perfectly divisible
    if (output_idx >= output_numel) {
        return;
    }

    // Map the linear output_idx to multi-dimensional indices for the non-reduced dimensions.
    // These indices determine which slice of the input tensor this block will process.
    int idx0_non_reduced, idx1_non_reduced, idx2_non_reduced;

    if (dim == 0) { // Reducing S0 (first dimension), output indices are (idx1, idx2)
        idx1_non_reduced = output_idx / S2;
        idx2_non_reduced = output_idx % S2;
    } else if (dim == 1) { // Reducing S1 (second dimension), output indices are (idx0, idx2)
        idx0_non_reduced = output_idx / S2;
        idx2_non_reduced = output_idx % S2;
    } else { // dim == 2 (reducing S2, third dimension), output indices are (idx0, idx1)
        idx0_non_reduced = output_idx / S1;
        idx1_non_reduced = output_idx % S1;
    }

    // Declare shared memory for reduction within the block.
    // The size is determined at kernel launch time (smem_size).
    extern __shared__ float s_min[];

    // Initialize thread-local minimum value with the maximum possible float value.
    float thread_min_val = std::numeric_limits<float>::max();

    // Each thread processes multiple elements along the dimension being reduced.
    // This loop distributes the work of iterating over the 'reduced_dim_size' among threads.
    for (int i = threadIdx.x; i < reduced_dim_size; i += blockDim.x) {
        int current_idx0, current_idx1, current_idx2;

        // Construct the full 3D input index for the current element 'i' along the reduced dimension.
        if (dim == 0) {
            current_idx0 = i; // This is the index along the reduced dimension
            current_idx1 = idx1_non_reduced;
            current_idx2 = idx2_non_reduced;
        } else if (dim == 1) {
            current_idx0 = idx0_non_reduced;
            current_idx1 = i; // This is the index along the reduced dimension
            current_idx2 = idx2_non_reduced;
        } else { // dim == 2
            current_idx0 = idx0_non_reduced;
            current_idx1 = idx1_non_reduced;
            current_idx2 = i; // This is the index along the reduced dimension
        }

        // Calculate the linear index in global memory for the input tensor 'x'.
        int linear_idx = get_linear_idx(current_idx0, current_idx1, current_idx2,
                                        stride0, stride1, stride2);

        // Update the thread-local minimum.
        thread_min_val = fminf(thread_min_val, x[linear_idx]);
    }

    // Store the thread-local minimum into shared memory.
    s_min[threadIdx.x] = thread_min_val;
    // Synchronize all threads in the block to ensure all thread-local mins are written to shared memory.
    __syncthreads();

    // Perform a parallel reduction in shared memory to find the minimum among all threads in the block.
    // This is a logarithmic reduction (tree reduction).
    // It assumes blockDim.x is a power of 2 for optimal performance, but works generally.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_min[threadIdx.x] = fminf(s_min[threadIdx.x], s_min[threadIdx.x + s]);
        }
        __syncthreads(); // Synchronize after each step of the reduction.
    }

    // The first thread in the block (threadIdx.x == 0) holds the final minimum for this output element.
    // It writes the result to global memory.
    if (threadIdx.x == 0) {
