    // blockIdx.y / threadIdx.y covers out_w
    // blockIdx.z / threadIdx.x covers out_d (coalesced)
    int n_oc_oh = blockIdx.x;
    int ow = blockIdx.y * blockDim.y + threadIdx.y;
    int od = blockIdx.z * blockDim.x + threadIdx.x;

    if (od < out_d && ow < out_w && n_oc_oh < batch_size * out_channels * out_h) {
        int oh = n_oc_oh % out_h;
        int oc = (n_oc_oh / out_h) % out_channels;
        int n = n_oc_oh / (out_h * out_channels);

