    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_d * out_h * out_w;

    if (idx >= total_elements) return;

    // Decode linear index to (n, c_out, oz, oy, ox)
    int temp = idx;
    int ox = temp % out_w; temp /= out_w;
    int oy = temp % out_h; temp /= out_h;
    int oz = temp % out_d; temp /= out_d;
    int c_out = temp % out_channels; temp /= out_channels;
    int n = temp;

    // Initialize with bias if present
    float val = 0.0f;
    if (bias != nullptr) {
