    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int ox = blockIdx.x * blockDim.x + tx;
    int oy = blockIdx.y * blockDim.y + ty;

    // Z-dimension of grid maps to batch and output channel
    int b_k = blockIdx.z;
    int b = b_k / out_channels;
    int k = b_k % out_channels;

    // Bounds check
    if (b >= batch_size || k >= out_channels || ox >= out_w || oy >= out_h) {
        return;
    }

    float val = 0.0f;

    // Add bias if present
    if (bias != nullptr) {
        val = bias[k];
    }

    // Convolution loop
    for (int c = 0; c < in_channels; ++c) {
        for (int p = 0; p < kernel_h; ++p) {
            for (int q = 0; q < kernel_w; ++q) {
                int in_y = oy * stride - padding + p * dilation;
                int in_x = ox * stride - padding + q * dilation;

