    is equivalent to a Conv1d operation with:
    - input: original input x
    - weights: original ConvTranspose1d weights, flipped along the kernel dimension, and then permuted
               from (C_in, C_out, K) to (C_out, C_in, K).
    - stride=1
    - padding=kernel_size - 1
    - groups=1
    - bias=False
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Store original parameters for validation and reference
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias

        # Validate that the custom kernel can handle the provided parameters
        if not (stride == 1 and padding == 0 and output_padding == 0 and groups == 1 and bias == False):
            raise ValueError(
                "Custom ConvTranspose1d kernel in ModelNew only supports "
                "stride=1, padding=0, output_padding=0, groups=1, and bias=False. "
                "For other parameters, the original PyTorch operator should be used."
            )

        # Initialize a dummy ConvTranspose1d layer to get its default initialized weight tensor.
        # This ensures our custom kernel uses the same initial weights as the PyTorch operator.
        dummy_conv = nn.ConvTranspose1d(in_channels, out_channels, kernel_size, 
                                        stride=stride, padding=padding, 
                                        output_padding=output_padding, groups=groups, bias=bias)

        # Pre-process the weight for the custom Conv1d kernel:
        # 1. Flip the kernel along the last dimension (kernel_size dimension).
        #    PyTorch's ConvTranspose1d weights are (in_channels, out_channels // groups, kernel_size).
        weight_flipped = dummy_conv.weight.flip(dims=[-1])

        # 2. Permute dimensions from (C_in, C_out, K) to (C_out, C_in, K).
        #    This is because our custom Conv1d kernel (like F.conv1d) expects weights in this format.
        self.weight_preprocessed = nn.Parameter(weight_flipped.permute(1, 0, 2))

        # Store kernel_size and padding for the custom Conv1d kernel.
        # For ConvTranspose1d with stride=1, padding=0, output_padding=0,
        # the equivalent Conv1d requires padding = kernel_size - 1.
        self.custom_kernel_size = kernel_size
        self.custom_padding = kernel_size - 1

        # Store the compiled custom CUDA kernel module
        self.conv1d_custom = conv1d_custom

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 1D convolution using the custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, length).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, length_out).
        """
        # Ensure input tensor is on the CUDA device before passing to the kernel
        x = x.cuda()

        # Call the custom CUDA kernel with the pre-processed weights and parameters
        return self.conv1d_custom.conv1d_cuda_forward(
            x,
            self.weight_preprocessed,
            self.custom_kernel_size,
            self.custom_padding
        )

