conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For debugging, can remove in production

// Helper for 4D tensor indexing (input: B, C_in, H_in, W_in)
__device__ __forceinline__ int get_input_idx(int b, int c_in, int h_in, int w_in,
                                            int C_in, int H_in, int W_in) {
    return b * (C_in * H_in * W_in) +
           c_in * (H_in * W_in) +
           h_in * W_in +
           w_in;
}

// Helper for 4D tensor indexing (weight: C_in, C_out, K_H, K_W)
__device__ __forceinline__ int get_weight_idx(int c_in, int c_out, int k_h, int k_w,
                                             int C_out, int K_H, int K_W) {
    return c_in * (C_out * K_H * K_W) +
           c_out * (K_H * K_W) +
           k_h * K_W +
           k_w;
}

// Helper for 4D tensor indexing (output: B, C_out, H_out, W_out)
__device__ __forceinline__ int get_output_idx(int b, int c_out, int h_out, int w_out,
                                             int C_out, int H_out, int W_out) {
    return b * (C_out * H_out * W_out) +
           c_out * (H_out * W_out) +
           h_out * W_out +
           w_out;
}


__global__ void conv_transpose2d_kernel(const float* input,
                                        const float* weight,
                                        float* output,
                                        int B, int C_in, int H_in, int W_in,
                                        int C_out, int K_H, int K_W,
                                        int H_out, int W_out) {
    // Each thread computes one output element (b, c_out, h_out, w_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < B * C_out * H_out * W_out) {
        // De-flatten index to 4D coordinates
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int c_out = (idx / (W_out * H_out)) % C_out;
        int b = idx / (C_out * H_out * W_out);

        float sum = 0.0f;

        // Iterate over input channels and kernel dimensions
        // For ConvTranspose2d (stride=1, padding=0, output_padding=0),
        // an output pixel (h_out, w_out) receives contributions from
        // input pixels (h_out - k_h, w_out - k_w)
        for (int c_in = 0; c_in < C_in; ++c_in) {
            for (int k_h = 0; k_h < K_H; ++k_h) {
                for (int k_w = 0; k_w < K_W; ++k_w) {
                    // Calculate corresponding input coordinates
                    int h_in = h_out - k_h;
                    int w_in = w_out - k_w;

                    // Check if input coordinates are within bounds (implicit padding with zeros)
                    if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                        float input_val = input[get_input_idx(b, c_in, h_in, w_in, C_in, H_in, W_in)];
                        float weight_val = weight[get_weight_idx(c_in, c_out, k_h, k_w, C_out, K_H, K_W)];
                        sum += input_val * weight_val;
                    }
                }
            }
        }
        output[get_output_idx(b, c_out, h_out, w_out, C_out, H_out, W_out)] = sum;
    }
