    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int b_oc = blockIdx.z;

    int oc = b_oc % Co;
    int b = b_oc / Co;

    if (ow < Wo && oh < Ho && b < B) {
        float sum = 0.0f;
        for (int ci = 0; ci < Ci; ++ci) {
            for (int kh = 0; kh < Kh; ++kh) {
                int num_h = oh + ph - kh * dh;
                if (num_h >= 0 && num_h % sh == 0) {
                    int ih = num_h / sh;
                    if (ih >= 0 && ih < Hi) {
                        int input_base = (b * Ci + ci) * Hi + ih;
                        int weight_base = (ci * Co + oc) * Kh + kh;
