# Define the custom CUDA kernel for ConvTranspose3d
# This kernel implements a simplified ConvTranspose3d without bias fusion.
# It supports groups, stride, padding, and output_padding.
# Note: For general cases, highly optimized libraries like cuDNN are significantly faster.
# This implementation is for demonstration purposes of replacing an operator with a custom kernel.
conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For debugging, can remove

// Helper function to get 5D tensor index (row-major)
// Args:
//   idx0, idx1, idx2, idx3, idx4: The 5D indices
//   dim1_size, dim2_size, dim3_size, dim4_size: Sizes of dimensions 1, 2, 3, 4 respectively.
//                                               (i.e., total_size = dim0_size * dim1_size * dim2_size * dim3_size * dim4_size)
__device__ __forceinline__ int get_idx_5d(
    int idx0, int idx1, int idx2, int idx3, int idx4,
    int dim1_size, int dim2_size, int dim3_size, int dim4_size) {
    return idx0 * (dim1_size * dim2_size * dim3_size * dim4_size) +
           idx1 * (dim2_size * dim3_size * dim4_size) +
           idx2 * (dim3_size * dim4_size) +
           idx3 * (dim4_size) +
           idx4;
}

__global__ void conv_transpose3d_kernel(
    const float* x_ptr, const float* w_ptr, float* out_ptr,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int K_D, int K_H, int K_W,
    int S_D, int S_H, int S_W,
    int P_D, int P_H, int P_W,
    int OP_D, int OP_H, int OP_W,
    int groups,
    int D_out, int H_out, int W_out) {

    long long total_output_elements = (long long)N * C_out * D_out * H_out * W_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output_elements) {
        // Map flat index to 5D output coordinates (n, co, do, ho, wo)
        int n = idx / (C_out * D_out * H_out * W_out);
        int rem = idx % (C_out * D_out * H_out * W_out);
        int co = rem / (D_out * H_out * W_out);
        rem = rem % (D_out * H_out * W_out);
        int do_out = rem / (H_out * W_out);
        rem = rem % (H_out * W_out);
        int ho_out = rem / W_out;
        int wo_out = rem % W_out;

        float sum = 0.0f;

        int c_in_per_group = C_in / groups;
        int c_out_per_group = C_out / groups;
        int group_idx = co / c_out_per_group; // Which group this output channel belongs to

        // Iterate over kernel dimensions
        for (int k_d = 0; k_d < K_D; ++k_d) {
            for (int k_h = 0; k_h < K_H; ++k_h) {
                for (int k_w = 0; k_w < K_W; ++k_w) {
                    // Calculate corresponding input coordinates (d_in, h_in, w_in)
                    // The relationship is: d_out = d_in * S_D - P_D + k_d
                    // So, d_in = (d_out + P_D - k_d) / S_D
                    int d_in_candidate = do_out + P_D - k_d;
                    int h_in_candidate = ho_out + P_H - k_h;
                    int w_in_candidate = wo_out + P_W - k_w;

                    // Check if candidate input coordinates are valid (integer and within input bounds)
                    if (d_in_candidate % S_D == 0 && h_in_candidate % S_H == 0 && w_in_candidate % S_W == 0) {
                        int d_in = d_in_candidate / S_D;
                        int h_in = h_in_candidate / S_H;
                        int w_in = w_in_candidate / S_W;

                        if (d_in >= 0 && d_in < D_in &&
                            h_in >= 0 && h_in < H_in &&
                            w_in >= 0 && w_in < W_in) {

                            // Iterate over input channels for this group
                            for (int c_in_local = 0; c_in_local < c_in_per_group; ++c_in_local) {
                                int c_in_global = group_idx * c_in_per_group + c_in_local;

                                // Accumulate sum
                                // Input tensor x: (N, C_in, D_in, H_in, W_in)
                                // Weight tensor w: (C_in_per_group, C_out_per_group, K_D, K_H, K_W)
                                sum += x_ptr[get_idx_5d(n, c_in_global, d_in, h_in, w_in, C_in, D_in, H_in, W_in)] *
                                       w_ptr[get_idx_5d(c_in_local, co % c_out_per_group, k_d, k_h, k_w, c_out_per_group, K_D, K_H, K_W)];
                            }
                        }
                    }
                }
            }
        }
        out_ptr[idx] = sum;
    }
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor x, torch::Tensor weight,
    int S_D, int S_H, int S_W,
    int P_D, int P_H, int P_W,
    int OP_D, int OP_H, int OP_W,
    int groups) {

    // Ensure tensors are on CUDA and float32
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(weight.is_cuda(), "Weight tensor must be on CUDA.");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor must be float32.");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "Weight tensor must be float32.");

    // Input dimensions
    int N = x.size(0);
    int C_in = x.size(1);
    int D_in = x.size(2);
    int H_in = x.size(3);
    int W_in = x.size(4);

    // Kernel dimensions
    int K_D = weight.size(2);
    int K_H = weight.size(3);
    int K_W = weight.size(4);

    // C_out is derived from weight.size(1) * groups, as weight.size(1) is C_out_per_group
    int C_out = weight.size(1) * groups;

    // Calculate output dimensions
    // D_out = (D_in - 1) * stride[0] - 2 * padding[0] + kernel_size[0] + output_padding[0]
    int D_out = (D_in - 1) * S_D - 2 * P_D + K_D + OP_D;
    int H_out = (H_in - 1) * S_H - 2 * P_H + K_H + OP_H;
    int W_out = (W_in - 1) * S_W - 2 * P_W + K_W + OP_W;

    // Create output tensor
    auto out = torch::zeros({N, C_out, D_out, H_out, W_out}, x.options());

    // Launch kernel
    long long total_output_elements = (long long)N * C_out * D_out * H_out * W_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), weight.data_ptr<float>(), out.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, K_D, K_H, K_W,
        S_D, S_H, S_W,
        P_D, P_H, P_W,
        OP_D, OP_H, OP_W,
        groups,
        D_out, H_out, W_out);

    return out;
}
"""

conv_transpose3d_cpp_source = """
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor x, torch::Tensor weight,
    int S_D, int S_H, int S_W,
    int P_D, int P_H, int P_W,
    int OP_D, int OP_H, int OP_W,
    int groups);
