    extra_cuda_cflags=["-O3", "--use_fast_math"], # Add optimization flags for CUDA device code
)


class ModelNew(nn.Module):
    """
    Optimized Model replacing nn.ConvTranspose3d with a custom CUDA kernel.
    The custom kernel implements the core ConvTranspose3d logic, including groups,
    stride, padding, and output_padding.

    Note: This custom kernel is a direct implementation and is unlikely to outperform
    highly optimized cuDNN/MIOpen implementations used by default in PyTorch for
    general ConvTranspose3d operations. Its purpose is to demonstrate operator replacement.
    Bias handling is currently performed as a separate PyTorch operation, not fused into the kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Store parameters for the custom kernel
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias 

        # Validate groups
        if in_channels % groups != 0 or out_channels % groups != 0:
            raise ValueError("in_channels and out_channels must be divisible by groups")

        # Initialize weights similar to nn.ConvTranspose3d
        # PyTorch ConvTranspose3d weights are (in_channels, out_channels // groups, kD, kH, kW)
        self.weight = nn.Parameter(torch.empty(
            in_channels, out_channels // groups, kernel_size[0], kernel_size[1], kernel_size[2]
        ))
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        if self.bias:
            # If bias is true, initialize it.
            # For this custom kernel, bias addition is currently a separate PyTorch operation,
            # not fused into the CUDA kernel for simplicity.
            self.bias_param = nn.Parameter(torch.empty(out_channels))
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / (fan_in**0.5)
            nn.init.uniform_(self.bias_param, -bound, bound)
            # print("Warning: Custom ConvTranspose3d kernel does not currently fuse bias. Bias will be added as a separate PyTorch operation.")
        else:
            self.register_parameter('bias_param', None)

        # Reference to the compiled custom CUDA operator
        self.conv_transpose3d_cuda_op = conv_transpose3d_module.conv_transpose3d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is on CUDA and float32
        x = x.to(dtype=torch.float32, device='cuda')
        weight = self.weight.to(dtype=torch.float32, device='cuda')

        output = self.conv_transpose3d_cuda_op(
            x, weight,
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.output_padding[0], self.output_padding[1], self.output_padding[2],
            self.groups
        )

        if self.bias and self.bias_param is not None:
            # Add bias as a separate PyTorch operation.
            # For true fusion and potential speedup, this would be integrated into the kernel.
            output = output + self.bias_param.view(1, -1, 1, 1, 1)

        return output

