__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels, int out_channels,
    int in_depth, int in_height, int in_width,
    int out_depth, int out_height, int out_width,
    int kernel_d, int kernel_h, int kernel_w,
    int stride, int padding, int groups) {

    // Global index for output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;

    if (idx >= total_elements) return;

    // Decode 1D index to 5D coordinates (N, C_out, D_out, H_out, W_out)
    int w_out = idx % out_width;
    int tmp = idx / out_width;
    int h_out = tmp % out_height;
    tmp = tmp / out_height;
    int d_out = tmp % out_depth;
    tmp = tmp / out_depth;
    int c_out = tmp % out_channels;
    int n = tmp / out_channels;

    // Determine group and channel indices
    int channels_per_group_out = out_channels / groups;
    int channels_per_group_in = in_channels / groups;
    int group_id = c_out / channels_per_group_out;
    int c_out_rel = c_out % channels_per_group_out;

    // Starting input channel for this group
    int c_in_start = group_id * channels_per_group_in;

    // Initialize accumulator with bias if present
    float val = 0.0f;
    if (bias != nullptr) {
        val = bias[c_out];
    }

