    // We only process kernel weights that align with the strided input
    // Condition: (d_out + padding - kd) % stride == 0
    // Implies: kd % stride == (d_out + padding) % stride

    int kd_start = (d_out + padding) % stride;
    int kh_start = (h_out + padding) % stride;
    int kw_start = (w_out + padding) % stride;

    // Iterate over relevant kernel weights
    for (int kd = kd_start; kd < kernel_d; kd += stride) {
        int d_in = (d_out + padding - kd) / stride;
