#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256
#define C_BLOCK 32 // Tile size for input channels

// Kernel: Optimized for stride=1, dilation>1, small kernel size
// Uses Shared Memory for both Weights and Input X to reduce global memory bandwidth
__global__ void conv_transpose1d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    float* __restrict__ y,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_length,
    int out_length,
    int kernel_size,
    int padding,
    int dilation
) {
    // Grid dimensions:
    // x: Output tiles (spatial)
    // y: Output channels
    // z: Batch size

    int tid = threadIdx.x;
    int blk_x = blockIdx.x;
    int c_out = blockIdx.y;
    int n = blockIdx.z;

    int l_out_base = blk_x * BLOCK_SIZE;
    int l_out = l_out_base + tid;
    bool valid_out = (l_out < out_length);

    // Calculate Shared Memory Layout
    // s_w: Stores weights for [C_BLOCK, 1, kernel_size] -> size: C_BLOCK * kernel_size
    // s_x: Stores input tile -> size: C_BLOCK * input_tile_width
    // Input tile width depends on receptive field. 
    // For output l, we need input i = l + padding - k*dilation
    // Min i (k=K-1) -> l - (K-1)*D + padding
    // Max i (k=0)   -> l + padding
    // For block range [base, base+255], we need input range [base - (K-1)*D + padding, base + 255 + padding]

    int ghost_left = (kernel_size - 1) * dilation;
    int input_tile_width = BLOCK_SIZE + ghost_left;

    // Dynamic Shared Memory pointer setup
    extern __shared__ float smem[];
    float* s_w = smem; 
    float* s_x = smem + C_BLOCK * kernel_size;

    // Start index in Global X for this block
    //Corresponds to the input index needed for the leftmost output in block at max kernel offset
    int start_in_idx = l_out_base + padding - ghost_left;

    float acc = 0.0f;

    // Iterate over input channels in chunks of C_BLOCK
    for (int c_start = 0; c_start < in_channels; c_start += C_BLOCK) {
        int c_end = min(c_start + C_BLOCK, in_channels);
        int c_chunk = c_end - c_start;

        // 1. Load Weights into Shared Memory
        // Need W[c, c_out, k] for c in [c_start, c_end)
        int num_weights = c_chunk * kernel_size;
        for (int i = tid; i < num_weights; i += BLOCK_SIZE) {
            int k = i % kernel_size;
            int c_rel = i / kernel_size;
            int c_abs = c_start + c_rel;
            // Weight layout (Cin, Cout, K)
            int w_idx = c_abs * (out_channels * kernel_size) + c_out * kernel_size + k;
            s_w[c_rel * kernel_size + k] = weight[w_idx];
        }

        // 2. Load Input X into Shared Memory
        // Need X[n, c, l] for corresponding range
        int num_inputs = c_chunk * input_tile_width;
        for (int i = tid; i < num_inputs; i += BLOCK_SIZE) {
            int l_rel = i % input_tile_width;
            int c_rel = i / input_tile_width;
            int c_abs = c_start + c_rel;
            int l_abs = start_in_idx + l_rel;

            float val = 0.0f;
            if (l_abs >= 0 && l_abs < in_length) {
                // X layout (N, Cin, Lin)
                int x_idx = n * (in_channels * in_length) + c_abs * in_length + l_abs;
                val = x[x_idx];
            }
            s_x[c_rel * input_tile_width + l_rel] = val;
        }

        __syncthreads();

        // 3. Compute
        if (valid_out) {
            for (int k = 0; k < kernel_size; ++k) {
                // Determine index in shared memory X
                // Logic: global_needed = l_out + padding - k*dilation
                // smem_idx = global_needed - start_in_idx
                //          = (l_out_base + tid + padding - k*dilation) - (l_out_base + padding - ghost_left)
                //          = tid - k*dilation + ghost_left
                int smem_x_idx = tid - k * dilation + ghost_left;

                for (int c = 0; c < c_chunk; ++c) {
                    acc += s_x[c * input_tile_width + smem_x_idx] * s_w[c * kernel_size + k];
                }
            }
        }
        __syncthreads();
    }

    if (valid_out) {
        // Y layout (N, Cout, Lout)
        int y_idx = n * (out_channels * out_length) + c_out * out_length + l_out;
        y[y_idx] = acc;
    }
}

torch::Tensor conv_transpose1d_cuda(torch::Tensor x, torch::Tensor weight, 
                                    int kernel_size, int stride, int padding, int dilation, int out_padding) {
    int batch_size = x.size(0);
    int in_channels = x.size(1);
    int in_length = x.size(2);
    int out_channels = weight.size(1); 

    // Formula for output length in ConvTranspose1d
    int out_length = (in_length - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + out_padding + 1;

