# This kernel uses a "gather" approach (inverse mapping) to compute output pixels,
# avoiding atomic operations required by the "scatter" approach.
conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_depth, int in_height, int in_width,
    int out_depth, int out_height, int out_width,
    int k_d, int k_h, int k_w,
    int stride,
    int padding,
    int dilation) {

    // Global thread index mapping to output tensor (N, C_out, D_out, H_out, W_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;

    if (idx >= total_elements) return;

    // Decode flattened index into 5D coordinates
    // Layout: N, C_out, D_out, H_out, W_out
    int temp_idx = idx;
    int w_out_idx = temp_idx % out_width;
    temp_idx /= out_width;
    int h_out_idx = temp_idx % out_height;
    temp_idx /= out_height;
    int d_out_idx = temp_idx % out_depth;
    temp_idx /= out_depth;
    int c_out_idx = temp_idx % out_channels;
    int n_idx = temp_idx / out_channels;

    // Initialize accumulator with bias if available
    float sum = (bias != nullptr) ? bias[c_out_idx] : 0.0f;

    // Pre-calculate strides for efficiency
    int input_img_stride = in_depth * in_height * in_width;
    int input_batch_stride = in_channels * input_img_stride;

    // Weight memory layout: (in_channels, out_channels, k_d, k_h, k_w)
    int kernel_vol = k_d * k_h * k_w;
    int weight_cout_stride = kernel_vol;
    int weight_cin_stride = out_channels * kernel_vol;

    // Iterate over the kernel spatial dimensions to find contributing input pixels
    for (int kd = 0; kd < k_d; ++kd) {
        // Inverse mapping: d_in * stride = d_out + padding - kd * dilation
        int d_in_numer = d_out_idx + padding - kd * dilation;

        if (d_in_numer >= 0 && d_in_numer % stride == 0) {
            int d_in_idx = d_in_numer / stride;
            if (d_in_idx >= 0 && d_in_idx < in_depth) {

                for (int kh = 0; kh < k_h; ++kh) {
                    int h_in_numer = h_out_idx + padding - kh * dilation;

                    if (h_in_numer >= 0 && h_in_numer % stride == 0) {
                        int h_in_idx = h_in_numer / stride;
                        if (h_in_idx >= 0 && h_in_idx < in_height) {

                            for (int kw = 0; kw < k_w; ++kw) {
                                int w_in_numer = w_out_idx + padding - kw * dilation;

                                if (w_in_numer >= 0 && w_in_numer % stride == 0) {
                                    int w_in_idx = w_in_numer / stride;
                                    if (w_in_idx >= 0 && w_in_idx < in_width) {

                                        // Calculate offsets
                                        int input_spatial_offset = d_in_idx * (in_height * in_width) + 
                                                                   h_in_idx * in_width + 
                                                                   w_in_idx;

                                        int weight_spatial_offset = kd * (k_h * k_w) + kh * k_w + kw;

                                        // Pointers to the start of the channel loops
                                        const float* in_ptr = input + n_idx * input_batch_stride + input_spatial_offset;
                                        const float* w_ptr = weight + c_out_idx * weight_cout_stride + weight_spatial_offset;

                                        // Dot product over input channels
                                        for (int c_in = 0; c_in < in_channels; ++c_in) {
                                            sum += (*in_ptr) * (*w_ptr);

                                            // Advance pointers to next input channel
                                            in_ptr += input_img_stride;
                                            w_ptr += weight_cin_stride;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

