    // Calculate output dimensions
    int out_depth = (in_depth - 1) * stride - 2 * padding + dilation * (k_d - 1) + 1;
    int out_height = (in_height - 1) * stride - 2 * padding + dilation * (k_h - 1) + 1;
    int out_width = (in_width - 1) * stride - 2 * padding + dilation * (k_w - 1) + 1;

