        // This converts a 1D global thread index into 5D tensor coordinates.
        int w_out = idx % W_out;
        idx /= W_out;
        int h_out = idx % H_out;
        idx /= H_out;
        int d_out = idx % D_out;
        idx /= D_out;
        int c_out = idx % C_out;
        idx /= C_out;
