            for (int k_d = 0; k_d < K_D; ++k_d) {
                for (int k_h = 0; k_h < K_H; ++k_h) {
                    for (int k_w = 0; k_w < K_W; ++k_w) {
                        // Calculate corresponding input coordinates (d_in, h_in, w_in)
                        // based on output coordinates (d_out, h_out, w_out) and kernel (k_d, k_h, k_w).
                        // The relationship is:
                        // d_out = d_in * stride_d - padding_d + k_d * dilation_d
                        // Rearranging for d_in:
                        // d_in = (d_out + padding_d - k_d * dilation_d) / stride_d

                        int d_in_candidate = d_out + padding_d - k_d * dilation_d;
                        int h_in_candidate = h_out + padding_h - k_h * dilation_h;
                        int w_in_candidate = w_out + padding_w - k_w * dilation_w;

