    int c_out = (index / ((long)out_w * out_h)) % out_channels;
    int n = index / ((long)out_w * out_h * out_channels);

    float val = 0.0f;

    // Standard Transposed Convolution logic: 
    // An output pixel (n, co, h_out, w_out) receives contributions from input pixels (n, ci, hi, wi)
    // where h_out = hi * stride - padding + kh * dilation.
    // Solving for hi: hi * stride = h_out + padding - kh * dilation.
    for (int ci = 0; ci < in_channels; ++ci) {
