    int out_h,
    int out_w,
    int k_h,
    int k_w,
    int stride,
    int padding,
    int dilation,
    bool has_bias
) {
    // Map thread to output position
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    int bc = blockIdx.z; // encoded batch and out_channel

    if (w_out >= out_w || h_out >= out_h) return;

    int n = bc / out_channels;
    int c_out = bc % out_channels;

    if (n >= batch_size) return;

    float sum = 0.0f;
    if (has_bias) {
        sum = bias[c_out];
    }

    // For Transposed Conv, we gather contributions from the input.
    // An output pixel (h_out, w_out) is influenced by input pixel (h_in, w_in)
    // if: h_out = h_in * stride + k_h * dilation - padding
    // Rearranging for h_in: h_in * stride = h_out + padding - k_h * dilation

    // We iterate over input channels and the kernel window to find valid input pixels
    for (int c_in = 0; c_in < in_channels; ++c_in) {
