        self.weight = nn.Parameter(torch.empty(in_channels, 1, kernel_size, kernel_size))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if self.has_bias:
            self.bias = nn.Parameter(torch.empty(in_channels))
            # Calculate fan_in for bias initialization
            # For depthwise, fan_in is (in_channels_per_group * kernel_height * kernel_width)
            # Since groups = in_channels, in_channels_per_group = 1
            fan_in = 1 * kernel_size * kernel_size
            bound = 1 / math.sqrt(fan_in)
