        else:
            self.register_parameter('bias', None) # Register as None to be part of state_dict

        # Store the compiled custom CUDA operator
        self.depthwise_conv2d_op = depthwise_conv2d_module.depthwise_conv2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the depthwise 2D convolution using the custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, in_channels, height_out, width_out).
        """
        # Pass the bias tensor or an empty tensor if bias is not used
        # The C++ wrapper checks bias.defined() and bias.numel() > 0
        bias_tensor = self.bias if self.has_bias else torch.empty(0, device=x.device, dtype=x.dtype)
        return self.depthwise_conv2d_op(x, self.weight, bias_tensor, self.stride, self.padding)

