#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for pointwise 2D convolution
// This kernel computes the output for a 1x1 convolution.
// Each thread computes one element of the output tensor.
__global__ void pointwise_conv2d_kernel(
    const float* x,    // Input tensor (N, C_in, H, W)
    const float* w,    // Weight tensor (C_out, C_in, 1, 1) - conceptually flattened to (C_out, C_in)
    const float* b,    // Bias tensor (C_out) - can be nullptr if no bias
    float* out,        // Output tensor (N, C_out, H, W)
    int N, int C_in, int C_out, int H, int W,
    bool has_bias) {

    // Each thread computes one output element (n, c_out, h, w)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements
    int total_out_elements = N * C_out * H * W;

    if (idx < total_out_elements) {
        // Deconstruct idx to (n, c_out, h, w)
        // The output tensor is (N, C_out, H, W)
        int n_stride = C_out * H * W;
        int c_out_stride = H * W;
        int h_stride = W;

        int n = idx / n_stride;
        int rem_n = idx % n_stride;
        int c_out = rem_n / c_out_stride;
        int rem_c_out = rem_n % c_out_stride;
        int h = rem_c_out / h_stride;
        int w = rem_c_out % h_stride;

        float sum_val = 0.0f;

        // Calculate base pointers for efficient memory access within the loop
        // x_base_n_hw points to the start of the (n, :, h, w) slice in x
        // w_base_c_out points to the start of the (c_out, :) slice in w (flattened)
        const float* x_base_n_hw = x + n * (C_in * H * W) + (h * W + w);
        const float* w_base_c_out = w + c_out * C_in;

        // Perform the dot product: sum_{c_in} (x[n, c_in, h, w] * w[c_out, c_in])
        for (int c_in_idx = 0; c_in_idx < C_in; ++c_in_idx) {
            // x[n, c_in_idx, h, w] is accessed by adding c_in_idx * (H * W) to x_base_n_hw
            float x_val = x_base_n_hw[c_in_idx * (H * W)];
            // w[c_out, c_in_idx] is accessed by adding c_in_idx to w_base_c_out
            float w_val = w_base_c_out[c_in_idx];
            sum_val += x_val * w_val;
        }

