scan_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Intra-block prefix sum using warp shuffles and shared memory.
// Handles up to 1024 threads (32 warps).
__device__ float blockScan(float val, float* shared) {
    int lane = threadIdx.x & 0x1f; // threadIdx.x % 32
    int wid = threadIdx.x >> 5;   // threadIdx.x / 32

    // 1. Warp-level inclusive scan
    for (int offset = 1; offset < 32; offset <<= 1) {
        float tmp = __shfl_up_sync(0xffffffff, val, offset);
        if (lane >= offset) val += tmp;
    }

    // 2. Write the sum of each warp to shared memory
    if (lane == 31) shared[wid] = val;
    __syncthreads();

    // 3. The first warp scans the partial sums from shared memory
    if (wid == 0) {
        float s = (lane < (blockDim.x >> 5)) ? shared[lane] : 0.0f;
        for (int offset = 1; offset < 32; offset <<= 1) {
            float tmp = __shfl_up_sync(0xffffffff, s, offset);
            if (lane >= offset) s += tmp;
        }
        shared[lane] = s;
    }
    __syncthreads();

    // 4. Add the scanned warp sums back to each thread's value
    if (wid > 0) val += shared[wid - 1];
    return val;
}

// Kernel to compute row-wise prefix sum
__global__ void row_scan_kernel(const float* __restrict__ input, float* __restrict__ output, int64_t rows, int64_t cols) {
