    }

    // Compute the block-level inclusive prefix sum of thread_sum values
    float inclusive_block_sum = blockScan(thread_sum, shared_mem);

    // The exclusive offset for this thread's segment is (inclusive_block_sum - thread_sum)
    float running_sum = inclusive_block_sum - thread_sum;

    // Second pass: Compute the inclusive prefix sum locally and write back to global memory
    for (int64_t i = 0; i < elements_per_thread; ++i) {
        int64_t col = tid + i * threads;
        if (col < cols) {
