#include <torch/extension.h>
#include <cuda_runtime.h>

__device__ float warpPrefixProd(float val) {
    for (int offset = 1; offset < 32; offset <<= 1) {
        float other = __shfl_up_sync(0xffffffff, val, offset);
        if ((threadIdx.x & 31) >= offset) {
            val *= other;
        }
    }
    return val;
}

__global__ void cumprod_row_kernel(const float* __restrict__ input, float* __restrict__ output, int64_t B, int64_t N) {
    int64_t row = blockIdx.x;
    if (row >= B) return;

    const int tid = threadIdx.x;
    const int tsize = blockDim.x;
    const int64_t items_per_thread = (N + tsize - 1) / tsize;

    __shared__ float block_sums[32]; // For 1024 threads, we have 32 warps

    // 1. Thread-local product of its allocated segment
    float thread_prod = 1.0f;
    int64_t start = (int64_t)tid * items_per_thread;
    for (int64_t i = 0; i < items_per_thread; ++i) {
        int64_t idx = start + i;
        if (idx < N) {
            thread_prod *= input[row * N + idx];
        }
    }

    // 2. Intra-warp prefix product
    float warp_prefix = warpPrefixProd(thread_prod);
    int lane = tid & 31;
    int wid = tid >> 5;

    // Last thread of each warp stores the warp total product
    if (lane == 31) block_sums[wid] = warp_prefix;
    __syncthreads();

    // 3. Prefix product across warp totals (in the first warp)
    if (wid == 0) {
        float b_val = (tid < 32) ? block_sums[tid] : 1.0f;
