    float exclusive_prefix = 1.0f;
    if (wid > 0) exclusive_prefix *= block_sums[wid - 1];
    float prev_warp_prefix = __shfl_up_sync(0xffffffff, warp_prefix, 1);
    if (lane > 0) exclusive_prefix *= prev_warp_prefix;

    // 5. Compute and store final prefix product for each element
    for (int64_t i = 0; i < items_per_thread; ++i) {
        int64_t idx = start + i;
        if (idx < N) {
