        x_reshaped = x_perm.view(-1, feature_size)

        # Execute the custom CUDA kernel
        out_reshaped = self.cumprod_op.cumprod_cuda_forward(x_reshaped)

        # Reshape back to the permuted shape
        out_perm = out_reshaped.view(input_shape)

