# This implementation combines subtraction, squaring, and partial reduction into a single kernel.
# It uses a grid-stride loop for scalability and intra-block reduction with shuffle instructions.
mse_loss_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mse_loss_kernel(const float* predictions, const float* targets, float* out, size_t n) {
    float local_sum = 0.0f;
    size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
    size_t stride = (size_t)blockDim.x * gridDim.x;

    // Grid-stride loop handles arbitrary input sizes and optimizes memory bandwidth
    for (size_t i = idx; i < n; i += stride) {
        float p = predictions[i];
        float t = targets[i];
        float diff = p - t;
        local_sum += diff * diff;
    }

    // Warp-level reduction using shuffle sync
    for (int offset = 16; offset > 0; offset /= 2) {
        local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
    }

    // Shared memory for block-level reduction
    __shared__ float warp_sums[32]; // Max 32 warps (for 1024 threads per block)
    int lane = threadIdx.x & 31;
    int wid = threadIdx.x >> 5;

    if (lane == 0) warp_sums[wid] = local_sum;
    __syncthreads();

    // The first warp reduces partial sums from all warps in the block
    if (wid == 0) {
        int num_warps = blockDim.x >> 5;
        float val = (lane < num_warps) ? warp_sums[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset /= 2) {
            val += __shfl_down_sync(0xffffffff, val, offset);
        }
        if (lane == 0) {
            atomicAdd(out, val);
        }
    }
}

