#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper to reduce max within a warp
__device__ __forceinline__ float warpReduceMax(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

// Helper to reduce sum within a warp
__device__ __forceinline__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void cross_entropy_kernel(
    const float* __restrict__ logits,
    const int64_t* __restrict__ targets,
    float* __restrict__ losses,
    int batch_size,
    int num_classes) {

    // Shared memory for block reduction (max 32 warps supported, i.e., 1024 threads)
    __shared__ float shared_val[32];

    int tid = threadIdx.x;
    int bid = blockIdx.x;
    int warpId = tid / 32;
    int laneId = tid % 32;

    // Only 8 warps needed for 256 threads
    int num_warps = blockDim.x / 32;

    if (bid >= batch_size) return;

    // Pointer to the start of the row for this batch item
    const float* row_logits = logits + bid * num_classes;

    // --- Step 1: Find Max (for numerical stability) ---
    float local_max = -1e37f; // Effectively -inf

    // Stride over the columns
    for (int i = tid; i < num_classes; i += blockDim.x) {
        local_max = fmaxf(local_max, row_logits[i]);
    }

    // Reduce within warp
    local_max = warpReduceMax(local_max);

    // Write warp results to shared memory
    if (laneId == 0) shared_val[warpId] = local_max;
    __syncthreads();

    // Reduce across warps (using the first warp)
    if (warpId == 0) {
        float val = (tid < num_warps) ? shared_val[laneId] : -1e37f;
        val = warpReduceMax(val);
        // Broadcast result back to shared memory
        if (tid == 0) shared_val[0] = val;
    }
    __syncthreads();
    float row_max = shared_val[0];

    // --- Step 2: Compute Sum of Exponentials ---
    float local_sum = 0.0f;
    for (int i = tid; i < num_classes; i += blockDim.x) {
        local_sum += expf(row_logits[i] - row_max);
    }

    // Reduce within warp
    local_sum = warpReduceSum(local_sum);

    // Write warp results to shared memory
    if (laneId == 0) shared_val[warpId] = local_sum;
    __syncthreads();

    // Reduce across warps
    if (warpId == 0) {
        float val = (tid < num_warps) ? shared_val[laneId] : 0.0f;
        val = warpReduceSum(val);
        if (tid == 0) shared_val[0] = val;
    }
    __syncthreads();
    float row_sum_exp = shared_val[0];

    // --- Step 3: Compute Final Loss for the Row ---
    // Loss = -log(softmax(target)) 
    //      = -log( exp(target - max) / sum_exp )
    //      = -( (target - max) - log(sum_exp) )
    //      = -target + max + log(sum_exp)

    if (tid == 0) {
        int64_t target_idx = targets[bid];
        float target_val = row_logits[target_idx];
        losses[bid] = -target_val + row_max + logf(row_sum_exp);
    }
