#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat> // For FLT_MAX
#include <algorithm> // For std::min

// CUDA kernel for fused LogSoftmax and NLLLoss per sample
// Each block processes one sample (row) from the predictions tensor.
// It computes the numerically stable log-softmax for the target class
// and stores the negative log-likelihood for that sample.
__global__ void fused_cross_entropy_kernel(const float* predictions, const long* targets, float* losses_per_sample, int batch_size, int num_classes) {
    // Get the index of the current sample (row) to process
    int sample_idx = blockIdx.x;

    // Guard against out-of-bounds access if gridDim.x > batch_size
    if (sample_idx >= batch_size) {
        return;
    }

    // Dynamically allocated shared memory for reduction within a block.
    // It will be used for both max_val and sum_exp reductions.
    extern __shared__ float s_data[];

    // Initialize max_val for this thread's portion of the row
    float max_val_thread = -FLT_MAX;

    // First pass: Find the maximum value in the current row (sample)
    // Each thread processes a subset of the `num_classes` elements.
    for (int i = threadIdx.x; i < num_classes; i += blockDim.x) {
        float val = predictions[sample_idx * num_classes + i];
        max_val_thread = fmaxf(max_val_thread, val);
    }

    // Reduce max_val across all threads in the block using shared memory
    s_data[threadIdx.x] = max_val_thread;
    __syncthreads(); // Ensure all threads have written their partial max_val

    // Tree reduction for max_val
    for (unsigned int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] = fmaxf(s_data[threadIdx.x], s_data[threadIdx.x + s]);
        }
        __syncthreads(); // Synchronize after each reduction step
    }
    float max_val_row = s_data[0]; // Thread 0 now holds the maximum value for the entire row

    // Second pass: Compute the sum of exponentials (sum_exp) for the current row
    // using the numerically stable `max_val_row`.
    float sum_exp_thread = 0.0f;
    for (int i = threadIdx.x; i < num_classes; i += blockDim.x) {
        float val = predictions[sample_idx * num_classes + i];
        sum_exp_thread += expf(val - max_val_row);
    }

    // Reduce sum_exp across all threads in the block using shared memory
    s_data[threadIdx.x] = sum_exp_thread;
    __syncthreads(); // Ensure all threads have written their partial sum_exp

    // Tree reduction for sum_exp
    for (unsigned int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }
    float sum_exp_row = s_data[0]; // Thread 0 now holds the sum of exponentials for the entire row

    // Only thread 0 of the block computes the final loss for the sample
    if (threadIdx.x == 0) {
