# CUDA source code for fused Smooth L1 Loss calculation and reduction
smooth_l1_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void smooth_l1_kernel(const float* __restrict__ p, const float* __restrict__ t, double* __restrict__ out, size_t n) {
    double local_sum = 0.0;
    size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
    size_t stride = (size_t)blockDim.x * gridDim.x;

    // Element-wise fused calculation and partial sum
    for (size_t i = idx; i < n; i += stride) {
        float diff = p[i] - t[i];
        float abs_diff = fabsf(diff);
        float res = (abs_diff < 1.0f) ? (0.5f * diff * diff) : (abs_diff - 0.5f);
        local_sum += (double)res;
    }

    // Warp-level reduction
    for (int offset = 16; offset > 0; offset /= 2) {
        local_sum += __shfl_down_sync(0xFFFFFFFF, local_sum, offset);
    }

    // Shared memory for block-level reduction
    __shared__ double shared_sum[32]; // Max 32 warps in a block of 1024 threads
    int warp_id = threadIdx.x / 32;
    if ((threadIdx.x & 31) == 0) {
        shared_sum[warp_id] = local_sum;
    }
    __syncthreads();

    // Block-level reduction using the first warp
    if (threadIdx.x < 32) {
        double block_sum = (threadIdx.x < (blockDim.x / 32)) ? shared_sum[threadIdx.x] : 0.0;
        for (int offset = 16; offset > 0; offset /= 2) {
            block_sum += __shfl_down_sync(0xFFFFFFFF, block_sum, offset);
        }
        // Atomic sum to final result (Atomic double requires Compute Capability 6.0+)
        if (threadIdx.x == 0) {
            atomicAdd(out, block_sum);
        }
    }
}

torch::Tensor smooth_l1_cuda(torch::Tensor predictions, torch::Tensor targets) {
    // Ensure inputs are contiguous for proper pointer indexing
    auto p = predictions.contiguous();
    auto t = targets.contiguous();
    auto n = (size_t)p.numel();

    // Use double precision for the global accumulator to maintain precision for large N
    auto options = torch::TensorOptions().dtype(torch::kFloat64).device(p.device());
    auto out = torch::zeros({1}, options);

    const int threads = 256;
    const int num_blocks = 1024; // Use grid-stride pattern for efficiency

    smooth_l1_kernel<<<num_blocks, threads>>>(
        p.data_ptr<float>(),
        t.data_ptr<float>(),
        out.data_ptr<double>(),
