#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void attention_kernel(const float* __restrict__ Q,
                                 const float* __restrict__ K,
                                 const float* __restrict__ V,
                                 float* __restrict__ out,
                                 int S, int D, float scale) {
    // Each block handles one row of the output matrix (Batch b, Head h, Query i)
    int i = blockIdx.x; // row of Q (sequence index)
    int h = blockIdx.y; // head index
    int b = blockIdx.z; // batch index
    int tid = threadIdx.x;

    // Shared memory allocation: 
    // s_q: stores the current Query row (D=1024 elements)
    // s_p: stores the calculated attention weights for one row (S=512 elements)
    extern __shared__ float s_mem[];
    float* s_q = s_mem;           
    float* s_p = &s_mem[1024];    

    __shared__ float warp_sums[32]; 
    __shared__ float shared_inv_sum;
    __shared__ float shared_max;

    int head_offset = (b * gridDim.y + h) * S * D;

    // 1. Load the specific Q row for this block into shared memory
    for (int d = tid; d < D; d += blockDim.x) {
        s_q[d] = Q[head_offset + i * D + d];
    }
    __syncthreads();

    // 2. Compute Attention Scores S_ij = (Q_i dot K_j) * scale
    // We compute this for all j in [0, S-1]. To ensure coalesced global memory access,
    // the threads in the block work together on each j.
    for (int j = 0; j < S; ++j) {
        float partial = 0.0f;
        const float* k_row = &K[head_offset + j * D];
        for (int d = tid; d < D; d += blockDim.x) {
            partial += s_q[d] * k_row[d];
        }

        // Block-level reduction for the dot product
        for (int mask = 16; mask > 0; mask /= 2)
            partial += __shfl_xor_sync(0xffffffff, partial, mask);

        int lane = tid % 32;
        int wid = tid / 32;
        if (lane == 0) warp_sums[wid] = partial;
        __syncthreads();

        if (tid < 32) {
            float s = (tid < (blockDim.x / 32)) ? warp_sums[tid] : 0.0f;
            for (int mask = 16; mask > 0; mask /= 2)
                s += __shfl_xor_sync(0xffffffff, s, mask);
            if (tid == 0) s_p[j] = s * scale;
        }
        __syncthreads();
    }

    // 3. Compute Softmax (Max reduction, then Exp, then Sum reduction)
    // For S=512, we can perform this sequentially on one thread for simplicity and stability
    if (tid == 0) {
        float mv = -1e20f;
        for (int j = 0; j < S; ++j) {
            if (s_p[j] > mv) mv = s_p[j];
        }
        shared_max = mv;

        float es = 0.0f;
        for (int j = 0; j < S; ++j) {
            float e = expf(s_p[j] - mv);
            s_p[j] = e;
            es += e;
        }
        shared_inv_sum = 1.0f / es;
    }
    __syncthreads();

    // 4. Compute Weighted Sum: O_id = sum_j (P_ij * V_jd)
    // Parallelize across the dimension d to ensure coalesced writes and loads
    float inv_s = shared_inv_sum;
    for (int d = tid; d < D; d += blockDim.x) {
        float res = 0.0f;
        for (int j = 0; j < S; ++j) {
            res += s_p[j] * V[head_offset + j * D + d];
        }
        out[head_offset + i * D + d] = res * inv_s;
    }
}

