# Define the custom CUDA kernel for Flash Attention (Forward pass)
# This kernel implements the online softmax algorithm to compute attention in one fused pass.
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

// Helper for warp reduction
__device__ inline float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) 
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Helper for block reduction
__device__ inline float blockReduceSum(float val) {
    static __shared__ float shared[32]; 
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);     

    if (lane == 0) shared[wid] = val; 

    __syncthreads();              

    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0.0f;

    if (wid == 0) val = warpReduceSum(val); 

    return val;
}

__global__ void flash_attn_fwd_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    const int batch_size,
    const int num_heads,
    const int seq_len,
    const int head_dim,
    const float scale
) {
    // Grid configuration:
    // x: Sequence Length (N) -> One block per query row
    // y: Num Heads (H)
    // z: Batch Size (B)

    int i = blockIdx.x; // Query row index
    int h = blockIdx.y; // Head index
    int b = blockIdx.z; // Batch index

    // Check bounds (though grid should match)
    if (i >= seq_len || h >= num_heads || b >= batch_size) return;

    // Strides
    long long stride_b = (long long)num_heads * seq_len * head_dim;
    long long stride_h = (long long)seq_len * head_dim;
    long long stride_n = head_dim;

    // Base pointers for this head
    long long offset = b * stride_b + h * stride_h;
    const __half* Q_head = Q + offset;
    const __half* K_head = K + offset;
    const __half* V_head = V + offset;
    __half* O_head = O + offset;

    // Load Q[i] into shared memory
    // Shared memory size passed at launch should be head_dim * sizeof(half)
    extern __shared__ __half q_shm[];

    for (int d = threadIdx.x; d < head_dim; d += blockDim.x) {
        q_shm[d] = Q_head[i * stride_n + d];
    }
    __syncthreads();

    // Accumulators for online softmax
    // m_i: running max
    // l_i: running sum of exp
    // o_acc: running output vector (accumulated in float)
    float m_i = -INFINITY;
    float l_i = 0.0f;

    // Each thread holds a part of the output row (D=1024, Block=256 -> 4 elems/thread)
    // We use a small array to hold these registers.
    float o_acc[8] = {0.0f}; 

    // Loop over key/value sequence (j)
    for (int j = 0; j < seq_len; ++j) {
        // 1. Compute dot product score = Q[i] . K[j]
        float dot = 0.0f;
        const __half* K_vec = K_head + j * stride_n;

        for (int d = threadIdx.x; d < head_dim; d += blockDim.x) {
            float q_val = __half2float(q_shm[d]);
            float k_val = __half2float(K_vec[d]);
            dot += q_val * k_val;
        }

        // Sum across threads
        float score = blockReduceSum(dot);
        score *= scale;

        // Broadcast score from thread 0 to all threads
        __shared__ float s_score;
        if (threadIdx.x == 0) s_score = score;
        __syncthreads();
        score = s_score;

        // 2. Online Softmax Update
        // m_new = max(m_old, score)
        // l_new = l_old * exp(m_old - m_new) + exp(score - m_new)
        // O_new = O_old * exp(m_old - m_new) + V[j] * exp(score - m_new)

        float m_prev = m_i;
        m_i = fmaxf(m_prev, score);

        float exp_score = expf(score - m_i);
        float exp_prev = expf(m_prev - m_i);

        l_i = l_i * exp_prev + exp_score;

        // Update O accumulator
        const __half* V_vec = V_head + j * stride_n;
        for (int k = 0; k < 8; ++k) {
            int d = k * blockDim.x + threadIdx.x;
            if (d < head_dim) {
                float v_val = __half2float(V_vec[d]);
                o_acc[k] = o_acc[k] * exp_prev + v_val * exp_score;
            }
        }
    }

    // 3. Finalize and Store to Global Memory
    // O[i] = o_acc / l_i
    float inv_l = 1.0f / l_i;
    for (int k = 0; k < 8; ++k) {
        int d = k * blockDim.x + threadIdx.x;
        if (d < head_dim) {
            O_head[i * stride_n + d] = __float2half(o_acc[k] * inv_l);
        }
    }
