#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Fused KL Divergence Kernel
// Computes sum(targets * (log(targets) - log(predictions)))
// Handles the reduction efficiently on GPU
__global__ void fused_kl_div_kernel(
    const float* __restrict__ predictions, 
    const float* __restrict__ targets, 
    float* output, 
    int numel
) {
    // Grid-stride loop setup
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;
    int stride = blockDim.x * gridDim.x;

    float local_sum = 0.0f;

    // Iterate over the data
    for (int i = idx; i < numel; i += stride) {
        float p = predictions[i];
        float t = targets[i];

        // KL Divergence formula: y_true * (log(y_true) - log(y_pred))
        // If target is 0, the term is 0 (limit x->0 of x*log(x) is 0)
        // We assume predictions > 0 (output of softmax)
        if (t > 0.0f) {
            local_sum += t * (logf(t) - logf(p));
        }
    }

    // Block-level reduction using shared memory
    extern __shared__ float sdata[];
    sdata[tid] = local_sum;
    __syncthreads();

    // Reduce within the block
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Atomic accumulation of block results to global memory
    if (tid == 0) {
        atomicAdd(output, sdata[0]);
    }
}

