# Define the fused CUDA kernel for Softmax followed by two MaxPool3d operations.
# Given that pool_kernel_size is 2, two applications of MaxPool3d(2) results 
# in a spatial reduction equivalent to a single MaxPool3d(4) with stride 4.
fused_softmax_pool_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_softmax_pool_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W,
    int D2, int H2, int W2) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial_size_out = D2 * H2 * W2;
    int total_elements = N * C * spatial_size_out;

    if (idx >= total_elements) return;

    // Decode thread index to N, C, D2, H2, W2
    int temp = idx;
    int w2 = temp % W2; temp /= W2;
    int h2 = temp % H2; temp /= H2;
    int d2 = temp % D2; temp /= D2;
    int c = temp % C; temp /= C;
    int n = temp;

    float max_softmax_val = -1.0e20f;
    int spatial_stride = D * H * W;

    // The fused window for two MaxPool3d(2) is 4x4x4 with stride 4
    for (int di = 0; di < 4; ++di) {
        int d = d2 * 4 + di;
        if (d >= D) continue;
        for (int hi = 0; hi < 4; ++hi) {
            int h = h2 * 4 + hi;
            if (h >= H) continue;
            for (int wi = 0; wi < 4; ++wi) {
                int w = w2 * 4 + wi;
                if (w >= W) continue;

                // Index for channel 0 at current (n, d, h, w)
                int base_idx_c0 = (((n * C) * D + d) * H + h) * W + w;

