                    float v = input[base_idx_c0 + k * spatial_stride];
                    if (v > max_channel_val) max_channel_val = v;
                }

                // 2. Compute Sum of Exponentials across channels
                float sum_exp = 0.0f;
                for (int k = 0; k < C; ++k) {
                    sum_exp += expf(input[base_idx_c0 + k * spatial_stride] - max_channel_val);
