                float target_val = input[base_idx_c0 + c * spatial_stride];
                float softmax_val = expf(target_val - max_channel_val) / sum_exp;

                // 4. Update Running Max for pooling
                if (softmax_val > max_softmax_val) max_softmax_val = softmax_val;
            }
