import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code
# Fuses Softmax (dim=1) and two MaxPool3d(kernel=2, stride=2) operations.
# Effectively performs Softmax then MaxPool3d(kernel=4, stride=4).
# Optimized for small channel counts (C <= 32) using warp-level primitives.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_softmax_pool_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W,
    int D_out, int H_out, int W_out) {

    // Grid mapping:
    // One block handles one spatial output location (n, d_out, h_out, w_out) across all channels.
    // We flatten the spatial output dimensions to map to blockIdx.x

    int idx = blockIdx.x;
    int area_out = D_out * H_out * W_out;

    int n = idx / area_out;
    int rem = idx % area_out;

    int w_out = rem % W_out;
    rem /= W_out;
    int h_out = rem % H_out;
    int d_out = rem / H_out;

    // Channel index from thread
    int c = threadIdx.x;

    // Effective Pooling Window: 4x4x4 (composition of two 2x2 pools)
    // Stride: 4
    const int k_size = 4;
    const int stride = 4;

    int d_start = d_out * stride;
    int h_start = h_out * stride;
    int w_start = w_out * stride;

    // Initialize local max accumulator for pooling
    // Threads with c >= C will carry -FLT_MAX and not write output
    float pool_max = -FLT_MAX;

    // Iterate over the 4x4x4 input window
    for (int kd = 0; kd < k_size; ++kd) {
        int d_in = d_start + kd;
        if (d_in >= D) continue;

        for (int kh = 0; kh < k_size; ++kh) {
            int h_in = h_start + kh;
            if (h_in >= H) continue;

            for (int kw = 0; kw < k_size; ++kw) {
                int w_in = w_start + kw;
                if (w_in >= W) continue;

                // Calculate input flat index
                // Input Layout: N, C, D, H, W
                // We use long long to prevent overflow for large tensors, though likely unnecessary for this specific size
                long long spatial_offset = (long long)d_in * H * W + (long long)h_in * W + w_in;
                long long input_idx = (long long)n * C * D * H * W + (long long)c * D * H * W + spatial_offset;

                // Load input value
                // Mask out-of-bounds channels
                float val = (c < C) ? input[input_idx] : -FLT_MAX;

                // --- Softmax Calculation (Stable) ---

                // 1. Find max across channels for this pixel
                float pixel_max = val;
                // Warp reduction (assuming warp size 32)
                #pragma unroll
                for (int offset = 16; offset > 0; offset /= 2) {
                    pixel_max = fmaxf(pixel_max, __shfl_xor_sync(0xFFFFFFFF, pixel_max, offset));
                }

                // 2. Compute Sum of Exponentials
                float val_exp = 0.0f;
                if (c < C) {
                    val_exp = expf(val - pixel_max);
                }

                float sum_exp = val_exp;
                #pragma unroll
                for (int offset = 16; offset > 0; offset /= 2) {
                    sum_exp += __shfl_xor_sync(0xFFFFFFFF, sum_exp, offset);
                }

                // 3. Compute Softmax Probability
                // Division by zero risk handled by logic (sum_exp > 0 if any input is valid)
                float softmax_val = val_exp / sum_exp;

                // --- Update Pool Max ---
                if (c < C) {
                    pool_max = fmaxf(pool_max, softmax_val);
                }
            }
        }
    }

    // Write output
    if (c < C) {
        long long out_idx = (long long)n * C * area_out + (long long)c * area_out + (long long)d_out * H_out * W_out + (long long)h_out * W_out + w_out;
        output[out_idx] = pool_max;
    }
