#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    const int N,
    const int C,
    const int D,
    const int H,
    const int W,
    const float scaling_factor) {

    // Each thread processes one spatial pixel (n, h, w)
    // Grid maps to flattened spatial dimensions
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial_dim = H * W;
    int total_threads = N * spatial_dim;

    if (idx >= total_threads) return;

    // Decode linear index into (n, h, w)
    // idx = n * (H * W) + h * W + w
    int w = idx % W;
    int h = (idx / W) % H;
    int n = idx / spatial_dim;

    // Shared memory for storing channel values for this pixel
    // We need to store C values per thread to compute Softmax
    // Dynamic shared memory size: blockDim.x * C * sizeof(float)
    extern __shared__ float s_data[];
    float* vals = &s_data[threadIdx.x * C];

    // Calculate strides for input tensor (N, C, D, H, W)
    // Standard contiguous layout
    int stride_d = H * W;
    int stride_c = D * H * W;
    int stride_n = C * D * H * W;

