# Define the custom CUDA kernel for the fused post-processing operations.
# The original model performs a sequence of element-wise operations after the convolution:
# 1. x = x + bias
# 2. original_x = x (before adding bias, but detached?)
#    Wait, the original code is:
#    x = conv(x)
#    original_x = x.clone().detach()
#    x = x + bias
#    x = x + original_x
#    x = x * original_x
#    x = x + original_x
# 
# Let val = conv output at some index.
# original_x = val
# Step 1: x = val + bias
# Step 2: x = (val + bias) + val = 2*val + bias
# Step 3: x = (2*val + bias) * val = 2*val^2 + bias*val
# Step 4: x = (2*val^2 + bias*val) + val = 2*val^2 + (bias + 1)*val
#
# This fused kernel computes this polynomial directly, avoiding multiple memory accesses and kernel launches.

fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_post_processing_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ bias, 
    float* __restrict__ out, 
    int total_elements, 
    int spatial_size, 
    int channels) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // x tensor layout is [N, C, D, H, W]
        // bias tensor layout is [C, 1, 1, 1] (effectively just C elements linearly)

        // We need to map the linear index 'idx' to the channel index 'c'.
        // spatial_size = D * H * W
        // The index structure is: n * (C * spatial_size) + c * spatial_size + spatial_offset
        // So, (idx / spatial_size) gives (n * C + c)
        // Then, % channels gives c.

        int c = (idx / spatial_size) % channels;

        float val = x[idx];
        float b = bias[c];

        // Compute: 2*val^2 + (b + 1)*val
        out[idx] = 2.0f * val * val + (b + 1.0f) * val;
    }
}

torch::Tensor fused_post_processing_cuda(torch::Tensor x, torch::Tensor bias) {
