stats_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void stats_kernel(const float* __restrict__ x, 
                             float* __restrict__ sums, 
                             float* __restrict__ sum_sqs, 
                             int spatial_size,
                             int C) {
    // blockIdx.x corresponds to channel c
    // blockIdx.y corresponds to batch n
    // Grid dimensions: (C, N, 1)

    int n = blockIdx.y;
    int c = blockIdx.x;

    // Offset to the specific channel plane
    // x is shape (N, C, Spatial)
    // Use long long for offset to prevent potential overflow for very large tensors
    long long offset = (long long)n * C * spatial_size + (long long)c * spatial_size;
    const float* input_ptr = x + offset;

    float local_sum = 0.0f;
    float local_sq_sum = 0.0f;

    // Iterate over spatial dimensions
    // We use a simple grid-stride loop, although with one block per channel,
    // the stride is just blockDim.x.
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        float val = input_ptr[i];
        local_sum += val;
        local_sq_sum += val * val;
    }

    // Block reduction using shared memory
    __shared__ float s_sum[256];
    __shared__ float s_sq[256];

    // Initialize shared memory
    if (threadIdx.x < 256) {
        s_sum[threadIdx.x] = local_sum;
        s_sq[threadIdx.x] = local_sq_sum;
    }
    __syncthreads();

    // Reduction tree (assuming block size 256)
    if (threadIdx.x < 128) { s_sum[threadIdx.x] += s_sum[threadIdx.x + 128]; s_sq[threadIdx.x] += s_sq[threadIdx.x + 128]; } __syncthreads();
    if (threadIdx.x < 64)  { s_sum[threadIdx.x] += s_sum[threadIdx.x + 64];  s_sq[threadIdx.x] += s_sq[threadIdx.x + 64]; } __syncthreads();
    if (threadIdx.x < 32)  { s_sum[threadIdx.x] += s_sum[threadIdx.x + 32];  s_sq[threadIdx.x] += s_sq[threadIdx.x + 32]; } __syncthreads();

    // Warp reduction for the last 32 threads
    if (threadIdx.x < 32) {
        volatile float* v_sum = s_sum;
        volatile float* v_sq = s_sq;
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 16]; v_sq[threadIdx.x] += v_sq[threadIdx.x + 16];
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 8];  v_sq[threadIdx.x] += v_sq[threadIdx.x + 8];
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 4];  v_sq[threadIdx.x] += v_sq[threadIdx.x + 4];
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 2];  v_sq[threadIdx.x] += v_sq[threadIdx.x + 2];
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 1];  v_sq[threadIdx.x] += v_sq[threadIdx.x + 1];
    }

    // Write result to global memory
    if (threadIdx.x == 0) {
        int out_idx = n * C + c;
        sums[out_idx] = s_sum[0];
        sum_sqs[out_idx] = s_sq[0];
    }
