    stats_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        sums.data_ptr<float>(),
        sum_sqs.data_ptr<float>(),
        spatial_size,
        C
    );

    return {sums, sum_sqs};
}
"""

stats_cpp_source = "std::vector<torch::Tensor> compute_stats_cuda(torch::Tensor x);"

# Compile the inline CUDA code
stats_module = load_inline(
    name="stats_module",
    cpp_sources=stats_cpp_source,
    cuda_sources=stats_source,
    functions=["compute_stats_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D convolution, then computes the mean of the GroupNormalized output
    without fully materializing the normalized tensor.
    """
    def __init__(self, in_channels, out_channels, kernel_size, num_groups):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.group_norm = nn.GroupNorm(num_groups, out_channels)
        self.num_groups = num_groups
        self.stats_module = stats_module

    def forward(self, x):
        # 1. 3D Convolution (Standard PyTorch/cuDNN is highly optimized)
        x = self.conv(x)

        # Shape: (Batch, Channels, D, H, W)
        N, C, D, H, W = x.shape
        spatial_size = D * H * W

        # 2. Optimized Reduction
        # We replace the sequence GroupNorm -> Mean with a fused analytical calculation.
        # This avoids writing the intermediate (N, C, D, H, W) tensor back to global memory,
        # saving significant memory bandwidth.

        # Calculate sums and squared sums per channel using CUDA kernel
        sums, sum_sqs = self.stats_module.compute_stats_cuda(x)

        # Retrieve GroupNorm Parameters
        gamma = self.group_norm.weight # Shape (C)
        beta = self.group_norm.bias    # Shape (C)
        eps = self.group_norm.eps
        G = self.num_groups
        K = C // G # Channels per group

        # 3. Compute Group Statistics in PyTorch (efficient for small tensors)
        # Reshape stats to (N, G, K) to aggregate per group
        sums_g = sums.view(N, G, K).sum(dim=2)
        sum_sqs_g = sum_sqs.view(N, G, K).sum(dim=2)

        group_elements = K * spatial_size
        mu_g = sums_g / group_elements
        # Biased variance estimate (standard for GroupNorm)
        var_g = (sum_sqs_g / group_elements) - mu_g.pow(2)

        # Numerical stability clamp
        var_g = torch.clamp(var_g, min=0.0)
        rstd_g = torch.rsqrt(var_g + eps) # Shape (N, G)

        # 4. Analytic Calculation of Final Mean
        # Formula: Mean_Final = (1/C) * Sum(Beta) + (1/(C*Spatial)) * Sum_All_Groups [ rstd_g * Sum_Channels_In_Group [ Gamma_c * (Sum_c - Spatial * Mu_g) ] ]

        # Expand group stats to channel dimension
        mu_g_expanded = mu_g.view(N, G, 1).expand(N, G, K).reshape(N, C)
        rstd_g_expanded = rstd_g.view(N, G, 1).expand(N, G, K).reshape(N, C)

        # Calculate the weighted sum term: gamma * (x - mu) * rstd
        # Sum_pixels(gamma * (x - mu) * rstd) = gamma * rstd * (Sum_pixels(x) - Spatial * mu)
        centered_sums = sums - (spatial_size * mu_g_expanded)
        weighted_sums = gamma * rstd_g_expanded * centered_sums

        # Sum over all channels (dim 1) to get numerator for the variable part
        total_weighted_sum = weighted_sums.sum(dim=1) # Shape (N)

        # Calculate final result
        mean_beta = beta.mean()
        result = mean_beta + total_weighted_sum / (C * spatial_size)

        return result

