    // Each thread will compute one (n, h, w) output element.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Ensure the thread is within the bounds of the output tensor
    if (idx < N * H * W) {
        // Decompose the global index back into (n, h, w) coordinates
        int n = idx / (H * W);
        int hw_idx = idx % (H * W);
        int h = hw_idx / W;
        int w = hw_idx % W;

