import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels for fusing HardSwish, GroupNorm, and Spatial Mean
# We use two kernels:
# 1. stats_kernel: Computes Mean and Variance for each group in each sample. 
#    Also applies HardSwish on the fly to avoid reading/writing the large activation tensor.
# 2. fused_apply_kernel: Applies HardSwish, GroupNorm normalization (using stats), and reduces (sums) over spatial dimensions.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// HardSwish activation function: x * ReLU6(x + 3) / 6
__device__ inline float hard_swish(float x) {
    return x * fminf(fmaxf(x + 3.0f, 0.0f), 6.0f) / 6.0f;
}

// Kernel to calculate mean and inverse standard deviation for GroupNorm
// Fuses HardSwish activation into the read
__global__ void stats_kernel(const float* __restrict__ x, 
                             float* __restrict__ mean_out, 
                             float* __restrict__ invstd_out,
                             int N, int C, int S, int G) {
   // N=Batch, C=Channels, S=Spatial(D*H*W), G=NumGroups
   int n = blockIdx.x; 
   int g = blockIdx.y; 
   int channels_per_group = C / G;
   int c_start = g * channels_per_group;

   float sum = 0.0f;
   float sq_sum = 0.0f;

   // Total elements involved in one group's statistics
   int total_elements = channels_per_group * S;
   int tid = threadIdx.x;

   // Stride loop to accumulate sum and sum of squares
   for (int i = tid; i < total_elements; i += blockDim.x) {
       int c_local = i / S;
       int s = i % S;
       int c = c_start + c_local;
       // Flat index: B * (C*S) + C * S + S_idx
       int idx = n * C * S + c * S + s;

       float val = x[idx];
       float h = hard_swish(val); // Fuse activation
       sum += h;
       sq_sum += h * h;
   }

   // Block reduction using shared memory
   __shared__ float s_sum[256];
   __shared__ float s_sq_sum[256];

   s_sum[tid] = sum;
   s_sq_sum[tid] = sq_sum;
   __syncthreads();

   for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
       if (tid < offset) {
           s_sum[tid] += s_sum[tid + offset];
           s_sq_sum[tid] += s_sq_sum[tid + offset];
       }
       __syncthreads();
   }

   // Write result
   if (tid == 0) {
       float mu = s_sum[0] / total_elements;
       float var = (s_sq_sum[0] / total_elements) - (mu * mu);
       // Epsilon for GroupNorm is typically 1e-5
       float invstd = rsqrtf(fmaxf(var, 0.0f) + 1e-5f);

       int out_idx = n * G + g;
       mean_out[out_idx] = mu;
       invstd_out[out_idx] = invstd;
   }
}

// Kernel to apply HardSwish, GroupNorm, and compute Spatial Mean
__global__ void fused_apply_kernel(const float* __restrict__ x,
                                   const float* __restrict__ mean,
                                   const float* __restrict__ invstd,
                                   const float* __restrict__ gamma,
                                   const float* __restrict__ beta,
                                   float* __restrict__ out,
                                   int N, int C, int S, int G) {
    int n = blockIdx.x; // Batch index
    int c = blockIdx.y; // Channel index
    int g = c / (C/G);  // Group index

    // Load stats and parameters
    float mu = mean[n * G + g];
    float is = invstd[n * G + g];
    float gm = gamma[c];
    float bt = beta[c];

    float sum = 0.0f;
    int offset = n * C * S + c * S;

    // Iterate over spatial dimensions
    for (int s = threadIdx.x; s < S; s += blockDim.x) {
        float val = x[offset + s];
        float h = hard_swish(val);      // Re-compute activation
        float norm = (h - mu) * is;     // GroupNorm
        float y = norm * gm + bt;       // Affine
        sum += y;                       // Accumulate for Mean
    }

    // Block reduction for sum
    __shared__ float s_data[256];
    s_data[threadIdx.x] = sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_data[threadIdx.x] += s_data[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        out[n * C + c] = s_data[0];
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, int num_groups) {
    auto N = x.size(0);
    auto C = x.size(1);
    // Flatten spatial dimensions
    auto S = x.size(2) * x.size(3) * x.size(4);

    auto mean = torch::empty({N, num_groups}, x.options());
    auto invstd = torch::empty({N, num_groups}, x.options());
    auto out_sum = torch::empty({N, C}, x.options());

    const int threads = 256;

    // Pass 1: Compute statistics per group
    dim3 stats_grid(N, num_groups);
    stats_kernel<<<stats_grid, threads>>>(x.data_ptr<float>(), 
                                          mean.data_ptr<float>(), 
                                          invstd.data_ptr<float>(), 
                                          N, C, S, num_groups);

    // Pass 2: Apply operations and reduce spatial dimensions
    dim3 apply_grid(N, C);
    fused_apply_kernel<<<apply_grid, threads>>>(x.data_ptr<float>(), 
                                                mean.data_ptr<float>(), 
                                                invstd.data_ptr<float>(), 
                                                gamma.data_ptr<float>(), 
                                                beta.data_ptr<float>(), 
                                                out_sum.data_ptr<float>(), 
                                                N, C, S, num_groups);

    // Final division to get mean
    return out_sum / static_cast<float>(S);
}
