    int g = blockIdx.x % num_groups;
    int tid = threadIdx.x;

    __shared__ float shared_sum_ptr[32];
    __shared__ float shared_sq_sum_ptr[32];

    float thread_sum = 0.0f;
    float thread_sq_sum = 0.0f;

