import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused GroupNorm + HardTanh
# This kernel fuses the normalization statistics calculation, normalization, 
# affine transformation (gamma/beta), and the HardTanh activation into a single kernel.
# This reduces global memory reads/writes compared to executing them sequentially.
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_gn_hardtanh_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ y,
    int N,
    int C,
    int D,
    float eps,
    float min_val,
    float max_val) 
{
    // n: Batch index
    // g: Group index
    // d: Channel index within group (0 to D-1)

    int n = blockIdx.x;
    int g = blockIdx.y;
    int d = threadIdx.x;

    // Global channel index
    int c = g * D + d;
    // Flattened index for input/output
    int idx = n * C + c;

    // Load input
    float val = x[idx];

    // Shared memory for reduction: need space for D floats
    // We assume D (channels per group) fits in shared memory and is power of 2 for this simple reduction
    extern __shared__ float sdata[];

    // --- 1. Calculate Mean ---
    sdata[d] = val;
    __syncthreads();

    // Tree reduction for sum
    // Assumes blockDim.x (D) is a power of 2
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (d < s) {
            sdata[d] += sdata[d + s];
        }
        __syncthreads();
    }
    float mean = sdata[0] / D;
    __syncthreads();

    // --- 2. Calculate Variance ---
    float diff = val - mean;
    sdata[d] = diff * diff;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (d < s) {
            sdata[d] += sdata[d + s];
        }
        __syncthreads();
    }
    float var = sdata[0] / D;

    // --- 3. Normalization ---
    float inv_std = rsqrtf(var + eps);
    float norm = (val - mean) * inv_std;

    // --- 4. Affine Transformation ---
    float out = norm * gamma[c] + beta[c];

    // --- 5. HardTanh Activation ---
    if (out < min_val) out = min_val;
    else if (out > max_val) out = max_val;

    // Store result
    y[idx] = out;
}

