import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA source for the fused kernel
# Fuses: Add Bias -> Scale -> BatchNorm (Training with Stats Update)
# This reduces memory bandwidth significantly compared to separate operations.
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_gemm_post_proc_kernel(
    const float* __restrict__ input,       // (N, K) from GEMM (no bias added yet)
    float* __restrict__ output,            // (N, K)
    const float* __restrict__ bias,        // (K) Linear bias
    const float* __restrict__ scale,       // (K) Element-wise scale
    const float* __restrict__ bn_weight,   // (K) BN Gamma
    const float* __restrict__ bn_bias,     // (K) BN Beta
    float* __restrict__ running_mean,      // (K)
    float* __restrict__ running_var,       // (K)
    int N, 
    int K,
    float eps, 
    float momentum) {

    // Grid assumes 1 block per feature K
    int k = blockIdx.x;
    int tid = threadIdx.x;

    if (k >= K) return;

    // Load feature-specific params
    float b = bias[k];
    float s = scale[k];

    // Shared memory for reduction. Size: 1024 floats (4KB)
    extern __shared__ float smem[];

    float val = 0.0f;

    // 1. Load Input, Apply Linear Bias and Scale
    // Each thread loads one element of the column (strided access, but necessary without transpose)
    if (tid < N) {
        val = input[tid * K + k];
        val = (val + b) * s;
        smem[tid] = val;
    } else {
        smem[tid] = 0.0f;
    }
    __syncthreads();

    // 2. Compute Mean (Parallel Reduction)
    for (int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            smem[tid] += smem[tid + stride];
        }
        __syncthreads();
    }
    float mean = smem[0] / N;

    // Synchronize to ensure 'smem[0]' is read by all before overwriting
    __syncthreads();

    // 3. Compute Variance
    float diff_sq = 0.0f;
    if (tid < N) {
        float diff = val - mean;
        diff_sq = diff * diff;
        smem[tid] = diff_sq;
    } else {
        smem[tid] = 0.0f;
    }
    __syncthreads();

    // Reduction for variance
    for (int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            smem[tid] += smem[tid + stride];
        }
        __syncthreads();
    }
    float sum_sq = smem[0];
    float var = sum_sq / N; // Biased variance

    // 4. Update Running Stats (Thread 0 only)
    if (tid == 0) {
        float unbiased_var = sum_sq / (N - 1);
        float rm = running_mean[k];
        float rv = running_var[k];

        running_mean[k] = (1.0f - momentum) * rm + momentum * mean;
        running_var[k] = (1.0f - momentum) * rv + momentum * unbiased_var;
    }

    // 5. Normalize and Apply BN Weight/Bias
    float inv_std = rsqrtf(var + eps);
    float bn_w = bn_weight[k];
    float bn_b = bn_bias[k];

    if (tid < N) {
        float norm = (val - mean) * inv_std;
        float res = norm * bn_w + bn_b;
        output[tid * K + k] = res;
    }
}

torch::Tensor fused_forward_cuda(
    torch::Tensor input, 
    torch::Tensor bias, 
    torch::Tensor scale, 
    torch::Tensor bn_weight, 
    torch::Tensor bn_bias, 
