    torch::Tensor running_var, 
    float eps, 
    float momentum) {

    int N = input.size(0);
    int K = input.size(1);

    auto output = torch::empty_like(input);

    // Optimize for N=1024 as per architecture spec.
    int threads = 1024;
    int blocks = K;
