fused_layernorm_gelu_scale_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrt, tanh

// GELU approximation (standard PyTorch GELU)
// 0.5 * x * (1 + tanh(sqrt(2 / pi) * (x + 0.044715 * x^3)))
__device__ float gelu_activation(float x) {
    const float M_SQRT2_PI = 0.7978845608028654f; // sqrt(2 / pi)
    const float CUBIC_TERM_COEFF = 0.044715f;
    float x_cubed = x * x * x;
    float tanh_arg = M_SQRT2_PI * (x + CUBIC_TERM_COEFF * x_cubed);
    return 0.5f * x * (1.0f + tanhf(tanh_arg));
}

// Kernel 1: Compute Mean and Variance for LayerNorm
// Each block processes one (B, C, D, H) slice.
// Threads within the block compute partial sums and then reduce them using shared memory.
__global__ void fused_layernorm_gelu_scale_mean_var_kernel(
    const float* x_ptr,
    float* mean_ptr,
    float* rstd_ptr,
    int B, int C, int D, int H, int W,
    float eps) {

    // blockIdx.x maps to the slice index (b, c, d, h)
    int slice_idx = blockIdx.x;

    // Calculate b, c, d, h from slice_idx
    int b = slice_idx / (C * D * H);
    int c = (slice_idx / (D * H)) % C;
    int d = (slice_idx / H) % D;
    int h = slice_idx % H;

    // Accumulators for sum and sum of squares for the current thread
    float sum_val = 0.0f;
    float sum_sq_val = 0.0f;

    // Grid-stride loop within the block to process all W elements
    // Each thread processes multiple elements if W > blockDim.x
    for (int w = threadIdx.x; w < W; w += blockDim.x) {
        int x_idx = b * (C * D * H * W) + c * (D * H * W) + d * (H * W) + h * W + w;
        float val = x_ptr[x_idx];
        sum_val += val;
        sum_sq_val += val * val;
    }

    // Shared memory for block-wise reduction
    extern __shared__ float s_data[];
    float* s_sum = s_data;
    float* s_sum_sq = s_data + blockDim.x;

    // Store partial sums in shared memory
    s_sum[threadIdx.x] = sum_val;
    s_sum_sq[threadIdx.x] = sum_sq_val;
    __syncthreads();

    // Perform parallel reduction within the block
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Only the first thread in the block writes the final mean and rstd
    if (threadIdx.x == 0) {
        float total_sum = s_sum[0];
        float total_sum_sq = s_sum_sq[0];

        float mean = total_sum / W;
        float var = total_sum_sq / W - mean * mean;
        if (var < 0) var = 0; // Handle potential floating point inaccuracies

        mean_ptr[slice_idx] = mean;
        rstd_ptr[slice_idx] = rsqrtf(var + eps); // Reciprocal standard deviation
    }
}

// Kernel 2: Apply normalization, GELU activation, and scaling
// Each thread processes one element of the output tensor.
__global__ void fused_layernorm_gelu_scale_apply_kernel(
    const float* x_ptr,
    const float* mean_ptr,
    const float* rstd_ptr,
    const float* gamma_ptr,
    const float* beta_ptr,
    float* out_ptr,
    int B, int C, int D, int H, int W,
    float scaling_factor) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = B * C * D * H * W;

    if (idx < total_elements) {
        // Calculate b, c, d, h, w from global index
        int b = idx / (C * D * H * W);
        int c = (idx / (D * H * W)) % C;
        int d = (idx / (H * W)) % D;
        int h = (idx / W) % H;
        int w = idx % W;

        // Index for mean and rstd (per slice)
        int slice_idx = b * (C * D * H) + c * (D * H) + d * H + h;

        float val = x_ptr[idx];
        float mean = mean_ptr[slice_idx];
        float rstd = rstd_ptr[slice_idx];

        // Gamma and beta are applied element-wise along the normalized dimension (W)
        float gamma = gamma_ptr[w]; 
        float beta = beta_ptr[w];

        // 1. Layer Normalization
        float normalized_val = (val - mean) * rstd;
        float scaled_shifted_val = normalized_val * gamma + beta;

        // 2. GELU Activation
        float gelu_val = gelu_activation(scaled_shifted_val);

        // 3. Scaling
        out_ptr[idx] = gelu_val * scaling_factor;
    }
}

