import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Swish + Add Bias + GroupNorm
# This kernel fuses the element-wise operations and the GroupNorm reduction
# to minimize memory bandwidth usage (Load once, Compute, Store once).
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_swish_bias_gn_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    float* __restrict__ out,
    int N, int C, int G, int channels_per_group) {

    // One block per row (sample) ensures we can use shared memory for the row statistics
    int row = blockIdx.x;
    if (row >= N) return;

    int offset = row * C;
    const float* row_x = x + offset;
    float* row_out = out + offset;

    // Shared memory allocation
    // s_data: stores the intermediate row data after Swish + Bias (Size: C floats)
    // s_mean: stores the mean for each group (Size: G floats)
    // s_rstd: stores the reciprocal standard deviation for each group (Size: G floats)
    extern __shared__ float s_mem[];
    float* s_data = s_mem;
    float* s_mean = s_data + C;
    float* s_rstd = s_mean + G;

    // -------------------------------------------------------------------------
    // Phase 1: Load Input, Apply Swish, Add Custom Bias, Store to Shared Memory
    // -------------------------------------------------------------------------
    for (int i = threadIdx.x; i < C; i += blockDim.x) {
        float val = row_x[i];
        float b = bias[i];

        // Swish Activation: x * sigmoid(x)
        float sig = 1.0f / (1.0f + expf(-val));
        val = val * sig;

        // Add Bias
        val = val + b;

        // Store to shared memory for GroupNorm
        s_data[i] = val;
    }

    __syncthreads();

    // -------------------------------------------------------------------------
    // Phase 2: Compute Group Statistics (Mean and Variance)
    // -------------------------------------------------------------------------
    // We have G groups. Assign threads to calculate stats for each group.
    for (int g = threadIdx.x; g < G; g += blockDim.x) {
        int g_start = g * channels_per_group;
        float sum = 0.0f;
        float sqsum = 0.0f;

        // Iterate over channels in the current group
        for (int k = 0; k < channels_per_group; ++k) {
            float v = s_data[g_start + k];
            sum += v;
            sqsum += v * v;
        }

        float mean = sum / float(channels_per_group);
        float var = sqsum / float(channels_per_group) - mean * mean;

        s_mean[g] = mean;
        // GroupNorm epsilon is typically 1e-5
        s_rstd[g] = rsqrtf(max(var, 1e-5f)); 
    }

    __syncthreads();

    // -------------------------------------------------------------------------
    // Phase 3: Normalize, Apply Affine Transform, and Write Output
    // -------------------------------------------------------------------------
    for (int i = threadIdx.x; i < C; i += blockDim.x) {
        int g = i / channels_per_group; // Determine which group this channel belongs to

        float val = s_data[i];
        float mean = s_mean[g];
        float rstd = s_rstd[g];

        // Normalize
        float norm = (val - mean) * rstd;

        // Apply GroupNorm affine parameters (gamma, beta)
        float gamma = gn_weight[i];
        float beta = gn_bias[i];

        row_out[i] = norm * gamma + beta;
    }
}

torch::Tensor fused_forward_cuda(
    torch::Tensor x,
    torch::Tensor bias,
