#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

// Helper function for block-wide reduction (max)
// Assumes s_data is shared memory of size blockDim.x
__device__ float block_reduce_max(float val, volatile float* s_data) {
    s_data[threadIdx.x] = val;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] = fmaxf(s_data[threadIdx.x], s_data[threadIdx.x + s]);
        }
        __syncthreads();
    }
    return s_data[0];
}

// Helper function for block-wide reduction (sum)
// Assumes s_data is shared memory of size blockDim.x
__device__ float block_reduce_sum(float val, volatile float* s_data) {
    s_data[threadIdx.x] = val;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads();
    }
    return s_data[0];
}

__global__ void clamp_spatial_softmax_scale_kernel(
    const float* input, float* output, const float* scale_ptr,
    float clamp_min, float clamp_max,
    int B, int C, int D, int H, int W) {

    int DHW = D * H * W;
    int batch_channel_idx = blockIdx.x; // Each block handles one (batch, channel) slice
    int batch_idx = batch_channel_idx / C;
    int channel_idx = batch_channel_idx % C;

    const float* input_slice_ptr = input + (batch_idx * C + channel_idx) * DHW;
    float* output_slice_ptr = output + (batch_idx * C + channel_idx) * DHW;
    float scale_val = scale_ptr[channel_idx]; // scale_ptr is a 1D array of size C

    // Dynamically allocated shared memory for reductions
    extern __shared__ float s_data[]; 

    // Phase 1: Find Max value in the slice (after clamping)
    float thread_max_val = -FLT_MAX; // Initialize with smallest possible float
    for (int i = threadIdx.x; i < DHW; i += blockDim.x) {
        float val = input_slice_ptr[i];
        float clamped_val = fmaxf(clamp_min, fminf(clamp_max, val));
        thread_max_val = fmaxf(thread_max_val, clamped_val);
    }
    float block_max_val = block_reduce_max(thread_max_val, s_data);

    // Phase 2: Compute Sum of Exponentials
    float thread_sum_exp = 0.0f;
    for (int i = threadIdx.x; i < DHW; i += blockDim.x) {
        float val = input_slice_ptr[i];
        float clamped_val = fmaxf(clamp_min, fminf(clamp_max, val));
        thread_sum_exp += expf(clamped_val - block_max_val);
    }
    float block_sum_exp = block_reduce_sum(thread_sum_exp, s_data);

    // Phase 3: Final calculation and store
    for (int i = threadIdx.x; i < DHW; i += blockDim.x) {
        float val = input_slice_ptr[i];
        float clamped_val = fmaxf(clamp_min, fminf(clamp_max, val));
        float exp_val = expf(clamped_val - block_max_val);
        // Handle potential division by zero if block_sum_exp is very small
        output_slice_ptr[i] = (block_sum_exp > 0.0f ? (exp_val / block_sum_exp) : 0.0f) * scale_val;
    }
}

