import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Linear + Scaling + Residual
# This kernel performs Matrix Multiplication (A @ W.T), adds bias, 
# and fuses the scaling and residual addition logic: out = (x @ W.T + b) * (1 + scaling_factor)
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void fused_linear_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int M, int N, int K,
    float scaling_multiplier) {

    // M: Batch size, N: Out features, K: In features
    // blockIdx.x handles N (columns of output)
    // blockIdx.y handles M (rows of output)
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    // Shared memory for tiles of Input (A) and Weight (W)
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Ws[TILE_SIZE][TILE_SIZE];

    float val = 0.0f;

    // Loop over the K-dimension in steps of TILE_SIZE
    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; ++t) {

        // Load tile of Input A [M, K]
        // As[ty][tx] corresponds to A[row, current_k_col]
        int a_col = t * TILE_SIZE + tx;
        if (row < M && a_col < K)
            As[ty][tx] = input[row * K + a_col];
        else
            As[ty][tx] = 0.0f;

        // Load tile of Weight W [N, K]
        // We perform C = A @ W.T. 
        // W is stored as (N, K). We need W^T elements.
        // We load W tile corresponding to the current output columns (bx) and current reduction cols (t).
        // Accessing W with [row_w, col_w] is coalesced.
        // We map shared memory Ws[ty][tx] to W[row_w, col_w]
        // where row_w corresponds to global output col index components,
        // and col_w corresponds to global reduction index components.
        int row_w = bx * TILE_SIZE + ty;
        int col_w = t * TILE_SIZE + tx;

        if (row_w < N && col_w < K)
            Ws[ty][tx] = weight[row_w * K + col_w];
        else
            Ws[ty][tx] = 0.0f;

        __syncthreads();

        // Compute partial dot product for this tile
        // C[row, col] += Sum_k (A[row, k] * W[col, k])
        // A[row, k] is As[ty][k]
        // W[col, k] is Ws[tx][k] (because we loaded Ws such that row index mapped to 'bx' block)
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            val += As[ty][k] * Ws[tx][k];
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        float b = bias[col];
        // Mathematical simplification of the original architecture:
        // x = matmul(x)
        // original_x = x.clone().detach() (treated as constant in residual)
        // x = x * s + original_x => x * (s + 1)
        output[row * N + col] = (val + b) * scaling_multiplier;
    }
}

torch::Tensor fused_linear_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, float scaling_factor) {
    // Input checks
    int M = input.size(0);
    int K = input.size(1);
    int N = weight.size(0); // weight shape is (out_features, in_features)

    auto output = torch::empty({M, N}, input.options());

    // Scaling multiplier = 1 + s
    float scaling_multiplier = 1.0f + scaling_factor;

    dim3 threads(TILE_SIZE, TILE_SIZE);
    dim3 blocks((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);

    fused_linear_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        M, N, K,
        scaling_multiplier
    );

    return output;
}
"""

