#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX
#include <math.h>  // For expf, logf, fmaxf

// Macro for checking CUDA errors
#define CUDA_CHECK(call) \\
    do { \\
        cudaError_t err = call; \\
        if (err != cudaSuccess) { \\
            fprintf(stderr, "CUDA error at %s:%d: %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \\
            exit(1); \\
        } \\
    } while (0)

// Kernel for fused_add_bias_logsumexp
// Each block processes one row (sample) independently.
// Shared memory is partitioned:
// - `shared_vals`: stores `val_ij = gemm_out_ij + bias_j` for the current row.
// - `shared_temp_reduction`: used for parallel reduction of max and sum_exp within the block.
__global__ void fused_add_bias_logsumexp_kernel(const float* gemm_out, const float* bias, float* out, int rows, int cols) {
    int row_idx = blockIdx.x;
    if (row_idx >= rows) return;

    // Partition shared memory:
    // First `cols` elements for `shared_vals` (to store val_ij)
    // Next `blockDim.x` elements for `shared_temp_reduction` (for max/sum reduction)
    extern __shared__ float shared_mem_ptr[];
    float* shared_vals = shared_mem_ptr;
    float* shared_temp_reduction = shared_mem_ptr + cols;

    // Step 1: Load val_ij = gemm_out_ij + bias_j into shared_vals and find thread-local max
    float thread_local_max = -FLT_MAX;
    for (int col_idx = threadIdx.x; col_idx < cols; col_idx += blockDim.x) {
        float val = gemm_out[row_idx * cols + col_idx] + bias[col_idx];
        shared_vals[col_idx] = val;
        thread_local_max = fmaxf(thread_local_max, val);
    }
    __syncthreads();

    // Step 2: Reduce thread-local maxes to find the global max for the row
    // Store thread_local_max into shared_temp_reduction[threadIdx.x]
    if (threadIdx.x < blockDim.x) {
        shared_temp_reduction[threadIdx.x] = thread_local_max;
    }
    __syncthreads();

    // Parallel reduction for max_val using shared_temp_reduction
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            shared_temp_reduction[threadIdx.x] = fmaxf(shared_temp_reduction[threadIdx.x], shared_temp_reduction[threadIdx.x + s]);
        }
        __syncthreads();
    }
    float max_val = shared_temp_reduction[0]; // Global max value for the current row

    __syncthreads(); // Ensure max_val is stable for all threads before proceeding

    // Step 3: Compute sum(exp(val_ij - max_val))
    float thread_local_sum_exp = 0.0f;
    for (int col_idx = threadIdx.x; col_idx < cols; col_idx += blockDim.x) {
        // Retrieve original val_ij from shared_vals
        thread_local_sum_exp += expf(shared_vals[col_idx] - max_val);
    }
    __syncthreads();

    // Step 4: Reduce thread-local sum_exp to find the global sum_exp for the row
    // Use shared_temp_reduction again for this reduction
    if (threadIdx.x < blockDim.x) {
        shared_temp_reduction[threadIdx.x] = thread_local_sum_exp;
    }
    __syncthreads();

    // Parallel reduction for sum_exp using shared_temp_reduction
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            shared_temp_reduction[threadIdx.x] += shared_temp_reduction[threadIdx.x + s];
        }
        __syncthreads();
    }
    float sum_exp = shared_temp_reduction[0]; // Global sum of exponentials for the current row

    // Step 5: Compute final logsumexp
    if (threadIdx.x == 0) { // Only one thread writes the result for the row
        out[row_idx] = max_val + logf(sum_exp);
    }
}

