#include <cuda_runtime.h>
#include <device_launch_parameters.h>
#include <float.h> // For FLT_MAX

// Helper for block-wise reduction (max)
// s_data: shared memory buffer for reduction
__device__ float block_reduce_max(float val, volatile __shared__ float* s_data) {
    s_data[threadIdx.x] = val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] = fmaxf(s_data[threadIdx.x], s_data[threadIdx.x + s]);
        }
        __syncthreads();
    }
    return s_data[0];
}

// Helper for block-wise reduction (sum)
// s_data: shared memory buffer for reduction
__device__ float block_reduce_sum(float val, volatile __shared__ float* s_data) {
    s_data[threadIdx.x] = val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads();
    }
    return s_data[0];
}


__global__ void softmax_sigmoid_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W) {

    // Each block processes one (N, D, H, W) slice
    // The total number of such slices is N * D * H * W.
    // blockIdx.x maps to this outer_idx.
    int outer_idx = blockIdx.x;

    // Check if outer_idx is within bounds
    if (outer_idx >= (long long)N * D * H * W) {
        return;
    }

    // Calculate n, d, h, w from outer_idx
    int w = outer_idx % W;
    int h = (outer_idx / W) % H;
    int d = (outer_idx / ((long long)H * W)) % D;
    int n = outer_idx / ((long long)D * H * W);

    // Base index for the current (n, d, h, w) slice across channels (c=0)
    long long base_idx = (long long)n * C * D * H * W + (long long)d * H * W + (long long)h * W + (long long)w;

    // Shared memory for reduction and intermediate exp_vals.
    // We declare a single dynamically-sized shared memory array and partition it.
    extern __shared__ float s_mem[];
    // The first `blockDim.x` elements are used for reduction operations (max and sum).
    volatile __shared__ float* s_reduction_buffer = s_mem;
    // The subsequent `C` elements are used to store `exp_vals` for the current slice.
    volatile __shared__ float* s_exp_vals_buffer = s_mem + blockDim.x;

    // Step 1: Find the maximum value across channels for numerical stability (log-sum-exp trick).
    float thread_max_val = -FLT_MAX; // Initialize with smallest float value
    // Each thread iterates over a subset of channels if C > blockDim.x
    for (int c_offset = threadIdx.x; c_offset < C; c_offset += blockDim.x) {
        long long current_idx = base_idx + (long long)c_offset * D * H * W;
        thread_max_val = fmaxf(thread_max_val, input[current_idx]);
    }
    // Reduce thread_max_val across all threads in the block to get the true max for the slice.
    float max_val = block_reduce_max(thread_max_val, s_reduction_buffer);

    __syncthreads(); // Ensure max_val is computed and visible to all threads before proceeding.

    // Step 2: Compute exp(x - max_val) for each channel and store in shared memory.
    // Also, sum these exponentiated values.
    float thread_sum_exp = 0.0f;
    for (int c_offset = threadIdx.x; c_offset < C; c_offset += blockDim.x) {
        long long current_idx = base_idx + (long long)c_offset * D * H * W;
        float val = input[current_idx];
        float exp_val = expf(val - max_val);

        // Store exp_val in shared memory for later division.
        // The check `c_offset < C` is technically redundant due to loop condition,
        // but ensures bounds safety if loop structure changes.
        if (c_offset < C) {
            s_exp_vals_buffer[c_offset] = exp_val;
        }
        thread_sum_exp += exp_val;
    }

    // Reduce thread_sum_exp to get the total sum of exponentiated values for the slice.
    float sum_exp = block_reduce_sum(thread_sum_exp, s_reduction_buffer);

    __syncthreads(); // Ensure sum_exp is computed and visible to all threads before proceeding.

    // Step 3: Compute Softmax and then Sigmoid, writing the final result to global memory.
    for (int c_offset = threadIdx.x; c_offset < C; c_offset += blockDim.x) {
        long long current_idx = base_idx + (long long)c_offset * D * H * W;

        // Only process valid channel offsets.
        if (c_offset < C) {
            float softmax_val = s_exp_vals_buffer[c_offset] / sum_exp;
            float sigmoid_val = 1.0f / (1.0f + expf(-softmax_val));
            output[current_idx] = sigmoid_val;
        }
    }
}

