                                      int kernel_size, 
                                      float scale_factor) {
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int num_segments = out_features / kernel_size;

    float thread_sum = 0.0f;
    // Each thread processes segments of kernel_size elements across the row.
    // Striding by blockDim.x ensures full row coverage and partial coalescence.
    for (int i = tid; i < num_segments; i += blockDim.x) {
        int start = i * kernel_size;
        float local_max = -1e38f; // Representing negative infinity for float
        for (int j = 0; j < kernel_size; ++j) {
