    int g = blockIdx.y;

    // Calculate elements to reduce: C_per_G channels * S spatial pixels
    int count = C_per_G * S;

    float sum = 0.0f;
    float sq_sum = 0.0f;

    int stride = blockDim.x;
    int tid = threadIdx.x;

