        // gamma and beta are per-channel.
        float gamma = gamma_ptr[c_idx];
        float beta = beta_ptr[c_idx];

        float gn_val = normalized_val * gamma + beta;

        // 3. HardSwish activation: x * ReLU6(x + 3) / 6
        // ReLU6(x) = min(max(x, 0), 6)
        float relu6_arg = gn_val + 3.0f;
        float relu6_val = fminf(fmaxf(relu6_arg, 0.0f), 6.0f);
        float hardswish_val = gn_val * relu6_val / 6.0f;

        out_ptr[idx] = hardswish_val;
    }
}

// PyTorch C++ API wrapper for group_norm_mean_var_kernel
std::vector<torch::Tensor> group_norm_mean_var_cuda(torch::Tensor x, int num_groups) {
