import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the fused Custom CUDA Kernel
# This kernel fuses GroupNorm (calculations + affine), LeakyReLU, and the Element-wise Sum (x+x)
# into a single kernel to reduce memory bandwidth usage.
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_gn_relu_add_kernel(
    float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    int N, int C, int G,
    float eps, float neg_slope) 
{
    // C = hidden_size
    // G = num_groups
    // D = Channels per group (C / G)
    // For the specific architecture: C=8192, G=512 => D=16.
    // D=16 fits within a single warp (32), allowing efficient shuffle reductions.

    int D = C / G;

    // Mapping:
    // gridDim.x represents the Batch dimension (N)
    // gridDim.y represents chunks of Groups
    // blockDim.x is fixed (e.g., 256)

    int n = blockIdx.x; // Batch index

    // Calculate how many groups one block handles
    int groups_per_block = blockDim.x / D;

    // Determine the starting group index for this block
    int g_base = blockIdx.y * groups_per_block;

    // Thread identifiers
    int tid = threadIdx.x;
    int local_g = tid / D; // Group index within the block
    int lane = tid % D;    // Lane index within the group (0..D-1)

    int g = g_base + local_g; // Global group index

    // Boundary check
    if (g < G && n < N) {
        // Calculate global memory index
        // Row-major layout: [N, C]
        // Flattened channel index: g * D + lane
        int channel_idx = g * D + lane;
        int idx = n * C + channel_idx; 

        float val = x[idx];

        // --- Step 1: Group Normalization (Mean & Variance) ---
        // Perform reduction across D (16) threads using warp shuffles.
        // We use __shfl_xor_sync to butterfly reduce.
        // Since D=16, we XOR with 8, 4, 2, 1.

        float sum = val;
        unsigned int mask = 0xffffffff;

        // Unrolled reduction for D=16
        sum += __shfl_xor_sync(mask, sum, 8);
        sum += __shfl_xor_sync(mask, sum, 4);
        sum += __shfl_xor_sync(mask, sum, 2);
        sum += __shfl_xor_sync(mask, sum, 1);

        float mean = sum / (float)D;

        // Variance calculation
        float diff = val - mean;
        float sq_diff = diff * diff;
        float var_sum = sq_diff;

        var_sum += __shfl_xor_sync(mask, var_sum, 8);
        var_sum += __shfl_xor_sync(mask, var_sum, 4);
        var_sum += __shfl_xor_sync(mask, var_sum, 2);
        var_sum += __shfl_xor_sync(mask, var_sum, 1);

        float var = var_sum / (float)D;
        float inv_std = rsqrtf(var + eps);

        // Normalize
        float norm = diff * inv_std;

        // --- Step 2: Apply Affine Parameters (Gamma & Beta) ---
        float g_val = gamma[channel_idx];
        float b_val = beta[channel_idx];
        float out = norm * g_val + b_val;

        // --- Step 3: LeakyReLU ---
        if (out < 0.0f) {
            out = out * neg_slope;
        }

        // --- Step 4: Element-wise Sum (x = x + x) ---
        // Equivalent to multiplication by 2
        out = out * 2.0f;

        // Write result back to global memory
        x[idx] = out;
    }
}

