# Define the custom CUDA kernel for Fused GELU + Global Average Pooling
# This kernel replaces the operations: GELU -> AdaptiveAvgPool2d(1) -> Flatten
# It drastically reduces memory traffic by fusing the activation and reduction,
# reading the large intermediate tensor once and writing only the tiny output tensor.

fused_gelu_pool_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// GELU implementation: x * 0.5 * (1 + erf(x / sqrt(2)))
__device__ __forceinline__ float gelu_func(float x) {
    const float kAlpha = 0.7071067811865476f; // 1 / sqrt(2)
    return 0.5f * x * (1.0f + erff(x * kAlpha));
}

__global__ void fused_gelu_pool_kernel(
    const float* __restrict__ input, 
    float* __restrict__ output, 
    int spatial_size) {

    // Each block handles one channel of one batch item
    // gridDim.y = Batch Size (N)
    // gridDim.x = Channels (C)
    int n = blockIdx.y;
    int c = blockIdx.x;

    // Global offset to the start of the HxW plane for this (n, c)
    int num_channels = gridDim.x;
    int offset = (n * num_channels + c) * spatial_size;

    float sum = 0.0f;

    // Vectorized loads (float4) for higher memory bandwidth
    // We assume the input tensor is contiguous and aligned. 
    // H*W = 254*254 = 64516, which is divisible by 4.
    int num_vecs = spatial_size / 4;
    const float4* input_vec = reinterpret_cast<const float4*>(input + offset);

    // Grid-stride loop (effectively just block stride here)
    for (int i = threadIdx.x; i < num_vecs; i += blockDim.x) {
        float4 v = input_vec[i];
        sum += gelu_func(v.x);
        sum += gelu_func(v.y);
        sum += gelu_func(v.z);
        sum += gelu_func(v.w);
    }

    // Handle remainder elements (if any)
    for (int i = num_vecs * 4 + threadIdx.x; i < spatial_size; i += blockDim.x) {
        sum += gelu_func(input[offset + i]);
    }

    // Warp-level reduction
    for (int mask = 16; mask > 0; mask /= 2) {
        sum += __shfl_down_sync(0xffffffff, sum, mask);
    }

    // Block-level reduction using Shared Memory
    static __shared__ float shared_sums[32]; // Max 1024 threads / 32 warps = 32
    int lane = threadIdx.x % 32;
    int warp = threadIdx.x / 32;

    if (lane == 0) {
        shared_sums[warp] = sum;
    }

    __syncthreads();

    // Final reduction by the first warp
    if (warp == 0) {
        // Load partial sums from shared memory
        int num_warps = (blockDim.x + 31) / 32;
        sum = (lane < num_warps) ? shared_sums[lane] : 0.0f;

        for (int mask = 16; mask > 0; mask /= 2) {
            sum += __shfl_down_sync(0xffffffff, sum, mask);
        }

        // Write result to global memory
        if (lane == 0) {
            output[n * num_channels + c] = sum / static_cast<float>(spatial_size);
        }
    }
}

