    // blockIdx.z -> Batch index (n)
    // blockIdx.y -> Output Channel index (c_out)
    // blockIdx.x * blockDim.x + threadIdx.x -> Spatial Linear Index (h_out * out_w + w_out)

    int n = blockIdx.z;
    int c_out = blockIdx.y;
    int spatial_idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Boundary check for spatial dimensions
    if (spatial_idx >= out_h * out_w) return;

    // Map spatial index back to h_out, w_out
    int h_out = spatial_idx / out_w;
    int w_out = spatial_idx % out_w;

    // Initialize accumulator with bias if available
    float sum = 0.0f;
    if (bias != nullptr) {
        sum = bias[c_out];
    }

    // Convolution Logic (Stride=1, Padding=0 as per original architecture)
    // To optimize, we pre-calculate base offsets

    // Offset for the current batch image in input: n * (C_in * H_in * W_in)
    int input_batch_offset = n * in_channels * in_h * in_w;

    // Offset for the current output channel filters in weight: c_out * (C_in * K * K)
