# CUDA source for fused BatchNormalization and two successive Average Pooling layers
# This kernel fuses: 
# 1. BatchNormalization3d (inference mode)
# 2. AvgPool3d (kernel_size=2, stride=2)
# 3. AvgPool3d (kernel_size=2, stride=2)
# The two pooling layers combined are equivalent to a single AvgPool3d (kernel_size=4, stride=4).
fused_bn_pool_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_bn_pool_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    float* __restrict__ output,
    int N, int C, int D, int H, int W,
    int OD, int OH, int OW,
    float eps) 
{
    int total_threads = N * C * OD * OH * OW;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_threads) {
        // Decompose linear index to N, C, D, H, W coordinates
        int temp_idx = idx;
        int ow = temp_idx % OW; temp_idx /= OW;
        int oh = temp_idx % OH; temp_idx /= OH;
        int od = temp_idx % OD; temp_idx /= OD;
        int c = temp_idx % C;
        int n = temp_idx / C;

        // Precompute Batch Normalization scale and shift for this channel
        // rsqrtf is the reciprocal square root intrinsic
        float s = weight[c] * rsqrtf(var[c] + eps);
        float b = bias[c] - mean[c] * s;

        float sum_val = 0.0f;
        int start_d = od * 4;
        int start_h = oh * 4;
        int start_w = ow * 4;

        // The two 2x2x2 pools with stride 2 are equivalent to one 4x4x4 pool with stride 4
        // Accumulate values in the 4x4x4 window
        for (int dd = 0; dd < 4; ++dd) {
            int d_off = ((((n * C + c) * D + (start_d + dd)) * H));
            for (int hh = 0; hh < 4; ++hh) {
                int h_off = (d_off + (start_h + hh)) * W;
                for (int ww = 0; ww < 4; ++ww) {
                    sum_val += input[h_off + (start_w + ww)];
                }
            }
        }

        // The result of two average pools is (Sum(elements) / 8) / 8 = Sum / 64
        // Apply normalization and divide by window size
        output[idx] = (sum_val / 64.0f) * s + b;
    }
}

