# This kernel performs the operation of:
# 1. AvgPool3d(kernel_size=4, stride=4) (Equivalent to two consecutive AvgPool3d(2) layers)
# 2. BatchNorm3d (Applied after pooling for efficiency, valid for inference/fixed stats)
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_bn_pool_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int N, int C,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    float eps) {

    // Grid maps to Output tensor dimensions
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * Dout * Hout * Wout;

    if (idx < total_elements) {
        // Decompose linear index into (n, c, d_out, h_out, w_out)
        int temp = idx;
        int w_out = temp % Wout; temp /= Wout;
        int h_out = temp % Hout; temp /= Hout;
        int d_out = temp % Dout; temp /= Dout;
        int c = temp % C; 
        int n = temp / C;

        // Calculate corresponding top-left corner in Input tensor
        // Stride is 4 effectively (2 * 2)
        int d_in_start = d_out * 4;
        int h_in_start = h_out * 4;
        int w_in_start = w_out * 4;

        // Strides for Input tensor (N, C, Din, Hin, Win)
        int input_depth_stride = Hin * Win;
        int input_height_stride = Win;
        int input_channel_stride = Din * input_depth_stride;
        int input_batch_stride = C * input_channel_stride;

        int input_offset = n * input_batch_stride + c * input_channel_stride;
        const float* input_slice = input + input_offset;

        float sum = 0.0f;

        // Accumulate 4x4x4 block
        #pragma unroll
        for (int z = 0; z < 4; ++z) {
            #pragma unroll
            for (int y = 0; y < 4; ++y) {
                #pragma unroll
                for (int x = 0; x < 4; ++x) {
                    int d_in = d_in_start + z;
                    int h_in = h_in_start + y;
                    int w_in = w_in_start + x;

                    int in_idx = d_in * input_depth_stride + h_in * input_height_stride + w_in;
                    sum += input_slice[in_idx];
                }
            }
        }

