        float avg = sum / 64.0f;

        // Apply BatchNorm: y = (x - mean) / sqrt(var + eps) * weight + bias
        float m = mean[c];
        float v = var[c];
        float w = weight[c];
        float b = bias[c];

        float res = (avg - m) * rsqrtf(v + eps) * w + b;

        output[idx] = res;
