        // This loop iterates over the 2x2x2 window in the *intermediate* pooling output.
        // For each element in this window, we calculate its value by performing the first pooling step.
        int d1_start = d_o * 2;
        int h1_start = h_o * 2;
        int w1_start = w_o * 2;

        for (int kd1 = 0; kd1 < 2; ++kd1) {
            for (int kh1 = 0; kh1 < 2; ++kh1) {
