#include <cuda_runtime.h>
#include <math.h>

__global__ void gn_min_kernel(const float* __restrict__ input,
                              const float* __restrict__ gamma,
                              const float* __restrict__ beta,
                              float* __restrict__ output,
                              int C, int G, int group_size, float eps) {
