#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_pool_sum_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W,
    int OD, int OH, int OW) {

    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int num_outputs = N * OD * OH * OW;

    if (tid < num_outputs) {
        int ow = tid % OW;
        int oh = (tid / OW) % OH;
        int od = (tid / (OW * OH)) % OD;
        int n = tid / (OW * OH * OD);

        float total_sum = 0.0f;

        // The composition of MaxPool3d(kernel=2, stride=2) followed by MaxPool3d(kernel=3, stride=3)
        // is equivalent to a single MaxPool3d with kernel=6 and stride=6.
        for (int c = 0; c < C; ++c) {
            float max_val = -FLT_MAX;
            int base_c = (n * C + c) * D;
            for (int kd = 0; kd < 6; ++kd) {
                int id = od * 6 + kd;
                if (id >= D) continue;
                int base_id = (base_c + id) * H;
                for (int kh = 0; kh < 6; ++kh) {
                    int ih = oh * 6 + kh;
                    if (ih >= H) continue;
                    int base_ih = (base_id + ih) * W;
                    for (int kw = 0; kw < 6; ++kw) {
                        int iw = ow * 6 + kw;
                        if (iw >= W) continue;

                        float val = input[base_ih + iw];
                        if (val > max_val) max_val = val;
                    }
                }
            }
            total_sum += (max_val == -FLT_MAX) ? 0.0f : max_val;
        }
        output[tid] = total_sum;
    }
