# The original architecture performs:
# 1. MaxPool3d(kernel_size=2) (stride defaults to kernel_size=2)
# 2. MaxPool3d(kernel_size=3) (stride defaults to kernel_size=3)
# 3. Sum(dim=1, keepdim=True)
#
# Mathematically, applying MaxPool(k=2, s=2) followed by MaxPool(k=3, s=3) is equivalent 
# to a single MaxPool(k=6, s=6), assuming standard floor behavior for output size calculation.
# We fuse these two pooling operations and the channel summation into a single CUDA kernel.
# This reduces memory bandwidth significantly by avoiding the write/read of intermediate tensors.

fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_pool_sum_kernel(
