    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial_out = D_out * H_out * W_out;
    int total_threads = N * spatial_out;

    if (idx < total_threads) {
        // Decode index to (n, d_out, h_out, w_out)
        int w_out = idx % W_out;
        int rem = idx / W_out;
        int h_out = rem % H_out;
        rem = rem / H_out;
        int d_out = rem % D_out;
        int n = rem / D_out;

        // Input strides
        int stride_w = 1;
        int stride_h = W;
        int stride_d = H * W;
        int stride_c = D * H * W;
        int stride_n = C * D * H * W;

        // Determine the starting corner of the 6x6x6 pooling window in the input
        // Stride is 6
        int d_start = d_out * 6;
        int h_start = h_out * 6;
        int w_start = w_out * 6;

