        const float* input_n = input + n * stride_n;

        float sum_val = 0.0f;

        // Iterate over all channels to perform the sum reduction
        for (int c = 0; c < C; ++c) {
            float max_val = -FLT_MAX;
            const float* input_c = input_n + c * stride_c;

            // Perform MaxPool over the 6x6x6 window
            // Unrolling loops for performance
