        // Operation 3: Dropout
        if (training && p > 0.0f) {
            // noise is a random tensor [0, 1) pre-generated
            // if noise[idx] < p, drop the value
            // otherwise scale it
            if (noise[idx] < p) {
                val = 0.0f;
            } else {
                val = val * scale;
            }
        }

        out[idx] = val;
    }
}

