    int row = blockIdx.x;
    int tid = threadIdx.x;

    if (row >= rows) return;

    // Shared memory for block-level reductions (supports up to 1024 threads)
    __shared__ float shared_val[32]; 

    // Step 1: Find Max across the row
    float max_v = -1e38f;
    for (int i = tid; i < cols; i += blockDim.x) {
        float s = (scale_len == 1) ? scale[0] : scale[i];
        max_v = fmaxf(max_v, input[row * cols + i] * s);
    }

    // Warp-level reduction
    max_v = warpReduceMax(max_v);
    if ((tid & 31) == 0) shared_val[tid >> 5] = max_v;
    __syncthreads();

    // Final reduction of warp results
    if (tid < 32) {
        max_v = (tid < (blockDim.x >> 5)) ? shared_val[tid] : -1e38f;
        max_v = warpReduceMax(max_v);
        if (tid == 0) shared_val[0] = max_v;
    }
    __syncthreads();
    max_v = shared_val[0];

    // Step 2: Sum exponentials across the row
    float sum_v = 0.0f;
