    __syncthreads();
    sum_v = shared_val[0];

    // Step 3: Compute final Softmax output and write to global memory
    float inv_sum = 1.0f / sum_v;
    for (int i = tid; i < cols; i += blockDim.x) {
        float s = (scale_len == 1) ? scale[0] : scale[i];
