# CUDA source for fused GroupNorm, Swish, Multiply, and Swish
# This kernel optimizes the post-linear operations: GroupNorm, two Swish activations, and an element-wise multiplication.
# It uses warp-level primitives for the GroupNorm reduction, assuming the group size is 32 (8192 / 256 = 32).
fused_ops_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    const float* __restrict__ mult_weight,
    float* __restrict__ output,
    int total_elements,
    int num_features,
    int group_size,
    float eps) {

    int tid = blockIdx.x * blockDim.x + threadIdx.x;

    if (tid < total_elements) {
        // Since group_size = 32 and num_features is a multiple of 32, 
        // each warp handles exactly one GroupNorm group.

        float val = input[tid];
        float sum = val;
        float sum_sq = val * val;

        // Warp-level reduction for mean and variance
        for (int offset = 16; offset > 0; offset /= 2) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
        }

        // Broadcast reduced values from the first thread of the warp
        float total_sum = __shfl_sync(0xffffffff, sum, 0);
        float total_sum_sq = __shfl_sync(0xffffffff, sum_sq, 0);

        float mean = total_sum / (float)group_size;
        float var = (total_sum_sq / (float)group_size) - (mean * mean);
        float inv_std = rsqrtf(var + eps);

        // Map tid to feature index (column index)
        int c = tid % num_features;

        // GroupNorm: Normalization and Affine Transform
        float res = (val - mean) * inv_std;
        res = res * gn_weight[c] + gn_bias[c];

        // First Swish Activation: x * sigmoid(x)
        res = res / (1.0f + expf(-res));

        // Element-wise Multiply with learnable weight
        res = res * mult_weight[c];

        // Second Swish Activation: x * sigmoid(x)
        res = res / (1.0f + expf(-res));

        output[tid] = res;
    }
}

