fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ __forceinline__ float sigmoid_f(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void fused_gn_swish_mul_swish_kernel(
    float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    const float* __restrict__ mult_w,
    int batch_size,
    int num_channels,
    int num_groups,
    int channels_per_group,
    float eps) {

    // Logic: Each warp handles one (Batch, Group) pair.
    // channels_per_group is 32 (based on 8192/256), so one warp covers exactly one group's channels.

    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32;

    // Calculate which (Batch, Group) pair this warp is responsible for
    int global_warp_id = blockIdx.x * (blockDim.x / 32) + warp_id;
    int total_work_items = batch_size * num_groups;

    if (global_warp_id >= total_work_items) return;

    int b_idx = global_warp_id / num_groups;
    int g_idx = global_warp_id % num_groups;

    // Calculate memory offsets
    int group_start_c = g_idx * channels_per_group;
    int c_idx = group_start_c + lane_id; // Channel index [0, 8191]
    int idx = b_idx * num_channels + c_idx; // Global 1D index

    // Load input
    float val = x[idx];

    // --- GroupNorm Step 1: Mean ---
    // Reduction within the warp
    float sum = val;
    unsigned int mask = 0xffffffff;

    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(mask, sum, offset);
    }
    float mean = __shfl_sync(mask, sum, 0) / channels_per_group;

    // --- GroupNorm Step 2: Variance ---
    float diff = val - mean;
    float sq_diff = diff * diff;
    float sum_sq = sq_diff;

    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        sum_sq += __shfl_down_sync(mask, sum_sq, offset);
    }
    float var = __shfl_sync(mask, sum_sq, 0) / channels_per_group;
    float inv_std = rsqrtf(var + eps);

    // --- Normalize & Affine ---
    float n_val = (val - mean) * inv_std;
    float g = gamma[c_idx];
    float b = beta[c_idx];
    float out = n_val * g + b;

    // --- Swish (x * sigmoid(x)) ---
    out = out * sigmoid_f(out);

    // --- Multiply ---
    float m = mult_w[c_idx];
    out = out * m;

    // --- Swish ---
    out = out * sigmoid_f(out);

    // Write output (in-place)
    x[idx] = out;
}

