    int total_work_items = batch_size * num_groups;

    const int block_size = 256;
    const int warps_per_block = block_size / 32;
    const int grid_size = (total_work_items + warps_per_block - 1) / warps_per_block;

    fused_gn_swish_mul_swish_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        mult_w.data_ptr<float>(),
        batch_size,
        num_channels,
        num_groups,
        channels_per_group,
        eps
    );

    return x;
}
"""

