    int spatial_vol = D * H * W;

    // Global thread index
    // Each thread handles one spatial location (d, h, w) for a specific batch item n
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = N * spatial_vol;

    if (idx < total_threads) {
        // Map linear index to (n, spatial_idx)
        int n = idx / spatial_vol;
        int spatial_idx = idx % spatial_vol;

        // Calculate stride to jump to the next channel at the same spatial position
        // Memory layout is (N, C, D, H, W)
        // Element index = n * (C * spatial_vol) + c * spatial_vol + spatial_idx
        int channel_stride = spatial_vol;

        // Pointer to the start of the channel vector for this spatial location
        const float* x_ptr = x + n * C * spatial_vol + spatial_idx;

        // ----------------------------------------------------------------
        // Step 1: Softmax (across C)
        // ----------------------------------------------------------------

        // Find Max for numerical stability
        float max_val = -1e30f;
        for (int c = 0; c < C; ++c) {
            float val = x_ptr[c * channel_stride];
            if (val > max_val) {
                max_val = val;
            }
