        // Compute Sum of Exponentials
        float sum_exp = 0.0f;
        for (int c = 0; c < C; ++c) {
            sum_exp += expf(x_ptr[c * channel_stride] - max_val);
        }

        // Precompute reciprocal of sum
        float inv_sum_exp = 1.0f / sum_exp;

        // ----------------------------------------------------------------
        // Step 2, 3, 4: Softmax -> Subtract -> Swish -> Reduce Max
