    // Grid size covers all N * H * W pixels.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_pixels = N * HW;

    if (idx < total_pixels) {
        // Determine the batch index (n) and spatial offset (rem = h * W + w)
        int n = idx / HW;
        int rem = idx % HW;

        // Calculate the base pointer offset for the channel column of this pixel
        // Tensor layout is NCHW.
        // The c-th channel for pixel (n, rem) is at:
        // index = n * (C * HW) + c * HW + rem
        // For a Warp of threads with consecutive 'rem', memory accesses are coalesced
        // because they access adjacent memory locations (stride 1).
        int base_offset = n * C * HW + rem;
        int stride = HW;

        // 1. Find Max for Softmax numerical stability
        float max_val = -1e37f;
        for (int c = 0; c < C; ++c) {
            float val = x[base_offset + c * stride];
            if (val > max_val) {
                max_val = val;
            }
        }

        // 2. Compute Sum of Exponentials
        float sum_exp = 0.0f;
        for (int c = 0; c < C; ++c) {
            float val = x[base_offset + c * stride];
            sum_exp += expf(val - max_val);
