#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_bias_act_gn_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    float* __restrict__ output,
    int N, int C, int G, int L, float eps) {

    // Total groups across entire batch is N * G
    int group_idx = blockIdx.x; 
    int tid = threadIdx.x; 

    if (group_idx >= N * G) return;

    int batch_idx = group_idx / G;
    int group_in_batch = group_idx % G;

    // Each thread in the block (warp) handles one element of the 32-element group
    int channel_idx = group_in_batch * L + tid;
    int input_idx = batch_idx * C + channel_idx;

    // 1. Load and Add Combined Bias
    float val = input[input_idx] + bias[channel_idx];

    // 2. Hardtanh Activation
    val = fmaxf(-1.0f, fminf(1.0f, val));

    // 3. Mish Activation: x * tanh(softplus(x))
    // softplus(x) = log(1 + exp(x))
    float sp = (val > 20.0f) ? val : log1pf(expf(val));
    val = val * tanhf(sp);

    // 4. GroupNorm reduction (mean, var)
    // This assumes L=32 so we can use single warp primitives
    float sum = val;
    float sq_sum = val * val;

    // Warp reduction using shuffle
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xFFFFFFFF, sum, offset);
        sq_sum += __shfl_down_sync(0xFFFFFFFF, sq_sum, offset);
