    // Broadcast results from thread 0 of warp to all others
    float mean = __shfl_sync(0xFFFFFFFF, sum, 0) / (float)L;
    float sq_mean = __shfl_sync(0xFFFFFFFF, sq_sum, 0) / (float)L;
    float var = sq_mean - (mean * mean);
    float inv_std = rsqrtf(var + eps);

    // 5. Normalize and Scale/Shift (GroupNorm parameters)
    float out_val = (val - mean) * inv_std * gn_weight[channel_idx] + gn_bias[channel_idx];
    output[input_idx] = out_val;
