import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# -----------------------------------------------------------------------------------------
# Custom CUDA Kernel for Fused Post-GEMM Operations
# Operations: BiasAdd -> Hardtanh -> Mish -> GroupNorm
# Optimized for:
#   - Batch size: 1024
#   - Out features: 8192
#   - Groups: 256
#   - Channels per group: 32 (Perfect fit for Warp-level reduction)
# -----------------------------------------------------------------------------------------

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ __forceinline__ float mish_func(float x) {
    // Mish: x * tanh(softplus(x))
    // Softplus threshold for numerical stability typically 20.0f
    float sp = (x > 20.0f) ? x : log1pf(expf(x));
    return x * tanhf(sp);
}

__global__ void fused_post_gemm_kernel(
    float* __restrict__ x,
    const float* __restrict__ bias,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    int N,
    int C,
    int G,
    float eps) 
{
    // Each warp processes one group of one sample.
    // Warp size = 32. Channels per group = 32.
    // Perfect mapping: 1 thread per channel in the group.

    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32; // Corresponds to channel index within group

    // Global group index
    // Block size is 256 threads -> 8 warps per block
    int global_group_id = blockIdx.x * 8 + warp_id;

    // Map global group id to (sample_row, group_idx)
    int row = global_group_id / G;
    int group_idx = global_group_id % G; // 0 to 255

    // Bounds check
    if (row >= N) return;

    // Calculate memory offset
    int channel_offset_in_row = group_idx * 32 + lane_id;
    int global_offset = row * C + channel_offset_in_row;

    // 1. Load Data
    float val = x[global_offset];

    // 2. Add Bias
    // Bias is shape (C,)
    float b = bias[channel_offset_in_row];
    val += b;

    // 3. Hardtanh
    // min = -1, max = 1
    val = fminf(1.0f, fmaxf(-1.0f, val));

    // 4. Mish
    val = mish_func(val);

    // 5. GroupNorm: Mean Calculation (Reduction within Warp)
    // We need mean of 32 elements in the group
    float sum = val;
    // Butterfly reduction
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }
    float mean = __shfl_sync(0xffffffff, sum, 0) / 32.0f; // Broadcast mean to all lanes

    // 6. GroupNorm: Variance Calculation
    float diff = val - mean;
    float sum_sq = diff * diff;

    for (int offset = 16; offset > 0; offset /= 2) {
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }
    float var = __shfl_sync(0xffffffff, sum_sq, 0) / 32.0f;

    // 7. Normalize & Affine Transform
    float inv_std = rsqrtf(var + eps);
    float gamma = gn_weight[channel_offset_in_row];
    float beta = gn_bias[channel_offset_in_row];

    float out = (val - mean) * inv_std * gamma + beta;

    // 8. Store Result
    x[global_offset] = out;
}

torch::Tensor fused_forward_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    torch::Tensor gn_weight,
    torch::Tensor gn_bias,
    float eps) 
