fused_bias_hardtanh_mish_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h> // For expf, logf, tanhf, fmaxf, fminf

// Helper function for numerically stable softplus: log(1 + exp(x))
__device__ float softplus_f(float x) {
    // For large x, exp(x) can overflow or lead to precision issues.
    // If x is large, log(1 + exp(x)) approaches x.
    // Using log1pf(expf(x)) is generally more stable than logf(1.0f + expf(x))
    // for small expf(x).
    // A common stable implementation:
    return (x > 20.0f) ? x : log1pf(expf(x));
}

// Helper function for Mish activation: x * tanh(softplus(x))
__device__ float mish_f(float x) {
    return x * tanhf(softplus_f(x));
}

// Helper function for Hardtanh activation (default min_val=-1.0, max_val=1.0)
__device__ float hardtanh_f(float x) {
    return fmaxf(-1.0f, fminf(x, 1.0f));
}

// Fused CUDA kernel for BiasAdd, Hardtanh, and Mish activations
__global__ void fused_bias_hardtanh_mish_kernel(
    const float* input,
    const float* custom_bias,
    float* output,
    int total_elements,
    int out_features // Used for broadcasting custom_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Apply custom_bias (broadcasted along the last dimension)
        float val = input[idx] + custom_bias[idx % out_features];

        // Apply Hardtanh activation
        val = hardtanh_f(val);

        // Apply Mish activation
        val = mish_f(val);

        output[idx] = val;
    }
}

