    TORCH_CHECK(custom_bias.is_cuda(), "Custom bias tensor must be on CUDA.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(custom_bias.is_contiguous(), "Custom bias tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input tensor must be float32.");
    TORCH_CHECK(custom_bias.dtype() == torch::kFloat32, "Custom bias tensor must be float32.");
    TORCH_CHECK(custom_bias.dim() == 1, "Custom bias tensor must be 1D.");
    TORCH_CHECK(input.size(-1) == custom_bias.size(0), "Last dimension of input must match custom bias size.");

