fused_postproc_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_postproc_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W,
    int Dp, int Hp, int Wp,
    int pool_k, int pool_s,
    float scale, float clamp_min, float clamp_max
) {
    // Each block processes one (n, c) output channel
    int nc = blockIdx.x;
    if (nc >= N * C) return;

    int c = nc % C;
    int n = nc / C;

    // Calculate offsets
    long long input_offset = (long long)n * (C * D * H * W) + (long long)c * (D * H * W);
    const float* input_ptr = input + input_offset;

    int total_pooled = Dp * Hp * Wp;
    float local_sum = 0.0f;

    // Iterate over all pooled elements using grid-stride style within the block
    for (int idx = threadIdx.x; idx < total_pooled; idx += blockDim.x) {
        int tmp = idx;
        int wp = tmp % Wp; tmp /= Wp;
        int hp = tmp % Hp; 
        int dp = tmp;

        // Determine input window top-left corner
        int d_start = dp * pool_s;
        int h_start = hp * pool_s;
        int w_start = wp * pool_s;

        float max_val = -FLT_MAX;

        // Iterate over the MaxPool window
        for (int id = 0; id < pool_k; ++id) {
            for (int ih = 0; ih < pool_k; ++ih) {
