                    int cur_d = d_start + id;
                    int cur_h = h_start + ih;
                    int cur_w = w_start + iw;

                    // Compute flat index
                    long long offset = (long long)cur_d * (H * W) + (long long)cur_h * W + cur_w;

                    // Apply scale immediately
                    float val = input_ptr[offset] * scale;

                    if (val > max_val) {
