# Define the custom CUDA kernel for fused Linear + GELU + Softmax
fused_linear_gelu_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <device_launch_parameters.h>
#include <float.h> // For FLT_MAX
#include <math.h>  // For expf, fmaxf, erff, M_SQRT1_2F

// GELU approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
// M_SQRT1_2F is 1/sqrt(2)
__device__ inline float gelu_approx(float x) {
    return 0.5f * x * (1.0f + erff(x * M_SQRT1_2F));
}

// Block-wide reduction for max
// s_reduce_buffer is a shared memory buffer of size blockDim.x
__device__ float block_max_reduce(float val, float* s_reduce_buffer) {
    s_reduce_buffer[threadIdx.x] = val;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_reduce_buffer[threadIdx.x] = fmaxf(s_reduce_buffer[threadIdx.x], s_reduce_buffer[threadIdx.x + s]);
        }
        __syncthreads();
    }
    return s_reduce_buffer[0];
}

// Block-wide reduction for sum
// s_reduce_buffer is a shared memory buffer of size blockDim.x
__device__ float block_sum_reduce(float val, float* s_reduce_buffer) {
    s_reduce_buffer[threadIdx.x] = val;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_reduce_buffer[threadIdx.x] += s_reduce_buffer[threadIdx.x + s];
        }
        __syncthreads();
    }
    return s_reduce_buffer[0];
}


__global__ void linear_gelu_softmax_kernel(
    const float* x_ptr,
    const float* W_ptr,
    const float* b_ptr,
    float* out_ptr,
    int batch_size,
    int in_features,
    int out_features)
{
    // Each block processes one row of the batch
    int batch_idx = blockIdx.x;

    // Pointers for the current row in the input tensor 'x'
    const float* current_x_row = x_ptr + batch_idx * in_features;

    // Dynamic shared memory allocation:
    // The first `out_features` floats are for s_gelu_vals (intermediate GELU outputs for the row).
    // The next `blockDim.x` floats are for s_reduce_buffer (used by block_max_reduce and block_sum_reduce).
    extern __shared__ float dynamic_shmem[];
    float* s_gelu_vals = dynamic_shmem;
    float* s_reduce_buffer = dynamic_shmem + out_features; // Offset by out_features floats

    float thread_local_max_gelu = -FLT_MAX;

    // Step 1: Compute Linear + GELU for a portion of the row
    // Each thread computes multiple output features if out_features > blockDim.x
    for (int out_feature_idx = threadIdx.x; out_feature_idx < out_features; out_feature_idx += blockDim.x) {
        float linear_val = 0.0f;
        // Compute dot product (x_row @ W.T)
        for (int k = 0; k < in_features; ++k) {
            linear_val += current_x_row[k] * W_ptr[out_feature_idx * in_features + k];
        }
        // Add bias
        linear_val += b_ptr[out_feature_idx];

        // Apply GELU activation
        float gelu_val = gelu_approx(linear_val);

        // Store the GELU output in shared memory for the current row
        s_gelu_vals[out_feature_idx] = gelu_val;

        // Update thread's local maximum GELU value encountered so far
        thread_local_max_gelu = fmaxf(thread_local_max_gelu, gelu_val);
    }
    __syncthreads(); // Ensure all GELU values are computed and stored in shared memory, and local maxes are updated

    // Step 2: Softmax - Pass 1 (Max Reduction)
    // Find the maximum GELU value across the entire row (all out_features)
    float row_max_val = block_max_reduce(thread_local_max_gelu, s_reduce_buffer);
    __syncthreads(); // Ensure row_max_val is visible to all threads

    float thread_local_sum_exp = 0.0f;

    // Step 3: Softmax - Pass 2 (Exponentiation and Sum Reduction)
    // Compute exp(gelu_val - row_max_val) and sum them
    for (int out_feature_idx = threadIdx.x; out_feature_idx < out_features; out_feature_idx += blockDim.x) {
        // Compute numerically stable exponentiation
        float exp_val = expf(s_gelu_vals[out_feature_idx] - row_max_val);
        // Overwrite s_gelu_vals with exp_val; original gelu_vals are no longer needed
        s_gelu_vals[out_feature_idx] = exp_val; 
        // Accumulate thread's local sum of exponents
        thread_local_sum_exp += exp_val;
    }
    __syncthreads(); // Ensure all exp_vals are computed and stored, and local sums are updated

    // Find the sum of exponents across the entire row
    float row_sum_exp = block_sum_reduce(thread_local_sum_exp, s_reduce_buffer);
    __syncthreads(); // Ensure row_sum_exp is visible to all threads

    // Step 4: Softmax - Pass 3 (Normalization)
    // Write final softmax output to global memory
    for (int out_feature_idx = threadIdx.x; out_feature_idx < out_features; out_feature_idx += blockDim.x) {
        out_ptr[batch_idx * out_features + out_feature_idx] = s_gelu_vals[out_feature_idx] / row_sum_exp;
    }
}

