class LinearReLU(nn.Module):
    """
    A custom module that fuses nn.Linear's matrix multiplication with bias addition and ReLU activation.
    It leverages PyTorch's highly optimized F.linear for the matrix multiplication
    and then applies a custom CUDA kernel for the fused bias_add + ReLU.
    """
    def __init__(self, in_features: int, out_features: int, bias: bool = True):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        # Weights are stored similar to nn.Linear
        self.weight = nn.Parameter(torch.empty(out_features, in_features))

        if bias:
            self.bias = nn.Parameter(torch.empty(out_features))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

        # Store a reference to the compiled custom CUDA function
        self.bias_relu_cuda_op = bias_relu_op.bias_relu_cuda

    def reset_parameters(self) -> None:
        # Initialize weights and biases using PyTorch's default nn.Linear initialization
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        # Perform matrix multiplication: input @ weight.T
        # F.linear is used without bias here, as bias will be added by the custom kernel
        output = F.linear(input, self.weight, None) 

        if self.bias is not None:
            # Apply the custom fused bias_add + ReLU kernel
            return self.bias_relu_cuda_op(output, self.bias)
        else:
            # If no bias, just apply ReLU using PyTorch's F.relu
            # (The primary fusion benefit is bias_add + ReLU, so F.relu is sufficient here)
            return F.relu(output)


class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_layer_sizes: list[int], output_size: int):
        """
        :param input_size: The number of input features
        :param hidden_layer_sizes: A list of ints containing the sizes of each hidden layer
        :param output_size: The number of output features
        """
        super(ModelNew, self).__init__()

        layers = []
        current_input_size = input_size

        # Replace nn.Linear + nn.ReLU pairs with the custom LinearReLU module for hidden layers
        for hidden_size in hidden_layer_sizes:
            layers.append(LinearReLU(current_input_size, hidden_size))
            current_input_size = hidden_size

        # The final layer remains a standard nn.Linear as there's no ReLU after it in the original model
        layers.append(nn.Linear(current_input_size, output_size))

        self.network = nn.Sequential(*layers)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        :param x: The input tensor, shape (batch_size, input_size)
        :return: The output tensor, shape (batch_size, output_size)
        """
        return self.network(x)

