import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

# Define the custom CUDA kernel source code
# This kernel implements a tiled matrix multiplication (GEMM) fused with Bias addition and ReLU.
# It computes Y = X * W^T + b.
# X is (M, K), W is (N, K), b is (N), Y is (M, N).
# Block size is fixed to 32x32 to maximize occupancy and fit in shared memory.

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void linear_relu_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int M, int K, int N,
    bool use_relu) {

    // Tiling dimensions
    const int TS = 32;

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Global row index for input and output
    int row = by * TS + ty;
    // Global column index for output (and row index for weights)
    int col = bx * TS + tx;

    // Shared memory for tiles
    // Padding [TS][TS+1] to avoid bank conflicts
    __shared__ scalar_t s_input[TS][TS + 1];
    __shared__ scalar_t s_weight[TS][TS + 1];

    scalar_t sum = 0.0;

    // Loop over the K dimension in chunks of TS
    for (int k = 0; k < K; k += TS) {
        // Load Input Tile: Input[row, k+tx]
        // Collaborative loading: thread (ty, tx) loads one element
        int in_col = k + tx;
        if (row < M && in_col < K) {
            s_input[ty][tx] = input[row * K + in_col];
        } else {
            s_input[ty][tx] = static_cast<scalar_t>(0.0);
        }

        // Load Weight Tile: Weight[col_chunk, k_chunk]
        // Weight matrix is (N, K). We need rows of W corresponding to columns of Output.
        // We load a TS x TS block of Weights.
        // The rows we need are (bx * TS) to (bx * TS + TS - 1).
        // The cols we need are k to k + TS - 1.
        // Thread (ty, tx) loads Weight[bx*TS + ty, k + tx].
        // This maps: s_weight[ty][tx] holds Weight[global_w_row, global_w_col]
        int w_row = bx * TS + ty;
        int w_col = k + tx;

        if (w_row < N && w_col < K) {
            s_weight[ty][tx] = weight[w_row * K + w_col];
        } else {
            s_weight[ty][tx] = static_cast<scalar_t>(0.0);
        }

        __syncthreads();

        // Compute partial dot product
        #pragma unroll
        for (int i = 0; i < TS; ++i) {
            // Y[row, col] = sum(X[row, k+i] * W[col, k+i])
            // X[row, k+i] is in s_input[ty][i]
            // W[col, k+i] is needed. 
            // 'col' implies global index bx*TS + tx.
            // Our load put Weight[bx*TS + u, k + v] into s_weight[u][v].
            // We need Weight[bx*TS + tx, k + i].
            // So we access s_weight[tx][i].
            sum += s_input[ty][i] * s_weight[tx][i];
        }

        __syncthreads();
    }

    // Store result
    if (row < M && col < N) {
        sum += bias[col];
        if (use_relu) {
            sum = sum > static_cast<scalar_t>(0.0) ? sum : static_cast<scalar_t>(0.0);
        }
        output[row * N + col] = sum;
    }
}

torch::Tensor linear_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, bool use_relu) {
    auto M = input.size(0);
    auto K = input.size(1);
    auto N = weight.size(0);

    auto output = torch::empty({M, N}, input.options());

    const int block_size = 32;
    dim3 dim_block(block_size, block_size);
    dim3 dim_grid((N + block_size - 1) / block_size, (M + block_size - 1) / block_size);

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "linear_relu_cuda", ([&] {
        linear_relu_kernel<scalar_t><<<dim_grid, dim_block>>>(
            input.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            bias.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            M, K, N, use_relu);
    }));

    return output;
}
"""

cpp_source = "torch::Tensor linear_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, bool use_relu);"

# Compile the inline CUDA code
linear_relu_module = load_inline(
    name="linear_relu_fused",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["linear_relu_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
