)

class FusedLinearReLU(nn.Module):
    def __init__(self, in_features, out_features, act=True):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.act = act

        # Initialize weights matching PyTorch nn.Linear default
        self.weight = nn.Parameter(torch.empty(out_features, in_features))
        self.bias = nn.Parameter(torch.empty(out_features))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, input):
        # Ensure input is contiguous for correct pointer arithmetic in CUDA
        return linear_relu_module.linear_relu_cuda(input.contiguous(), self.weight, self.bias, self.act)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_layer_sizes, output_size):
        super(ModelNew, self).__init__()

        self.layers = nn.ModuleList()
        current_input_size = input_size

        # Replace Linear + ReLU with fused FusedLinearReLU
        for hidden_size in hidden_layer_sizes:
            self.layers.append(FusedLinearReLU(current_input_size, hidden_size, act=True))
            current_input_size = hidden_size

        # Final layer is just Linear (act=False)
        self.layers.append(FusedLinearReLU(current_input_size, output_size, act=False))

    def forward(self, x):
        for layer in self.layers:
            x = layer(x)
        return x

