import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA source for fused Conv2d + ReLU + MaxPool2d
# This kernel fuses the convolution, activation, and pooling operations 
# into a single step for each output element of the pooled feature map.
fused_conv_relu_pool_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_relu_pool_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int in_c, int in_h, int in_w,
    int out_c, int out_h, int out_w,
    int k_size) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output_pixels = batch_size * out_c * out_h * out_w;
    if (idx >= total_output_pixels) return;

    // Output layout: (N, C_out, H_out, W_out)
    int ow = idx % out_w;
    int oh = (idx / out_w) % out_h;
    int c = (idx / (out_w * out_h)) % out_c;
    int n = idx / (out_w * out_h * out_c);

    float max_val = -1.0e38f;
    int k_size_sq = k_size * k_size;

    // Max pooling window of 2x2 with stride 2
    for (int ph = 0; ph < 2; ++ph) {
        for (int pw = 0; pw < 2; ++pw) {
            int conv_h = oh * 2 + ph;
            int conv_w = ow * 2 + pw;

            float sum = bias[c];
            // Perform convolution sum for the specific pixel
            for (int ic = 0; ic < in_c; ++ic) {
                int input_base = ((n * in_c + ic) * in_h + conv_h) * in_w + conv_w;
                int weight_base = (c * in_c + ic) * k_size_sq;

                for (int kh = 0; kh < k_size; ++kh) {
                    for (int kw = 0; kw < k_size; ++kw) {
                        sum += input[input_base + kh * in_w + kw] * weight[weight_base + kh * k_size + kw];
                    }
                }
            }
            // ReLU activation
            if (sum < 0.0f) sum = 0.0f;
            // Max Pool aggregation
            if (sum > max_val) max_val = sum;
        }
    }
    output[idx] = max_val;
}

