#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void relu_maxpool_3x3_s2_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                               int N, int C, int H, int W, int H_out, int W_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H_out * W_out;
    if (idx >= total) return;

    int ow = idx % W_out;
    int oh = (idx / W_out) % H_out;
    int c = (idx / (W_out * H_out)) % C;
    int n = idx / (W_out * H_out * C);

    int ih_base = oh * 2;
    int iw_base = ow * 2;
    int channel_offset = ((n * C + c) * H) * W;

    float max_val = 0.0f; // Since ReLU(x) >= 0

    #pragma unroll
    for (int kh = 0; kh < 3; ++kh) {
        int ih = ih_base + kh;
        if (ih < H) {
            #pragma unroll
            for (int kw = 0; kw < 3; ++kw) {
                int iw = iw_base + kw;
                if (iw < W) {
                    float val = input[channel_offset + ih * W + iw];
                    if (val > max_val) max_val = val;
                }
            }
        }
    }
    output[idx] = max_val;
}

__global__ void relu_inplace_kernel(float* data, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
