__global__ void maxpool3x3_kernel(const float* __restrict__ inp, float* __restrict__ out, int B, int C, int H, int W) {
    int w = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;
    int bc = blockIdx.z; // Corresponds to batch * channels

    if (w < W && h < H) {
