                if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                    float val = inp[(bc * H + ih) * W + iw];
                    if (val > max_v) max_v = val;
                }
            }
        }
        out[(bc * H + h) * W + w] = max_v;
    }
}

__global__ void concat4_kernel(
    const float* __restrict__ b1,
    const float* __restrict__ b2,
    const float* __restrict__ b3,
    const float* __restrict__ b4,
    float* __restrict__ out,
    int hw, int B, int C1, int C2, int C3, int C4
) {
    int spatial_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (spatial_idx >= hw) return;

    int b_idx = blockIdx.y;
    int c_idx = blockIdx.z;
    int total_c = C1 + C2 + C3 + C4;

