// Element-wise ReLU kernel
__global__ void relu_kernel(const float* __restrict__ inp, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = inp[idx] > 0.0f ? inp[idx] : 0.0f;
    }
}

// Custom 4-way Concatenation kernel for Inception modules
__global__ void inception_cat_kernel(
    const float* __restrict__ b1, 
    const float* __restrict__ b2, 
    const float* __restrict__ b3, 
    const float* __restrict__ b4,
    float* __restrict__ out,
    int N, int H, int W,
    int C1, int C2, int C3, int C4) {

    int total_C = C1 + C2 + C3 + C4;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int hw = H * W;
    int total_elements = N * total_C * hw;

    if (idx < total_elements) {
        int s_idx = idx % hw;
        int remaining = idx / hw;
        int c_idx = remaining % total_C;
        int n_idx = remaining / total_C;

        float val;
        if (c_idx < C1) {
            val = b1[(n_idx * C1 + c_idx) * hw + s_idx];
        } else if (c_idx < C1 + C2) {
            val = b2[(n_idx * C2 + (c_idx - C1)) * hw + s_idx];
        } else if (c_idx < C1 + C2 + C3) {
            val = b3[(n_idx * C3 + (c_idx - C1 - C2)) * hw + s_idx];
        } else {
            val = b4[(n_idx * C4 + (c_idx - C1 - C2 - C3)) * hw + s_idx];
        }
        out[idx] = val;
    }
}

// Global Average Pooling + Flatten kernel
__global__ void global_avg_pool_kernel(const float* __restrict__ inp, float* __restrict__ out, int N, int C, int HW) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * C) {
        float sum = 0.0f;
        int start = idx * HW;
        for (int i = 0; i < HW; ++i) {
            sum += inp[start + i];
        }
        out[idx] = sum / (float)HW;
    }
}

