# Define custom CUDA kernels for VGG-specific fusions
# Fusing ReLU and MaxPool2d (2x2, stride 2) into a single kernel 
# significantly reduces memory access by combining activation and pooling.
vgg_custom_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void relu_maxpool2d_kernel(const float* __restrict__ input, 
                                      float* __restrict__ output, 
                                      int batch, int channels, 
                                      int in_h, int in_w, 
                                      int out_h, int out_w) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * channels * out_h * out_w;
    if (idx < total) {
        // Inverse indexing from a flat index to (n, c, oh, ow)
        int ow = idx % out_w;
        int oh = (idx / out_w) % out_h;
        int c = (idx / (out_w * out_h)) % channels;
        int n = idx / (out_w * out_h * channels);

        // Calculate top-left coordinate of the 2x2 pool window
        int ih = oh << 1;
        int iw = ow << 1;

        // Memory offset for the top-left element
        int offset = ((n * channels + c) * in_h + ih) * in_w + iw;

        // Load the 2x2 grid elements
        float v0 = input[offset];
        float v1 = input[offset + 1];
        float v2 = input[offset + in_w];
        float v3 = input[offset + in_w + 1];

        // Compute max for Pooling and apply ReLU
        float res = fmaxf(fmaxf(v0, v1), fmaxf(v2, v3));
        output[idx] = fmaxf(0.0f, res);
    }
}

torch::Tensor relu_maxpool2d_cuda(torch::Tensor input) {
    // Ensure input is contiguous before passing to the kernel
    auto input_c = input.contiguous();
    int batch = input_c.size(0);
    int channels = input_c.size(1);
    int in_h = input_c.size(2);
    int in_w = input_c.size(3);
    int out_h = in_h / 2;
    int out_w = in_w / 2;

    auto output = torch::empty({batch, channels, out_h, out_w}, input_c.options());
    int total = batch * channels * out_h * out_w;

    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    relu_maxpool2d_kernel<<<blocks, threads>>>(
        input_c.data_ptr<float>(), output.data_ptr<float>(),
        batch, channels, in_h, in_w, out_h, out_w);

    return output;
}
