        int h_out = (idx / W_out) % H_out;
        int w_out = idx % W_out;

        // Calculate input region start coordinates for a 2x2 kernel with stride 2
        int h_start = h_out * 2; // stride = 2
        int w_start = w_out * 2; // stride = 2

