#include <cuda_runtime.h>
#include <cmath> // For sqrtf and fmaxf

// Fused BatchNorm (inference) + ReLU kernel
// This kernel operates on 4D tensors (N, C, H, W).
// Each thread processes one element of the output tensor.
__global__ void fused_bn_relu_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    const float* running_mean,
    const float* running_var,
    float eps,
    float* output,
    int N, int C, int H, int W) {

