class FusedBNReLU(nn.Module):
    """
    Fuses BatchNorm2d and ReLU into a single CUDA kernel for inference.
    Falls back to standard PyTorch implementation during training.
    """
    def __init__(self, bn_module, fused_op):
        super(FusedBNReLU, self).__init__()
        self.register_buffer('weight', bn_module.weight)
        self.register_buffer('bias', bn_module.bias)
        self.register_buffer('running_mean', bn_module.running_mean)
        self.register_buffer('running_var', bn_module.running_var)
        self.eps = bn_module.eps
        self.fused_op = fused_op

    def forward(self, x):
        if not x.is_cuda or self.training:
            return F.relu(F.batch_norm(x, self.running_mean, self.running_var, self.weight, self.bias, self.training, 0.1, self.eps))

        # Precompute fused scale and shift: y = x * scale + shift
        # In actual deployment, these can be cached if weights don't change.
        scale = self.weight / torch.sqrt(self.running_var + self.eps)
        shift = self.bias - self.running_mean * scale
        return self.fused_op.fused_bn_relu_cuda(x, scale, shift)

