// -----------------------------------------------------------------------------------------
// Kernel: 2x2 Average Pooling
// Fixed kernel_size=2, stride=2. Matches nn.AvgPool2d(2, stride=2)
// -----------------------------------------------------------------------------------------
__global__ void avgpool2x2_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                  int C, int H, int W, int out_H, int out_W, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Map linear index to output coordinates (n, c, oh, ow)
        int temp = idx;
        int ow = temp % out_W; temp /= out_W;
        int oh = temp % out_H; temp /= out_H;
        int c  = temp % C;     temp /= C;
        int n  = temp;

        // Input top-left coordinates
        int ih = oh * 2;
        int iw = ow * 2;

        // Linear input index
        int in_base = ((n * C + c) * H + ih) * W + iw;

        // Sum 2x2 block
