#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void cat2d_kernel(
    const float* a_ptr,
    const float* b_ptr,
    float* out_ptr,
    int batch_size,
    int a_channels,
    int b_channels,
    int height,
    int width
