#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// ------------------------------------------------------------------
// Kernel 1: Fused Depthwise Convolution 3x3 + Bias + ReLU
// ------------------------------------------------------------------
// Supports stride 1 or 2, fixed padding=1, dilation=1.
// Input: [N, C, H, W]
// Weight: [C, 1, 3, 3] (standard PyTorch depthwise weight shape)
// Output: [N, C, H_out, W_out]
__global__ void depthwise_3x3_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int H_out, int W_out,
    int stride) {

    // Global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H_out * W_out;

    if (idx < total_elements) {
        // Decode index (n, c, h_out, w_out) from linear idx
        // Layout is NCHW
        int w_out = idx % W_out;
        int rem = idx / W_out;
        int h_out = rem % H_out;
        rem = rem / H_out;
        int c = rem % C;
        int n = rem / C;

        // Calculate input window top-left (padding=1)
        int h_in_base = h_out * stride - 1;
        int w_in_base = w_out * stride - 1;

        float sum = 0.0f;

        // Weight is stored as [C, 1, 3, 3], so flat offset is c * 9
        const float* w_ptr = weight + c * 9;

        #pragma unroll
        for (int i = 0; i < 3; ++i) {
            #pragma unroll
            for (int j = 0; j < 3; ++j) {
                int h_in = h_in_base + i;
                int w_in = w_in_base + j;

                // Boundary check
                if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                    sum += input[((n * C + c) * H + h_in) * W + w_in] * w_ptr[i * 3 + j];
                }
            }
        }

        // Add bias
        if (bias != nullptr) {
            sum += bias[c];
        }

        // Apply ReLU
        output[idx] = fmaxf(sum, 0.0f);
    }
}

// ------------------------------------------------------------------
// Kernel 2: Fused Pointwise Convolution 1x1 + Bias + ReLU
// ------------------------------------------------------------------
// Input: [N, Cin, H, W]
// Weight: [Cout, Cin] (PyTorch 1x1 weights are [Cout, Cin, 1, 1])
// Output: [N, Cout, H, W]
__global__ void pointwise_1x1_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int Cin, int Cout, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int HW = H * W;
    int total_elements = N * Cout * HW;

    if (idx < total_elements) {
        // Decode index (n, cout, h, w)
        // Since we treat H,W as a flat HW block: (n, cout, hw)
        int hw = idx % HW;
        int rem = idx / HW;
        int cout = rem % Cout;
        int n = rem / Cout;

        float sum = 0.0f;

        // Input pointer base for this (n, :, hw) location
        // Input layout is N, Cin, HW. We need input[n, cin, hw]
        // Offset = n * (Cin * HW) + cin * HW + hw
        int input_n_offset = n * Cin * HW;

        // Weight row for this output channel
        const float* w_row = weight + cout * Cin;

        for (int cin = 0; cin < Cin; ++cin) {
            sum += input[input_n_offset + cin * HW + hw] * w_row[cin];
        }

        if (bias != nullptr) {
            sum += bias[cout];
        }

        // ReLU
        output[idx] = fmaxf(sum, 0.0f);
    }
}

// Wrapper for Depthwise
torch::Tensor depthwise_conv_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride) {
