            conv3 = nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False)
            bn3 = nn.BatchNorm2d(oup)
            block_layers.append(FusedConvBn(conv3, bn3))

            return nn.Sequential(*block_layers), use_res_connect

        # MobileNetV2 architecture parameters
        input_channel = 32
        last_channel = 1280
        inverted_residual_setting = [
            # t (expand_ratio), c (output_channel), n (num_blocks), s (stride)
            [1, 16, 1, 1],
            [6, 24, 2, 2],
            [6, 32, 3, 2],
            [6, 64, 4, 2],
            [6, 96, 3, 1],
            [6, 160, 3, 2],
            [6, 320, 1, 1],
        ]

        # Building first layer: Conv + BN + ReLU6
        features = []
        conv_init = nn.Conv2d(3, input_channel, 3, 2, 1, bias=False)
        bn_init = nn.BatchNorm2d(input_channel)
        features.append(FusedConvBnReLU6(conv_init, bn_init))

        # Building inverted residual blocks
        for t, c, n, s in inverted_residual_setting:
            output_channel = _make_divisible(c, 8)
            for i in range(n):
                stride = s if i == 0 else 1
                block, use_res_connect = _inverted_residual_block(input_channel, output_channel, stride, expand_ratio=t)

                if use_res_connect:
                    features.append(InvertedResidualFused(block))
                else:
                    features.append(block)
                input_channel = output_channel

        # Building last several layers: Conv + BN + ReLU6
        conv_final = nn.Conv2d(input_channel, last_channel, 1, 1, 0, bias=False)
        bn_final = nn.BatchNorm2d(last_channel)
        features.append(FusedConvBnReLU6(conv_final, bn_final))

        # Final layer: AdaptiveAvgPool2d
        features.append(nn.AdaptiveAvgPool2d((1, 1)))

        self.features = nn.Sequential(*features)

        # Classifier
        self.classifier = nn.Sequential(
            nn.Dropout(0.0), # Dropout is typically a no-op during inference
            nn.Linear(last_channel, num_classes),
        )

        # Weight initialization
        for m in self.modules():
            if isinstance(m, nn.Conv2d):
                nn.init.kaiming_normal_(m.weight, mode='fan_out')
                if m.bias is not None:
                    nn.init.zeros_(m.bias)
            elif isinstance(m, (FusedConvBnReLU6, FusedConvBn)):
                # Initialize the BatchNorm parameters within our fused modules
                nn.init.ones_(m.bn_weight)
                nn.init.zeros_(m.bn_bias)
                # running_mean and running_var are buffers, usually initialized to 0 and 1 respectively
                nn.init.zeros_(m.bn_running_mean)
                nn.init.ones_(m.bn_running_var)
            elif isinstance(m, nn.Linear):
                nn.init.normal_(m.weight, 0, 0.01)
                nn.init.zeros_(m.bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Forward pass of the optimized MobileNetV2 model.

        :param x: The input tensor, shape (batch_size, 3, 224, 224)
        :return: The output tensor, shape (batch_size, num_classes)
        """
        x = self.features(x)
        x = x.view(x.size(0), -1) # Flatten for the linear classifier
        x = self.classifier(x)
        return x

