#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Helper device function for fused BN+ReLU6 logic
__device__ __forceinline__ float bn_relu6_op(float val, float m, float v, float g, float b, float eps) {
    float inv_std = rsqrtf(v + eps);
    float out = (val - m) * inv_std * g + b;
    return fminf(fmaxf(out, 0.0f), 6.0f);
}

// Helper device function for fused BN logic (no activation)
__device__ __forceinline__ float bn_op(float val, float m, float v, float g, float b, float eps) {
    float inv_std = rsqrtf(v + eps);
    return (val - m) * inv_std * g + b;
}

// Kernel 1: Fused Depthwise Convolution + BatchNorm + ReLU6
// Supports generic kernel size/stride/padding via arguments
__global__ void fused_dw_conv_bn_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ bn_mean,
    const float* __restrict__ bn_var,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int H_out, int W_out,
    int kernel_size, int stride, int padding,
    float epsilon
) {
    // Grid layout:
    // y dimension: covers Batch(N) and Channels(C) -> idx = n*C + c
    // x dimension: covers spatial output (H_out * W_out)

    int nc = blockIdx.y;
    int n = nc / C;
    int c = nc % C;

    int spatial_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (spatial_idx >= H_out * W_out) return;

    int h_out = spatial_idx / W_out;
    int w_out = spatial_idx % W_out;

    int h_in_start = h_out * stride - padding;
    int w_in_start = w_out * stride - padding;

    float sum = 0.0f;

    // Weight pointer for channel c. 
    // PyTorch Depthwise weight shape: (C, 1, K, K) -> effectively (C, K, K)
    const float* w_ptr = weight + c * kernel_size * kernel_size;

    // Simple convolution loop
    for (int kh = 0; kh < kernel_size; ++kh) {
        int h_in = h_in_start + kh;
        if (h_in >= 0 && h_in < H) {
            int h_offset = ((n * C + c) * H + h_in) * W;
            for (int kw = 0; kw < kernel_size; ++kw) {
                int w_in = w_in_start + kw;
                if (w_in >= 0 && w_in < W) {
                    sum += input[h_offset + w_in] * w_ptr[kh * kernel_size + kw];
                }
            }
        }
    }

    // Apply fused BN and ReLU6
    // Output index
    int out_idx = ((n * C + c) * H_out + h_out) * W_out + w_out;

    output[out_idx] = bn_relu6_op(
        sum, 
        bn_mean[c], bn_var[c], bn_weight[c], bn_bias[c], 
        epsilon
    );
}

// Wrapper for Kernel 1
torch::Tensor fused_dw_conv_bn_relu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
