    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int H_out = (H + 2 * padding - kernel_size) / stride + 1;
    int W_out = (W + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    int total_spatial = H_out * W_out;
    int threads = 256;
    int blocks_x = (total_spatial + threads - 1) / threads;

    // Launch configuration:
    // Grid Y: N * C (Independent channels/batches)
    // Grid X: Spatial chunks
    dim3 grid(blocks_x, N * C);

    fused_dw_conv_bn_relu_kernel<<<grid, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        bn_mean.data_ptr<float>(),
        bn_var.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W, H_out, W_out,
