) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // determine channel index for BN parameters
        // idx = ((n * C) + c) * HW + hw
        int c = (idx / HW) % C;
        output[idx] = bn_relu6_op(
            input[idx], bn_mean[c], bn_var[c], bn_weight[c], bn_bias[c], epsilon
        );
    }
}

torch::Tensor fused_bn_relu6_cuda(
    torch::Tensor input,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor bn_mean,
    torch::Tensor bn_var,
