    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C_out * H * W;

    if (idx < total_elements) {
        int n = idx / (C_out * H * W);
        int c_out = (idx / (H * W)) % C_out;
        int h = (idx / W) % H;
        int w = idx % W;

        float conv_sum = 0.0f;
        // conv_weight is (C_out, C_in, 1, 1) -> effectively (C_out, C_in)
        // x is (N, C_in, H, W)
        for (int c_in_idx = 0; c_in_idx < C_in; ++c_in_idx) {
            conv_sum += x[n * C_in * H * W + c_in_idx * H * W + h * W + w] *
                        conv_weight[c_out * C_in + c_in_idx];
        }

        // BatchNorm: y = (x - mean) / sqrt(var + eps) * weight + bias
        float bn_val = bn_weight[c_out] * (conv_sum - bn_mean[c_out]) /
                       sqrtf(bn_var[c_out] + eps) + bn_bias[c_out];

        // ReLU6: out = min(max(bn_val, 0.0f), 6.0f)
        out[idx] = fminf(fmaxf(bn_val, 0.0f), 6.0f);
    }
}

// Fused Depthwise Conv + BatchNorm + ReLU6 Kernel
// This kernel performs a depthwise convolution, followed by BatchNorm, and then ReLU6 activation.
__global__ void fused_depthwise_conv_bn_relu6_kernel(
    const float* __restrict__ x,
    const float* __restrict__ conv_weight,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ bn_mean,
    const float* __restrict__ bn_var,
    float* __restrict__ out,
    int N, int C, int H_in, int W_in, int H_out, int W_out,
    int kernel_size, int stride, int padding, float eps) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H_out * W_out;

    if (idx < total_elements) {
        int n = idx / (C * H_out * W_out);
        int c = (idx / (H_out * W_out)) % C; // Channel index
        int h_out = (idx / W_out) % H_out;
        int w_out = idx % W_out;

        float conv_sum = 0.0f;
        // conv_weight is (C, 1, K, K) -> effectively (C, K, K)
        // x is (N, C, H_in, W_in)
        for (int k_h = 0; k_h < kernel_size; ++k_h) {
            for (int k_w = 0; k_w < kernel_size; ++k_w) {
                int h_in = h_out * stride + k_h - padding;
                int w_in = w_out * stride + k_w - padding;

                // Check bounds for input tensor
                if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                    conv_sum += x[n * C * H_in * W_in + c * H_in * W_in + h_in * W_in + w_in] *
                                conv_weight[c * kernel_size * kernel_size + k_h * kernel_size + k_w];
                }
            }
        }

        // BatchNorm
        float bn_val = bn_weight[c] * (conv_sum - bn_mean[c]) /
                       sqrtf(bn_var[c] + eps) + bn_bias[c];

        // ReLU6
        out[idx] = fminf(fmaxf(bn_val, 0.0f), 6.0f);
    }
}

// Fused 1x1 Conv + BatchNorm + Optional Residual Add Kernel
// This kernel performs a 1x1 convolution, followed by BatchNorm, and then optionally adds a residual connection.
// It's used for the projection phase of the MBConv block.
__global__ void fused_conv1x1_bn_add_kernel(
    const float* __restrict__ x,
    const float* __restrict__ identity, // Can be nullptr if not used
    const float* __restrict__ conv_weight,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ bn_mean,
    const float* __restrict__ bn_var,
    float* __restrict__ out,
    int N, int C_in, int H, int W, int C_out, float eps, bool use_residual) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C_out * H * W;

    if (idx < total_elements) {
        int n = idx / (C_out * H * W);
        int c_out = (idx / (H * W)) % C_out;
        int h = (idx / W) % H;
        int w = idx % W;

        float conv_sum = 0.0f;
        // conv_weight is (C_out, C_in, 1, 1) -> effectively (C_out, C_in)
        // x is (N, C_in, H, W)
        for (int c_in_idx = 0; c_in_idx < C_in; ++c_in_idx) {
            conv_sum += x[n * C_in * H * W + c_in_idx * H * W + h * W + w] *
                        conv_weight[c_out * C_in + c_in_idx];
        }

        // BatchNorm
        float bn_val = bn_weight[c_out] * (conv_sum - bn_mean[c_out]) /
                       sqrtf(bn_var[c_out] + eps) + bn_bias[c_out];

        // Optional Residual Add
        if (use_residual) {
            out[idx] = bn_val + identity[idx]; // identity has same shape as output
        } else {
            out[idx] = bn_val;
        }
    }
}

