// Fused BatchNorm + ReLU kernel
// This kernel applies BatchNorm using provided running statistics (suitable for inference)
// followed by a ReLU activation.
__global__ void fused_bn_relu_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    const float* running_mean,
    const float* running_var,
    float epsilon,
    float* output,
    int total_elements,
    int C, int H, int W) { // C, H, W are for channel indexing in NCHW format

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Calculate channel index for the current element (assuming NCHW layout)
        // idx = n*C*H*W + c*H*W + h*W + w
        // c = (idx / (H*W)) % C
        int c = (idx / (H * W)) % C;

        float val = input[idx];
        float mean = running_mean[c];
        float var = running_var[c];
        float gamma = weight[c];
        float beta = bias[c];

        // BatchNorm calculation: y = (x - mean) / sqrt(var + eps) * gamma + beta
        float bn_val = (val - mean) / sqrtf(var + epsilon) * gamma + beta;

        // ReLU activation: max(0, y)
        output[idx] = fmaxf(0.0f, bn_val);
    }
}

// Fused ReLU kernel
