template <typename scalar_t>
__global__ void channel_shuffle_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    int total_elements,
    int C, int H, int W,
    int groups,
    int channels_per_group,
    int S) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Decompose linear index to find (n, c, h, w)
        // idx = n * (C * S) + c * S + hw
        // S = H * W

        int hw = idx % S;
        int tmp = idx / S;
        int c = tmp % C;
        int n_offset = (tmp / C) * C * S; // Base offset for the batch item

        // Shuffle logic:
        // Current channel c corresponds to group g and inner index k
        // c = g * channels_per_group + k
        int g = c / channels_per_group;
        int k = c % channels_per_group;

        // Target channel c_out corresponds to (k, g)
        // c_out = k * groups + g
        int c_out = k * groups + g;

        // Reconstruct output index
        int out_idx = n_offset + c_out * S + hw;

        output[out_idx] = input[idx];
    }
}

