#include <torch/extension.h>
#include <cuda_runtime.h>

// Optimized ReLU kernel
__global__ void relu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = fmaxf(0.0f, val);
    }
}

// Global Average Pooling kernel using warp-level synchronization for spatial reduction
__global__ void gap_kernel_warp(const float* __restrict__ input, float* __restrict__ output, int N, int C, int HW, float invHW) {
    int n_c = blockIdx.x; // Each block handles one (batch, channel) pair
    int tid = threadIdx.x; // 32 threads per block

    if (n_c < N * C) {
        float sum = 0.0f;
        const float* ptr = input + n_c * HW;

        // Strided loop over spatial dimensions
        for (int i = tid; i < HW; i += 32) {
            sum += ptr[i];
        }

        // Warp reduction
        for (int offset = 16; offset > 0; offset /= 2) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }

        // Thread 0 writes the average to the output
        if (tid == 0) {
            output[n_c] = sum * invHW;
        }
