    relu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}

// ----------------------------------------------------------------------------
// Custom Global Average Pooling (GAP) Kernel
// Performs Mean Pooling over H and W dimensions: (N, C, H, W) -> (N, C)
// ----------------------------------------------------------------------------
__global__ void gap_kernel(const float* __restrict__ x, float* __restrict__ out, int N, int C, int H, int W) {
    // We launch a grid where x-dimension is N and y-dimension is C.
    // Each block handles one (n, c) channel plane.
    int n = blockIdx.x;
    int c = blockIdx.y;
    int tid = threadIdx.x;

    // Calculate offset for the specific channel
    int offset = n * (C * H * W) + c * (H * W);
    int spatial_size = H * W;

    // Load and sum elements for this channel
    float sum = 0.0f;
    for (int i = tid; i < spatial_size; i += blockDim.x) {
        sum += x[offset + i];
    }

    // Shared memory for block reduction
    extern __shared__ float sdata[];
    sdata[tid] = sum;
    __syncthreads();

    // Parallel reduction in shared memory (assumes blockDim.x is power of 2, e.g., 256)
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Write result to global memory
    if (tid == 0) {
        out[n * C + c] = sdata[0] / (float)spatial_size;
    }
}

