#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// ------------------------------------------------------------------
// Kernel 1: Patchify
// Replaces img.unfold(...).reshape(...)
// Flattens patches into a contiguous tensor suitable for Linear layer
// ------------------------------------------------------------------
__global__ void patchify_kernel(const float* __restrict__ img, float* __restrict__ out, 
                                int N, int C, int H, int W, int P, 
                                int Hp, int Wp) {
    // Total elements to process
    int total = N * C * H * W;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total) {
        // We want to produce an output layout corresponding to:
        // (B, C, Hp, Wp, P, P) flattened.
        // This corresponds to the PyTorch behavior of reshape after unfold.

        int temp = idx;
        int px = temp % P; temp /= P;
        int py = temp % P; temp /= P;
        int wp = temp % Wp; temp /= Wp;
        int hp = temp % Hp; temp /= Hp;
        int c = temp % C; temp /= C;
        int b = temp; 

        // Map back to source image coordinates (N, C, H, W)
        int src_y = hp * P + py;
        int src_x = wp * P + px;

        int src_idx = ((b * C + c) * H + src_y) * W + src_x;
        out[idx] = img[src_idx];
    }
}

torch::Tensor patchify_cuda(torch::Tensor img, int P) {
    int N = img.size(0);
    int C = img.size(1);
    int H = img.size(2);
    int W = img.size(3);
    int Hp = H / P;
    int Wp = W / P;

    // Allocate output with same size as input, but we will view it differently later
    auto out = torch::empty_like(img);

    int total = N * C * H * W;
    const int block_size = 256;
    const int num_blocks = (total + block_size - 1) / block_size;

    patchify_kernel<<<num_blocks, block_size>>>(img.data_ptr<float>(), out.data_ptr<float>(), 
                                                N, C, H, W, P, Hp, Wp);

    // View as (Batch, NumPatches, PatchDim)
    // NumPatches = Hp * Wp
    // PatchDim = C * P * P
    return out.view({N, Hp * Wp, C * P * P});
}

// ------------------------------------------------------------------
// Kernel 2: Fused Prep (Concat CLS + Add Pos Embedding)
// Replaces torch.cat([cls, x], dim=1) + pos_embedding
// ------------------------------------------------------------------
__global__ void fused_prep_kernel(const float* __restrict__ x, 
                                  const float* __restrict__ cls_token, 
                                  const float* __restrict__ pos_embed, 
                                  float* __restrict__ out,
                                  int B, int N_patches, int Dim) {
    // x: (B, N_patches, Dim)
    // cls_token: (1, 1, Dim)
    // pos_embed: (1, N_patches+1, Dim)
    // out: (B, N_patches+1, Dim)

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * (N_patches + 1) * Dim;

    if (idx < total) {
        // Map linear index to (b, seq_idx, d)
        int d = idx % Dim;
        int temp = idx / Dim;
        int seq_idx = temp % (N_patches + 1);
        int b = temp / (N_patches + 1);

        float val;
        if (seq_idx == 0) {
            // CLS token position
            // cls_token is (1, 1, Dim), so just index d
            // pos_embed is (1, N_patches+1, Dim), index (0, 0, d) -> d
            val = cls_token[d] + pos_embed[d]; 
        } else {
            // Patch position (shifted by 1)
            int patch_idx = seq_idx - 1;
            // x flat index: b * (N_patches * Dim) + patch_idx * Dim + d
            int x_idx = (b * N_patches + patch_idx) * Dim + d;

            // pos_embed index: 0 * ... + seq_idx * Dim + d
            int pos_idx = seq_idx * Dim + d;

            val = x[x_idx] + pos_embed[pos_idx];
        }
        out[idx] = val;
    }
}

torch::Tensor fused_prep_cuda(torch::Tensor x, torch::Tensor cls_token, torch::Tensor pos_embed) {
    int B = x.size(0);
    int N_patches = x.size(1);
    int Dim = x.size(2);

    auto out = torch::empty({B, N_patches + 1, Dim}, x.options());

    int total = B * (N_patches + 1) * Dim;
    const int block_size = 256;
    const int num_blocks = (total + block_size - 1) / block_size;

    fused_prep_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), 
        cls_token.data_ptr<float>(), 
        pos_embed.data_ptr<float>(), 
        out.data_ptr<float>(), 
        B, N_patches, Dim);

    return out;
}

// ------------------------------------------------------------------
// Kernel 3: Fast GELU
// Replaces nn.GELU
// ------------------------------------------------------------------
__global__ void gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        // Approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
        out[idx] = 0.5f * val * (1.0f + erff(val * 0.70710678f));
    }
}

torch::Tensor gelu_cuda(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
