// Helper for GELU (approximate)
// Using the standard approximation from PyTorch's F.gelu
__device__ float gelu_approx(float x) {
    return 0.5f * x * (1.0f + tanhf(sqrtf(2.0f / M_PI_F) * (x + 0.044715f * x * x * x)));
