// Kernel for Fused Concatenation, Positional Embedding Addition, and Dropout
// Fuses: torch.cat((cls_tokens, x), dim=1) + x += self.pos_embedding + self.dropout(x)
__global__ void fused_cat_add_dropout_kernel(
    const float* cls_tokens_ptr,
    const float* patch_embeddings_ptr,
    const float* pos_embedding_ptr,
    float* output_ptr,
    int B, int P, int D, // batch_size, num_patches, dim
    float dropout_p,
    bool training,
    unsigned long long seed) {

    int total_elements = B * (P + 1) * D;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        int b = idx / ((P + 1) * D);
        int rem = idx % ((P + 1) * D);
