    int nWh = _H / ws;
    int total = B * nWh * nWw * ws * ws * C;
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= total) return;

    int c = i % C;
    int w_win = (i / C) % ws;
    int h_win = (i / (C * ws)) % ws;
    int win_w = (i / (C * ws * ws)) % nWw;
    int win_h = (i / (C * ws * ws * nWw)) % nWh;
    int b = i / (C * ws * ws * nWw * nWh);

    int h_in = win_h * ws + h_win - Pt;
    int w_in = win_w * ws + w_win - Pl;

    if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
        out[i] = x[((b * H + h_in) * W + w_in) * C + c];
    } else {
        out[i] = 0.0f;
    }
}

__global__ void window_reverse_sliced_kernel(const float* x, float* out, int B, int H, int W, int C, int ws, int Pl, int Pr, int Pt, int Pb) {
    int total = B * H * W * C;
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= total) return;

    int _H = H + Pt + Pb;
    int _W = W + Pl + Pr;
    int nWw = _W / ws;
    int nWh = _H / ws;

    int c = i % C;
    int w = (i / C) % W;
    int h = (i / (C * W)) % H;
    int b = i / (C * W * H);

    int h_pad = h + Pt;
    int w_pad = w + Pl;

    int win_h = h_pad / ws;
    int h_win = h_pad % ws;
    int win_w = w_pad / ws;
    int w_win = w_pad % ws;

    int b_new = b * (nWh * nWw) + win_h * nWw + win_w;
    int x_idx = (((b_new * ws + h_win) * ws + w_win) * C) + c;

    out[i] = x[x_idx];
}

torch::Tensor patch_merging_cuda(torch::Tensor input, int H, int W) {
    auto B = input.size(0);
    auto C = input.size(3);
    auto output = torch::empty({B, H / 2, W / 2, 4 * C}, input.options());
    int total_elements = output.numel();
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;
    patch_merging_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), B, H, W, C);
    return output;
}

torch::Tensor window_partition_padded_cuda(torch::Tensor x, int ws, int Pl, int Pr, int Pt, int Pb) {
    int B = x.size(0);
    int H = x.size(1);
    int W = x.size(2);
    int C = x.size(3);
    int _H = H + Pt + Pb;
    int _W = W + Pl + Pr;
    int nWh = _H / ws;
    int nWw = _W / ws;
    auto output = torch::empty({B, nWh, nWw, ws, ws, C}, x.options());
    int total_elements = output.numel();
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;
    window_partition_padded_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), output.data_ptr<float>(), B, H, W, C, ws, Pl, Pr, Pt, Pb);
    return output;
}

torch::Tensor window_reverse_sliced_cuda(torch::Tensor x, int H, int W, int ws, int Pl, int Pr, int Pt, int Pb) {
    int B = x.size(0) / (( (H+Pt+Pb)/ws ) * ( (W+Pl+Pr)/ws ));
