import torch
import torch.nn as nn
import torch.nn.functional as F
from itertools import repeat
import collections.abc
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernels ---

# Kernel for PatchMerging's unfold and concat part
# This kernel replaces the slicing, concatenation, and view operations in PatchMerging.
patch_unfold_and_concat_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void patch_unfold_and_concat_kernel(
    const float* x_ptr, float* out_ptr,
    int B, int H, int W, int C,
    int H_out, int W_out, int C_out_total) { // C_out_total = 4*C

    int total_elements = B * H_out * W_out * C_out_total;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Deconstruct idx to (b, h_out, w_out, c_out)
        int c_out = idx % C_out_total;
        int rem = idx / C_out_total;
        int w_out = rem % W_out;
        rem /= W_out;
        int h_out = rem % H_out;
        int b = rem / H_out;

        // Calculate original (h_in, w_in, c_in) based on c_out
        int h_in, w_in, c_in;

        if (c_out < C) { // x0: (2*h_out, 2*w_out, c_out)
            h_in = 2 * h_out;
            w_in = 2 * w_out;
            c_in = c_out;
        } else if (c_out < 2 * C) { // x1: (2*h_out+1, 2*w_out, c_out - C)
            h_in = 2 * h_out + 1;
            w_in = 2 * w_out;
            c_in = c_out - C;
        } else if (c_out < 3 * C) { // x2: (2*h_out, 2*w_out+1, c_out - 2*C)
            h_in = 2 * h_out;
            w_in = 2 * w_out + 1;
            c_in = c_out - 2 * C;
        } else { // x3: (2*h_out+1, 2*w_out+1, c_out - 3*C)
            h_in = 2 * h_out + 1;
            w_in = 2 * w_out + 1;
            c_in = c_out - 3 * C;
        }

        // Calculate input index
        // x is (B, H*W, C) but conceptually (B, H, W, C) for indexing
        // input_idx = b * (H * W * C) + (h_in * W + w_in) * C + c_in;
        int input_idx = b * (H * W * C) + h_in * (W * C) + w_in * C + c_in;

        out_ptr[idx] = x_ptr[input_idx];
    }
}

torch::Tensor patch_unfold_and_concat_cuda(torch::Tensor x, int H, int W) {
    // x: (B, H*W, C)
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be 3D (B, L, C)");
    TORCH_CHECK(H % 2 == 0 && W % 2 == 0, "H and W must be even for patch merging");

    int B = x.size(0);
    int L = x.size(1); // H*W
    int C = x.size(2);

    TORCH_CHECK(L == H * W, "Input feature length L does not match H*W");

    int H_out = H / 2;
    int W_out = W / 2;
    int C_out_total = 4 * C;

    auto out = torch::empty({B, H_out * W_out, C_out_total}, x.options());

    const int block_size = 256;
    int total_elements = B * H_out * W_out * C_out_total;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    patch_unfold_and_concat_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), out.data_ptr<float>(),
        B, H, W, C, H_out, W_out, C_out_total);

    return out;
}
"""

patch_unfold_and_concat_cpp_source = (
    "torch::Tensor patch_unfold_and_concat_cuda(torch::Tensor x, int H, int W);"
)

patch_unfold_and_concat_op = load_inline(
    name="patch_unfold_and_concat",
    cpp_sources=patch_unfold_and_concat_cpp_source,
    cuda_sources=patch_unfold_and_concat_source,
    functions=["patch_unfold_and_concat_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)


# Kernel for window_partition operation
# This kernel replaces the view, permute, contiguous, and reshape operations for window partitioning.
window_partition_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void window_partition_kernel(
    const float* x_ptr, float* windows_ptr,
    int B, int H, int W, int C, int window_size,
    int num_windows_h, int num_windows_w) { // num_windows_h = H/window_size, num_windows_w = W/window_size

    int total_elements = B * num_windows_h * num_windows_w * window_size * window_size * C;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Deconstruct idx to (b_idx, h_grid_idx, w_grid_idx, win_h, win_w, c)
        int c = idx % C;
        int rem = idx / C;
        int win_w = rem % window_size;
        rem /= window_size;
        int win_h = rem % window_size;
        rem /= window_size;
        int w_grid_idx = rem % num_windows_w;
        rem /= num_windows_w;
        int h_grid_idx = rem % num_windows_h;
        int b_idx = rem / num_windows_h;

        // Calculate input coordinates
        int h_in = h_grid_idx * window_size + win_h;
        int w_in = w_grid_idx * window_size + win_w;

        // Calculate input index (x is B, H, W, C)
        int input_idx = b_idx * (H * W * C) + h_in * (W * C) + w_in * C + c;

        windows_ptr[idx] = x_ptr[input_idx];
    }
}

torch::Tensor window_partition_cuda(torch::Tensor x, int window_size) {
    // x: (B, H, W, C)
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (B, H, W, C)");

    int B = x.size(0);
    int H = x.size(1);
    int W = x.size(2);
    int C = x.size(3);

    TORCH_CHECK(H % window_size == 0 && W % window_size == 0, "H and W must be divisible by window_size");

    int num_windows_h = H / window_size;
    int num_windows_w = W / window_size;

    auto out = torch::empty({B * num_windows_h * num_windows_w, window_size, window_size, C}, x.options());

    const int block_size = 256;
    int total_elements = B * num_windows_h * num_windows_w * window_size * window_size * C;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    window_partition_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), out.data_ptr<float>(),
        B, H, W, C, window_size, num_windows_h, num_windows_w);

    return out;
}
"""

window_partition_cpp_source = (
    "torch::Tensor window_partition_cuda(torch::Tensor x, int window_size);"
)

window_partition_op = load_inline(
    name="window_partition",
    cpp_sources=window_partition_cpp_source,
    cuda_sources=window_partition_source,
    functions=["window_partition_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
