)


# Kernel for window_reverse operation
# This kernel replaces the view, permute, contiguous, and reshape operations for window reversal.
window_reverse_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void window_reverse_kernel(
    const float* windows_ptr, float* x_ptr,
    int B, int H, int W, int C, int window_size,
    int num_windows_h, int num_windows_w) {

    int total_elements = B * H * W * C;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Deconstruct idx to (b_idx, h_in, w_in, c)
        int c = idx % C;
        int rem = idx / C;
        int w_in = rem % W;
        rem /= W;
        int h_in = rem % H;
        int b_idx = rem / H;

        // Calculate window coordinates
        int h_grid_idx = h_in / window_size;
        int w_grid_idx = w_in / window_size;
        int win_h = h_in % window_size;
        int win_w = w_in % window_size;

        // Calculate window index
        int batch_window_idx = b_idx * (num_windows_h * num_windows_w) + h_grid_idx * num_windows_w + w_grid_idx;
        // windows is (num_windows*B, window_size, window_size, C)
        int window_idx = batch_window_idx * (window_size * window_size * C) +
                         win_h * (window_size * C) +
                         win_w * C + c;

        x_ptr[idx] = windows_ptr[window_idx];
    }
}

torch::Tensor window_reverse_cuda(torch::Tensor windows, int window_size, int H, int W) {
    // windows: (num_windows*B, window_size, window_size, C)
    TORCH_CHECK(windows.is_cuda(), "windows must be a CUDA tensor");
    TORCH_CHECK(windows.dim() == 4, "windows must be 4D (num_windows*B, window_size, window_size, C)");

    int num_windows_B = windows.size(0);
    int C = windows.size(3);

    TORCH_CHECK(H % window_size == 0 && W % window_size == 0, "H and W must be divisible by window_size");

    int num_windows_h = H / window_size;
    int num_windows_w = W / window_size;
    int B = num_windows_B / (num_windows_h * num_windows_w);

    auto out = torch::empty({B, H, W, C}, windows.options());

    const int block_size = 256;
    int total_elements = B * H * W * C;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    window_reverse_kernel<<<num_blocks, block_size>>>(
        windows.data_ptr<float>(), out.data_ptr<float>(),
        B, H, W, C, window_size, num_windows_h, num_windows_w);

    return out;
}
"""

window_reverse_cpp_source = (
    "torch::Tensor window_reverse_cuda(torch::Tensor windows, int window_size, int H, int W);"
)

window_reverse_op = load_inline(
    name="window_reverse",
