import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import numpy as np
import collections
from itertools import repeat

# CUDA source for optimized kernels: LayerNorm, GELU, and PatchMerging
swin_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// GELU Kernel
__global__ void gelu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        output[idx] = 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
    }
}

// LayerNorm Kernel (Optimized for inference/forward)
__global__ void layernorm_kernel(const float* __restrict__ input, const float* __restrict__ gamma, const float* __restrict__ beta, float* __restrict__ output, int rows, int cols, float eps) {
    int row = blockIdx.x;
    if (row >= rows) return;

    extern __shared__ float shared_data[];
    float* s_sum = shared_data;
    float* s_sq_sum = &shared_data[blockDim.x];

    float thread_sum = 0.0f;
    float thread_sq_sum = 0.0f;
    for (int col = threadIdx.x; col < cols; col += blockDim.x) {
        float val = input[row * cols + col];
        thread_sum += val;
        thread_sq_sum += val * val;
    }
    s_sum[threadIdx.x] = thread_sum;
    s_sq_sum[threadIdx.x] = thread_sq_sum;
    __syncthreads();

    // Reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sq_sum[threadIdx.x] += s_sq_sum[threadIdx.x + s];
        }
        __syncthreads();
    }

    float mean = s_sum[0] / cols;
    float var = (s_sq_sum[0] / cols) - (mean * mean);
    float inv_std = 1.0f / sqrtf(var + eps);

    for (int col = threadIdx.x; col < cols; col += blockDim.x) {
        output[row * cols + col] = (input[row * cols + col] - mean) * inv_std * gamma[col] + beta[col];
    }
}

// Patch Merging Kernel (Fuses slicing and concatenation)
__global__ void patch_merging_kernel(const float* __restrict__ input, float* __restrict__ output, int B, int H, int W, int C) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = B * (H / 2) * (W / 2) * (4 * C);
    if (idx >= total_elements) return;

    int out_c = idx % (4 * C);
    int out_w = (idx / (4 * C)) % (W / 2);
    int out_h = (idx / (4 * C) / (W / 2)) % (H / 2);
    int b = idx / (4 * C) / (W / 2) / (H / 2);

    int c_orig = out_c % C;
    int quadrant = out_c / C; // 0, 1, 2, 3 mapping to (0,0), (1,0), (0,1), (1,1)

    int in_h = out_h * 2 + (quadrant % 2); // original x0, x1, x2, x3 logic
    int in_w = out_w * 2 + (quadrant / 2); 
    // Adjusting indices to match: x0=0,0; x1=1,0; x2=0,1; x3=1,1
    if (quadrant == 0) { in_h = out_h * 2; in_w = out_w * 2; }
    else if (quadrant == 1) { in_h = out_h * 2 + 1; in_w = out_w * 2; }
    else if (quadrant == 2) { in_h = out_h * 2; in_w = out_w * 2 + 1; }
    else if (quadrant == 3) { in_h = out_h * 2 + 1; in_w = out_w * 2 + 1; }

    int in_idx = ((b * H + in_h) * W + in_w) * C + c_orig;
    output[idx] = input[in_idx];
}

torch::Tensor gelu_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    gelu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}

torch::Tensor layernorm_cuda(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, float eps) {
    int cols = input.size(-1);
    int rows = input.numel() / cols;
    auto output = torch::empty_like(input);
    const int block_size = 256;
    size_t shared_mem_size = 2 * block_size * sizeof(float);
    layernorm_kernel<<<rows, block_size, shared_mem_size>>>(input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(), output.data_ptr<float>(), rows, cols, eps);
    return output;
}

