# Define custom CUDA kernel for fusing Element-wise Addition and Layer Normalization
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename T>
__global__ void fused_add_layernorm_kernel(
    const T* __restrict__ input_a,
    const T* __restrict__ input_b,
    const T* __restrict__ gamma,
    const T* __restrict__ beta,
    T* __restrict__ output,
    int n_rows,
    int n_cols,
    float epsilon) {

    // Shared memory for reduction: need space for sum and sum_sq per thread in block
    extern __shared__ float s_data[];
    float* s_sum = s_data;
    float* s_sum_sq = s_data + blockDim.x;

    int row = blockIdx.x;
    if (row >= n_rows) return;

    // Offset to the start of the current row
    int offset = row * n_cols;

    float local_sum = 0.0f;
    float local_sum_sq = 0.0f;

    // 1. Element-wise Add + Accumulate Statistics (Mean/Var calculation)
    // Loop handles cases where n_cols > blockDim.x
    for (int col = threadIdx.x; col < n_cols; col += blockDim.x) {
        float val = static_cast<float>(input_a[offset + col]) + static_cast<float>(input_b[offset + col]);
        local_sum += val;
        local_sum_sq += val * val;
    }

    s_sum[threadIdx.x] = local_sum;
    s_sum_sq[threadIdx.x] = local_sum_sq;
    __syncthreads();

    // 2. Parallel Reduction within the block
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // 3. Compute Mean and Inverse Standard Deviation
    float mean = s_sum[0] / n_cols;
    float var = (s_sum_sq[0] / n_cols) - (mean * mean);
    if (var < 0.f) var = 0.f; // Numerical stability
    float inv_std = rsqrtf(var + epsilon);

    // 4. Normalize, Apply Affine Transform (Gamma/Beta), and Store
    for (int col = threadIdx.x; col < n_cols; col += blockDim.x) {
        float val = static_cast<float>(input_a[offset + col]) + static_cast<float>(input_b[offset + col]);
        float norm_val = (val - mean) * inv_std;

        float g = (gamma != nullptr) ? static_cast<float>(gamma[col]) : 1.0f;
        float b = (beta != nullptr) ? static_cast<float>(beta[col]) : 0.0f;

        output[offset + col] = static_cast<T>(norm_val * g + b);
    }
}

torch::Tensor fused_add_layernorm_cuda(torch::Tensor a, torch::Tensor b, torch::Tensor gamma, torch::Tensor beta, float epsilon) {
