    float val = current_attn_output_ptr[threadIdx.x] + current_x_input_ptr[threadIdx.x];
    s_data[threadIdx.x] = val; // Store val for sum
    s_data[threadIdx.x + embed_dim] = val * val; // Store val*val for sum of squares

