import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Fused Add + LayerNorm
# This kernel fuses the element-wise addition of the residual connection
# with the subsequent Layer Normalization, reducing memory bandwidth usage.
fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename T>
__global__ void fused_add_layernorm_kernel(
    const T* __restrict__ x,
    const T* __restrict__ residual,
    const T* __restrict__ gamma,
    const T* __restrict__ beta,
    T* __restrict__ out,
    int D,
    float epsilon) {

    // One block per row
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int offset = row * D;

    // Load and Add
    // We compute (x + residual)
    float val = 0.0f;
    if (tid < D) {
        val = static_cast<float>(x[offset + tid]) + static_cast<float>(residual[offset + tid]);
    }

    // Shared memory for reduction
    extern __shared__ float s_data[];

    // --- Mean Calculation ---
    // Initialize shared memory. If tid >= D, pad with 0 for reduction.
    s_data[tid] = (tid < D) ? val : 0.0f;
    __syncthreads();

    // Tree reduction
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }
    float mean = s_data[0] / D;
    __syncthreads();

    // --- Variance Calculation ---
    float diff = 0.0f;
    if (tid < D) {
        diff = val - mean;
        diff = diff * diff;
    }
    s_data[tid] = (tid < D) ? diff : 0.0f;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }
    float var = s_data[0] / D;
    float inv_std = rsqrtf(var + epsilon);

    // --- Normalize and Scale ---
    if (tid < D) {
        float n_val = (val - mean) * inv_std;
        out[offset + tid] = static_cast<T>(n_val * static_cast<float>(gamma[tid]) + static_cast<float>(beta[tid]));
    }
}

torch::Tensor fused_add_layernorm_cuda(
    torch::Tensor x, 
    torch::Tensor residual, 
    torch::Tensor gamma, 
    torch::Tensor beta, 
    float epsilon) {

    auto D = x.size(-1);
    auto N = x.numel() / D;

    // Ensure inputs are contiguous
    x = x.contiguous();
    residual = residual.contiguous();

    auto out = torch::empty_like(x);

    // Determine block size (Next power of 2)
    int threads = 1;
    while (threads < D) threads *= 2;
    // Cap at 1024 threads per block
    if (threads > 1024) threads = 1024; 

    // Check if D is supported by this simple kernel
    TORCH_CHECK(D <= 1024, "fused_add_layernorm_cuda only supports embedding dim <= 1024");

    int shared_mem = threads * sizeof(float);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(x.scalar_type(), "fused_add_layernorm_cuda", ([&] {
        fused_add_layernorm_kernel<scalar_t><<<N, threads, shared_mem>>>(
            x.data_ptr<scalar_t>(),
            residual.data_ptr<scalar_t>(),
            gamma.data_ptr<scalar_t>(),
            beta.data_ptr<scalar_t>(),
            out.data_ptr<scalar_t>(),
            D,
            epsilon
        );
    }));

    return out;
}
"""

fused_ops_cpp = "torch::Tensor fused_add_layernorm_cuda(torch::Tensor x, torch::Tensor residual, torch::Tensor gamma, torch::Tensor beta, float epsilon);"

