#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void rnn_recurrence_kernel(
    const float* __restrict__ X_proj,
    const float* __restrict__ h0,
    const float* __restrict__ W_hh_T,
    float* __restrict__ H_out,
    int L, int B, int H) 
{
    // Each block processes one sequence in the batch
    int b = blockIdx.x;
    int tid = threadIdx.x;
    if (b >= B || tid >= H) return;

    // Use shared memory to store the previous hidden state
    extern __shared__ float s_hprev[];

    // Initialize the shared hidden state from h0
    s_hprev[tid] = h0[b * H + tid];
    __syncthreads();

    for (int t = 0; t < L; t++) {
        float sum = 0.0f;
        // Compute (h_prev @ W_hh^T). By passing W_hh transposed, 
        // we ensure coalesced memory access where each thread reads adjacent elements.
        for (int j = 0; j < H; j++) {
            sum += W_hh_T[j * H + tid] * s_hprev[j];
