        // Store the result in the global output tensor
        H_out[(t * B + b) * H + tid] = h_curr;

        // Synchronize threads to update the shared hidden state for the next step
        __syncthreads(); 
        s_hprev[tid] = h_curr;
        __syncthreads();
    }
}

