    // A block size of 32x8 (256 threads) is a common choice for NVIDIA GPUs.
    const int block_size_x = 32; // Threads per block along the hidden_size dimension
    const int block_size_y = 8;  // Threads per block along the batch_size dimension
    dim3 block_dim(block_size_x, block_size_y);

    // Calculate the number of blocks needed to cover the entire output tensor.
    dim3 grid_dim(
        (hidden_size + block_size_x - 1) / block_size_x, // Blocks for hidden_size
        (batch_size + block_size_y - 1) / block_size_y    // Blocks for batch_size
    );

