#include <cuda_runtime.h>
#include <math.h>
#include <vector>

__device__ __forceinline__ float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void lstm_gates_kernel(
    const float* __restrict__ g_x,
    const float* __restrict__ g_h,
    const float* __restrict__ c_old,
    float* __restrict__ h_new,
    float* __restrict__ c_new,
    int batch_size,
    int hidden_size
) {
    int b = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;

    if (b < batch_size && h < hidden_size) {
        int h_idx = b * hidden_size + h;
        int g_idx = b * (4 * hidden_size) + h;

        // Gate layout in PyTorch: input, forget, cell, output
        float ix = g_x[g_idx];
        float fx = g_x[g_idx + hidden_size];
        float gx = g_x[g_idx + 2 * hidden_size];
        float ox = g_x[g_idx + 3 * hidden_size];

        float ih = g_h[g_idx];
        float fh = g_h[g_idx + hidden_size];
        float gh = g_h[g_idx + 2 * hidden_size];
        float oh = g_h[g_idx + 3 * hidden_size];

        float i = sigmoid(ix + ih);
        float f = sigmoid(fx + fh);
        float g = tanhf(gx + gh);
        float o = sigmoid(ox + oh);

        float c_prev_val = c_old[h_idx];
        float c_next_val = f * c_prev_val + i * g;
        float h_next_val = o * tanhf(c_next_val);

        c_new[h_idx] = c_next_val;
        h_new[h_idx] = h_next_val;
    }
}

