    // Grid dimensions: x = output_size, y = batch_size
    // Block dimensions: x = 256 (fixed block size for reduction)

    int o_idx = blockIdx.x; // Output feature index
    int b_idx = blockIdx.y; // Batch index
    int tid = threadIdx.x;  // Thread index within block

    // Calculate offsets
    // Input is (Batch, Seq, Hidden). We want input[b, -1, :]
    // The flat index start for the last sequence element of batch b is:
    int input_offset = b_idx * seq_len * hidden_size + (seq_len - 1) * hidden_size;

