#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void lstm_pointwise_kernel(
    const float* __restrict__ gates,    // [batch_size, 4 * hidden_size]
    const float* __restrict__ c_prev,   // [batch_size, hidden_size]
    float* __restrict__ h_out,          // [batch_size, hidden_size]
    float* __restrict__ c_out,          // [batch_size, hidden_size]
    int batch_size,
    int hidden_size) {

    int b = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;

    if (b < batch_size && h < hidden_size) {
        int gate_offset = b * 4 * hidden_size + h;
        int h_offset = b * hidden_size + h;

        // PyTorch layout: i, f, g, o
        float i_raw = gates[gate_offset];
        float f_raw = gates[gate_offset + 1 * hidden_size];
        float g_raw = gates[gate_offset + 2 * hidden_size];
        float o_raw = gates[gate_offset + 3 * hidden_size];

        float i_gate = 1.0f / (1.0f + expf(-i_raw));
        float f_gate = 1.0f / (1.0f + expf(-f_raw));
        float g_gate = tanhf(g_raw);
        float o_gate = 1.0f / (1.0f + expf(-o_raw));

        float c_prev_val = c_prev[h_offset];
        float c_curr = f_gate * c_prev_val + i_gate * g_gate;
        float h_curr = o_gate * tanhf(c_curr);

        c_out[h_offset] = c_curr;
        h_out[h_offset] = h_curr;
    }
}

