        // We need the element at index [b, seq_length - 1, h].
        // Stride for batch: seq_length * hidden_size
        // Stride for sequence: hidden_size
        // Using long for pointer arithmetic to prevent potential overflow with very large tensor dimensions.
        const float* current_batch_last_h_ptr = lstm_output_ptr + (long)b * seq_length * hidden_size + (long)(seq_length - 1) * hidden_size;

