    // Use 256 threads per block and one block per output element.
    int threads = 256;
    int blocks = B * O;

    fused_slice_linear_kernel<<<blocks, threads>>>(
        lstm_out.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, S, K, O
    );

    return output;
}
"""

