#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

__device__ inline float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__device__ inline float tanh_f(float x) {
    return tanhf(x);
}

__global__ void gru_cell_fused_kernel(
    const float* __restrict__ x_gates, // [batch, 3*hidden] (Precomputed input projections)
    const float* __restrict__ h_gates, // [batch, 3*hidden] (Computed recurrent projections)
    const float* __restrict__ h_prev,  // [batch, hidden]
    float* __restrict__ h_next,        // [batch, hidden]
    int hidden_size,
    int batch_size) 
{
    int b = blockIdx.x; 
    // Each block handles one batch element
    // Loop ensures we cover all hidden units if hidden_size > blockDim.x
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        if (b >= batch_size) return;

        // Offsets
        int gate_idx_base = b * 3 * hidden_size + i;
        int h_idx = b * hidden_size + i;

        // Load pre-computed gates
        // x_gates contains: W_ix @ x + b_ix
        // h_gates contains: W_hx @ h_prev + b_hx

        // Chunk 0: Reset gate (r)
        float xr = x_gates[gate_idx_base];
        float hr = h_gates[gate_idx_base];

        // Chunk 1: Update gate (z)
        float xz = x_gates[gate_idx_base + hidden_size];
        float hz = h_gates[gate_idx_base + hidden_size];

        // Chunk 2: New gate (n)
        float xn = x_gates[gate_idx_base + 2 * hidden_size];
        float hn = h_gates[gate_idx_base + 2 * hidden_size];

        float hp = h_prev[h_idx];

        // Apply activations
        // r = sigmoid(xr + hr)
        float r = sigmoid(xr + hr);

        // z = sigmoid(xz + hz)
        float z = sigmoid(xz + hz);

        // n = tanh(xn + r * hn)
        // Note: r scales the recurrent part of the n computation
        float n = tanh_f(xn + r * hn);

        // h_new = (1 - z) * n + z * h_prev
        float h_new = (1.0f - z) * n + z * hp;

        h_next[h_idx] = h_new;
    }
}

