    int total_threads = batch_size * hidden_size;
    int threads_per_block = 256;
    int num_blocks = (total_threads + threads_per_block - 1) / threads_per_block;

    gru_cell_fused_kernel<<<num_blocks, threads_per_block>>>(
        gates_x.data_ptr<float>(),
        gates_h.data_ptr<float>(),
        h_prev.data_ptr<float>(),
        h_next.data_ptr<float>(),
        batch_size,
        hidden_size
    );

    return h_next;
}
"""

