#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gru_layer_kernel(
    const float* __restrict__ ih_proj, // [T, B, 3, H]
    const float* __restrict__ whh,     // [3*H, H]
    const float* __restrict__ bhh,     // [3*H]
    const float* __restrict__ h_init,  // [B, H]
    float* __restrict__ h_out,         // [T, B, H]
    int T, int B, int H, bool reverse) {

    extern __shared__ float s_h_prev[]; // size [H] per block

    int tid = threadIdx.x; // 0 to H-1
    int b = blockIdx.y;    // 0 to B-1 (each block handles one batch element)

    // Load initial hidden state for this batch element into shared memory
    if (tid < H) {
        s_h_prev[tid] = h_init[b * H + tid];
    }
    __syncthreads();

    for (int t = 0; t < T; ++t) {
        int time_idx = reverse ? (T - 1 - t) : t;

        // Base index for input projections: ih_proj is [T, B, 3, H]
        int base_idx = ((time_idx * B + b) * 3) * H + tid;
        float ih_r = ih_proj[base_idx + 0 * H];
        float ih_z = ih_proj[base_idx + 1 * H];
        float ih_n = ih_proj[base_idx + 2 * H];

        // Hidden bias components
        float bh_r = bhh[0 * H + tid];
        float bh_z = bhh[1 * H + tid];
        float bh_n = bhh[2 * H + tid];

        // Compute recurrent hidden projections (Matrix-Vector multiply: W_hh * h_prev)
        float hh_r = 0.0f, hh_z = 0.0f, hh_n = 0.0f;
        for (int i = 0; i < H; ++i) {
            float h_val = s_h_prev[i];
            hh_r += whh[(0 * H + tid) * H + i] * h_val;
            hh_z += whh[(1 * H + tid) * H + i] * h_val;
            hh_n += whh[(2 * H + tid) * H + i] * h_val;
        }

        // GRU gate updates
        float r = 1.0f / (1.0f + expf(-(ih_r + hh_r + bh_r)));
        float z = 1.0f / (1.0f + expf(-(ih_z + hh_z + bh_z)));
        float n = tanhf(ih_n + r * (hh_n + bh_n));

        float h_next = (1.0f - z) * n + z * s_h_prev[tid];

