import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for GRU element-wise fusion
# This kernel fuses the sigmoid, tanh, and element-wise arithmetic operations
# within a single GRU cell computation for one time step.
gru_elementwise_fusion_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf, tanhf

// Custom sigmoid function for device
__device__ float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

// Custom tanh function for device (using CUDA's built-in tanhf for efficiency)
__device__ float tanh_custom(float x) {
    return tanhf(x);
}

__global__ void gru_elementwise_fusion_kernel(
    const float* gates_ih_ptr, // Input-hidden gate contributions (batch_size, 3 * hidden_size)
    const float* gates_hh_ptr, // Hidden-hidden gate contributions (batch_size, 3 * hidden_size)
    const float* h_prev_ptr,   // Previous hidden state (batch_size, hidden_size)
    float* h_curr_ptr,         // Output current hidden state (batch_size, hidden_size)
    int batch_size,
    int hidden_size
) {
    // Each thread computes one element of the current hidden state h_curr.
    // The total number of elements to compute is batch_size * hidden_size.
    int idx = blockIdx.x * blockDim.x + threadIdx.x; 
    int total_elements = batch_size * hidden_size;

    if (idx < total_elements) {
        int b = idx / hidden_size; // Batch index
        int h = idx % hidden_size; // Hidden dimension index within the batch

        // The 'gates_ih_ptr' and 'gates_hh_ptr' tensors are structured as:
        // [reset_gate_contrib | update_gate_contrib | new_hidden_candidate_contrib]
        // Each part has 'hidden_size' elements.

        // 1. Calculate Reset Gate (r_t)
        // r_t = sigmoid(W_ir * x_t + b_ir + W_hr * h_{t-1} + b_hr)
        // The terms (W_ir * x_t + b_ir) and (W_hr * h_{t-1} + b_hr) are already combined into gates_ih_ptr and gates_hh_ptr.
        // The first 'hidden_size' elements (0 to hidden_size-1) correspond to the reset gate.
        float r_ih = gates_ih_ptr[b * (3 * hidden_size) + h];
        float r_hh = gates_hh_ptr[b * (3 * hidden_size) + h];
        float r_t = sigmoid(r_ih + r_hh);

        // 2. Calculate Update Gate (z_t)
        // z_t = sigmoid(W_iz * x_t + b_iz + W_hz * h_{t-1} + b_hz)
        // The next 'hidden_size' elements (hidden_size to 2*hidden_size-1) correspond to the update gate.
        float z_ih = gates_ih_ptr[b * (3 * hidden_size) + hidden_size + h];
        float z_hh = gates_hh_ptr[b * (3 * hidden_size) + hidden_size + h];
        float z_t = sigmoid(z_ih + z_hh);

        // 3. Calculate New Hidden Candidate (n_t)
        // n_t = tanh(W_in * x_t + b_in + r_t * (W_hn * h_{t-1} + b_hn))
        // The last 'hidden_size' elements (2*hidden_size to 3*hidden_size-1) correspond to the new hidden candidate gate.
        float n_ih = gates_ih_ptr[b * (3 * hidden_size) + 2 * hidden_size + h];
        float n_hh = gates_hh_ptr[b * (3 * hidden_size) + 2 * hidden_size + h];
        float n_t = tanh_custom(n_ih + r_t * n_hh); // Note: r_t is applied element-wise to n_hh

        // 4. Calculate Current Hidden State (h_t)
        // h_t = (1 - z_t) * n_t + z_t * h_{t-1}
        float h_prev_val = h_prev_ptr[b * hidden_size + h];
        float h_t = (1.0f - z_t) * n_t + z_t * h_prev_val;

