        h_curr_ptr[b * hidden_size + h] = h_t;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor gru_elementwise_fusion_cuda(
    torch::Tensor gates_ih,
    torch::Tensor gates_hh,
    torch::Tensor h_prev
