import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math

# Custom CUDA kernel for fused causal attention:
# Includes split/transpose, scaled dot-product, causal masking, online softmax, and weighted sum.
# This avoids storing the large (B, nh, T, T) attention matrix in global memory.
fused_attn_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_attention_kernel(
    const float* __restrict__ qkv,
    float* __restrict__ out,
    int B, int T, int nh, int hs, float scale) {

    // Each block handles one row (batch, head, query_idx) of the output.
    // Dimensions: blockIdx.x = query index (t), y = head index (h), z = batch index (b).
    int t = blockIdx.x;
    int h = blockIdx.y;
    int b = blockIdx.z;
    int tid = threadIdx.x;

    extern __shared__ float s_mem[];
    float* s_q = s_mem; // Size: hs
    __shared__ float s_score;
    __shared__ float warp_sums[32]; // Enough for any reasonable block size

    // 1. Load the specific Q row for this block into shared memory.
    // qkv indexing (B, T, 3, nh, hs): q is at index 0 in the "3" dimension.
    int q_idx_base = (((b * T + t) * 3 + 0) * nh + h) * hs;
    for (int i = tid; i < hs; i += blockDim.x) {
        s_q[i] = qkv[q_idx_base + i];
    }
    __syncthreads();

    // 2. Compute Causal Attention using Online Softmax.
    float m = -1e20f; // Max score
    float d = 0.0f;   // Sum of exponentials
    float acc = 0.0f; // This thread's component of the output value vector

    for (int j = 0; j <= t; ++j) {
        // Dot product Q[t] * K[j]
        float local_score = 0.0f;
        int k_idx_base = (((b * T + j) * 3 + 1) * nh + h) * hs;
        for (int i = tid; i < hs; i += blockDim.x) {
            local_score += s_q[i] * qkv[k_idx_base + i];
        }

        // Warp-level reduction for the dot product
        for (int offset = 16; offset > 0; offset /= 2)
            local_score += __shfl_down_sync(0xffffffff, local_score, offset);

        if (tid % 32 == 0) warp_sums[tid / 32] = local_score;
        __syncthreads();

        // Block-level reduction
        if (tid == 0) {
            float total_score = 0;
            int num_warps = (blockDim.x + 31) / 32;
            for (int i = 0; i < num_warps; i++) total_score += warp_sums[i];
            s_score = total_score * scale;
        }
        __syncthreads();

        // Online Softmax update
        float score = s_score;
        float m_prev = m;
        m = fmaxf(m_prev, score);
        float exp_val = expf(score - m);
        float exp_m_diff = expf(m_prev - m);
        d = d * exp_m_diff + exp_val;

        // Weighted accumulation of Value vector: v is at index 2 in the "3" dimension.
        int v_idx_base = (((b * T + j) * 3 + 2) * nh + h) * hs;
        if (tid < hs) {
            acc = acc * exp_m_diff + qkv[v_idx_base + tid] * exp_val;
        }
        __syncthreads(); // Sync before reusing shared score memory
    }

    // 3. Store the final normalized result to output.
    if (tid < hs) {
        // Output indexing (B, T, nh, hs)
        int out_idx = (((b * T + t) * nh + h) * hs) + tid;
        out[out_idx] = acc / d;
    }
}

torch::Tensor fused_attention_cuda(torch::Tensor qkv, int nh, int hs, float scale) {
    int B = qkv.size(0);
    int T = qkv.size(1);

    auto out = torch::empty({B, T, nh, hs}, qkv.options());

    // Use a fixed block size that covers the embedding head dimension (hs).
    // Standard hs is 64, 96, or 128.
    const int threads = 128; 
    const dim3 blocks(T, nh, B); 
    size_t shared_mem_size = hs * sizeof(float);

    fused_attention_kernel<<<blocks, threads, shared_mem_size>>>(
        qkv.data_ptr<float>(),
        out.data_ptr<float>(),
        B, T, nh, hs, scale
    );

    return out;
}
"""

fused_attn_cpp_source = (
    "torch::Tensor fused_attention_cuda(torch::Tensor qkv, int nh, int hs, float scale);"
)

# Compile the inline CUDA code
fused_attn_module = load_inline(
    name="fused_attn",
    cpp_sources=fused_attn_cpp_source,
    cuda_sources=fused_attn_source,
    functions=["fused_attention_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.n_head = n_head
        self.n_embd = n_embd
        self.fused_attn = fused_attn_module

    def forward(self, x):
        B, T, C = x.size()
        hs = C // self.n_head

        # 1. Project to QKV
        # Result: (B, T, 3 * C)
        qkv = self.c_attn(x)

        # 2. Reshape for the fused kernel
        # Shape becomes (B, T, 3, nh, hs) where hs is head size
        qkv = qkv.view(B, T, 3, self.n_head, hs).contiguous()

