torch::Tensor fused_causal_softmax_cuda(torch::Tensor input, float scale) {
    // Input is (Batch, Heads, T, T)
    // Flattened view for kernel: (Batch*Heads*T, T)

    int B = input.size(0);
    int NH = input.size(1);
    int T = input.size(2);

    // Ensure contiguous memory
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    int total_rows = B * NH * T;

    // Determine block size (Next power of 2 covering T)
    int block_size = 32;
    while (block_size < T && block_size < 1024) block_size *= 2;
    // Cap at 1024 (typical max threads per block). 
    // Note: If T > 1024, this simple 1-block-per-row kernel requires modification (looping).
    // Assuming T <= 1024 based on problem constraints.
    if (T > 1024) block_size = 1024; 

    fused_causal_softmax_kernel<<<total_rows, block_size>>>(
        input.data_ptr<float>(), 
        B * NH, 
        T, 
        scale
    );

    return input;
}
"""

fused_softmax_cpp_source = "torch::Tensor fused_causal_softmax_cuda(torch::Tensor input, float scale);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_softmax_cpp_source,
    cuda_sources=fused_softmax_source,
    functions=["fused_causal_softmax_cuda"],
    verbose=False,
    extra_cuda_cflags=["-O3"]
)

class ModelNew(nn.Module):
    """
    Optimized Multi-head self-attention layer using custom CUDA kernel for 
    fused Scale + Causal Mask + Softmax.
    """

    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.n_head = n_head
        self.n_embd = n_embd
        # Custom fused operator module
        self.fused_ops = fused_ops

    def forward(self, x):
        B, T, C = x.size()

        # q, k, v generation
        # (B, T, 3C) -> (B, T, 3, nh, hs) -> (3, B, nh, T, hs) effectively
        # We keep the PyTorch split/view/transpose logic as it involves complex striding 
        # and CuBLAS is efficient enough for the initial projection.
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)

        # Reshape for multi-head attention
        # (B, nh, T, hs)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        # MatMul: (B, nh, T, hs) x (B, nh, hs, T) -> (B, nh, T, T)
        # Using native torch.matmul (calls CuBLAS)
        att = torch.matmul(q, k.transpose(-2, -1))

        # Optimization: Replace Scale + Mask + Softmax with custom CUDA kernel
        # We calculate the scale factor
        scale = 1.0 / math.sqrt(k.size(-1))

        # Call custom kernel (in-place modification of att)
        # This replaces:
        #   att = att * scale
        #   att = att.masked_fill(bias == 0, -inf)
        #   att = F.softmax(att, dim=-1)
        self.fused_ops.fused_causal_softmax_cuda(att, scale)

        # Dropout
        att = self.attn_dropout(att)

        # MatMul: (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
        y = torch.matmul(att, v)

        # Re-assemble
        y = y.transpose(1, 2).contiguous().view(B, T, C)

        # Output projection
        y = self.resid_dropout(self.c_proj(y))
        return y

