#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX
#include <cub/cub.cuh> // For block-level reductions

// Define a small negative number for masked_fill
#define NEG_INF -FLT_MAX

__global__ void fused_scaled_masked_softmax_kernel(
    const float* attn_scores_ptr,
    const float* bias_mask_ptr,
    float* output_ptr,
    int B, int nh, int T, // T is sequence length, also the last dim size for softmax
