    // Each thread contributes its portion of the shared memory row to the reduction.
    typedef cub::BlockReduce<float, 256> BlockReduce; // Assuming block_size = 256
    __shared__ typename BlockReduce::TempStorage temp_storage; // Shared memory for CUB's internal use

    float thread_max_val = NEG_INF;
