torch::Tensor new_gelu_cuda(torch::Tensor x) {
    auto y = torch::empty_like(x);
    int n = x.numel();
    const int threads = 256;
    const int blocks = (n + threads - 1) / threads;
    new_gelu_kernel<<<blocks, threads>>>(x.data_ptr<float>(), y.data_ptr<float>(), n);
    return y;
}

__global__ void layernorm_kernel(const float* __restrict__ x, 
                                 const float* __restrict__ gamma, 
                                 const float* __restrict__ beta, 
                                 float* __restrict__ y, 
                                 int rows, int cols, float eps) {
    int row = blockIdx.x;
    int tid = threadIdx.x;

    // Shared memory for reduction within a row
    extern __shared__ float shared_data[]; 
    float* s_mean = shared_data;
    float* s_var = &shared_data[blockDim.x];

    float sum = 0.0f;
    float sq_sum = 0.0f;
    for (int col = tid; col < cols; col += blockDim.x) {
        float val = x[row * cols + col];
        sum += val;
        sq_sum += val * val;
