    s_mean[tid] = sum;
    s_var[tid] = sq_sum;
    __syncthreads();

    // Parallel reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_mean[tid] += s_mean[tid + s];
            s_var[tid] += s_var[tid + s];
        }
        __syncthreads();
