softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

__global__ void softmax_kernel(
    const float* input,
    float* output,
    int N, int C, int H, int W) {

    // Each block handles one (n, c, h) slice
    int n_c_h_idx = blockIdx.x;
    int n = n_c_h_idx / (C * H);
    int c = (n_c_h_idx % (C * H)) / H;
    int h = n_c_h_idx % H;

    // Shared memory for intermediate values and reduction
    extern __shared__ float s_data[]; // s_data[blockDim.x] for input_vals/exp_vals

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // Load input values into shared memory
    float input_val = 0.0f;
    if (tid < W) {
        int input_idx = n * C * H * W + c * H * W + h * W + tid;
        input_val = input[input_idx];
    }
    s_data[tid] = input_val;
    __syncthreads();

    // Softmax calculation
    // 1. Find max value in the slice for numerical stability
    float thread_max_val = -FLT_MAX;
    if (tid < W) {
        thread_max_val = s_data[tid];
    }
    // Reduce max_val across the block using shared memory
    s_data[tid] = thread_max_val; // Store thread's max candidate
    __syncthreads();
    for (int s = block_size / 2; s > 0; s /= 2) {
        if (tid < s) {
