import math
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch as th
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for NetVLAD fused operations
vlad_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void vlad_intra_norm_kernel(
    const float* __restrict__ vlad_raw,  // (B, K, D)
    const float* __restrict__ a_sum,     // (B, K)
    const float* __restrict__ clusters2, // (D, K)
    float* __restrict__ output,          // (B, D, K)
    int B, int K, int D) {

    int bk = blockIdx.x;
    if (bk >= B * K) return;
    int b = bk / K;
    int k = bk % K;

    float ss = 0.0f;
    // Step 1: Compute residual and sum of squares
    // Note: This step also effectively performs a transpose: (B, K, D) -> (B, D, K)
    for (int d = threadIdx.x; d < D; d += blockDim.x) {
        float res = vlad_raw[b * K * D + k * D + d] - a_sum[b * K + k] * clusters2[d * K + k];
        output[b * D * K + d * K + k] = res;
        ss += res * res;
    }

    // Step 2: Parallel reduction for sum of squares within the block (for intra-norm)
    for (int offset = 16; offset > 0; offset /= 2)
        ss += __shfl_down_sync(0xffffffff, ss, offset);

    __shared__ float warp_sums[8]; // For block_size=256 (8 warps)
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;
    if (lane == 0) warp_sums[wid] = ss;
    __syncthreads();

    __shared__ float shared_std;
    if (threadIdx.x < 32) {
        float s = (threadIdx.x < 8) ? warp_sums[threadIdx.x] : 0.0f;
        for (int offset = 4; offset > 0; offset /= 2) 
            s += __shfl_down_sync(0xffffffff, s, offset);
        if (threadIdx.x == 0) {
            shared_std = sqrtf(fmaxf(s, 1e-12f));
        }
    }
    __syncthreads();

    // Step 3: Intra-normalization
    float inv_std = 1.0f / shared_std;
    for (int d = threadIdx.x; d < D; d += blockDim.x) {
        output[b * D * K + d * K + k] *= inv_std;
    }
}

torch::Tensor vlad_intra_cuda(torch::Tensor vlad_raw, torch::Tensor a_sum, torch::Tensor clusters2) {
    auto B = vlad_raw.size(0);
    auto K = vlad_raw.size(1);
    auto D = vlad_raw.size(2);
    auto output = torch::empty({B, D, K}, vlad_raw.options());

    const int block_size = 256;
    const int num_blocks = B * K;

    vlad_intra_norm_kernel<<<num_blocks, block_size>>>(
        vlad_raw.data_ptr<float>(),
        a_sum.data_ptr<float>(),
        clusters2.data_ptr<float>(),
        output.data_ptr<float>(),
        B, K, D);

    return output;
}
"""

vlad_cpp_source = (
    "torch::Tensor vlad_intra_cuda(torch::Tensor vlad_raw, torch::Tensor a_sum, torch::Tensor clusters2);"
)

# Compile the inline CUDA code
vlad_norm_lib = load_inline(
    name="vlad_norm_lib",
    cpp_sources=vlad_cpp_source,
    cuda_sources=vlad_cuda_source,
    functions=["vlad_intra_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, cluster_size, feature_size, ghost_clusters):
        super(ModelNew, self).__init__()

        self.feature_size = feature_size
        self.cluster_size = cluster_size
        self.ghost_clusters = ghost_clusters

        init_sc = (1 / math.sqrt(feature_size))
        clusters = cluster_size + ghost_clusters

        # Parameters
        self.clusters = nn.Parameter(init_sc * th.randn(feature_size, clusters))
        self.batch_norm = nn.BatchNorm1d(clusters)
        self.clusters2 = nn.Parameter(init_sc * th.randn(1, feature_size, cluster_size))
        self.out_dim = self.cluster_size * feature_size

        # Reference compiled library
        self.vlad_norm_lib = vlad_norm_lib

    def forward(self, x, mask=None):
        B, N, D = x.shape
        x_flat = x.view(-1, D)

        if x.device != self.clusters.device:
            msg = f"x.device {x.device} != cluster.device {self.clusters.device}"
            raise ValueError(msg)

        # 1. Assignment and soft assignment calculation
        assignment = th.matmul(x_flat, self.clusters)
        assignment = self.batch_norm(assignment)
        assignment = F.softmax(assignment, dim=1)

        # 2. Slice ghost clusters and aggregate
        assignment_sliced = assignment[:, :self.cluster_size]
        assignment_reshaped = assignment_sliced.view(B, N, self.cluster_size)

        # a_sum: B x K
        a_sum = th.sum(assignment_reshaped, dim=1)

        # 3. Compute raw VLAD aggregation: (B x K x N) x (B x N x D) -> (B x K x D)
        vlad_raw = th.matmul(assignment_reshaped.transpose(1, 2), x)

        # 4. Custom CUDA Kernel: Fused subtraction and intra-normalization
        # Input clusters2: (1, D, K) viewed as (D, K)
        # Kernel produces: (B, D, K) where each cluster vector is normalized
        vlad_intra = self.vlad_norm_lib.vlad_intra_cuda(
            vlad_raw, a_sum, self.clusters2.view(D, self.cluster_size)
        )

        # 5. Global Normalization
        vlad_flat = vlad_intra.reshape(B, -1)
        vlad_final = F.normalize(vlad_flat, p=2, dim=1)

        return vlad_final

