import torch
import torch.nn as nn
import torch.nn.functional as F
import torch as th
from torch.utils.cpp_extension import load_inline
import math

# --- Custom CUDA Kernel 1: Fuses BatchNorm, Softmax, and Slicing ---
# This kernel takes the raw output of the initial matrix multiplication,
# applies batch normalization, performs a numerically stable softmax row-wise,
# and then slices the result to remove ghost clusters.
batch_norm_softmax_slice_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf, sqrtf
#include <float.h> // For FLT_MAX

__global__ void batch_norm_softmax_slice_kernel(
    const float* assignment_raw,
    const float* bn_weight,
    const float* bn_bias,
    const float* bn_mean,
    const float* bn_var,
    float bn_eps,
    int BN, // total_samples (batch_size * num_features)
    int K_plus_G, // total_clusters (cluster_size + ghost_clusters)
    int K, // cluster_size
    float* output) {

    // Each block processes one row (one sample from BN)
    int row_idx = blockIdx.x;

    if (row_idx >= BN) return;

    // Shared memory for one row's values after BN, and for softmax calculation.
    // s_vals[0...K_plus_G-1] for bn_vals/exp_vals
    // s_vals[K_plus_G] for max_val (computed by thread 0)
    // s_vals[K_plus_G+1] for sum_exp (computed by thread 0)
    extern __shared__ float s_vals[];

    // 1. Apply Batch Norm and store in shared memory
    for (int col_idx = threadIdx.x; col_idx < K_plus_G; col_idx += blockDim.x) {
        float val = assignment_raw[row_idx * K_plus_G + col_idx];
        s_vals[col_idx] = (val - bn_mean[col_idx]) / sqrtf(bn_var[col_idx] + bn_eps) * bn_weight[col_idx] + bn_bias[col_idx];
    }
    __syncthreads();

    // 2. Find max_val for numerically stable softmax.
    // For small K_plus_G (e.g., 48), a single thread (threadIdx.x == 0) can efficiently
    // compute the max over all elements in shared memory.
    if (threadIdx.x == 0) {
        float max_val = s_vals[0];
        for (int col_idx = 1; col_idx < K_plus_G; ++col_idx) {
            if (s_vals[col_idx] > max_val) {
                max_val = s_vals[col_idx];
            }
        }
        s_vals[K_plus_G] = max_val; // Store max_val in shared memory for all threads to read
    }
    __syncthreads();
    float max_val = s_vals[K_plus_G]; // All threads read the computed max_val

    // 3. Compute exp(val - max_val) and sum_exp
    for (int col_idx = threadIdx.x; col_idx < K_plus_G; col_idx += blockDim.x) {
        s_vals[col_idx] = expf(s_vals[col_idx] - max_val); // s_vals now holds exp(bn_val - max_val)
    }
    __syncthreads();

    // Reduce sum_exp across the block.
    // Similar to max_val, thread 0 sums up all exp values from shared memory.
    if (threadIdx.x == 0) {
        float total_sum_exp = 0.0f;
        for (int col_idx = 0; col_idx < K_plus_G; ++col_idx) {
            total_sum_exp += s_vals[col_idx];
        }
        s_vals[K_plus_G + 1] = total_sum_exp; // Store total_sum_exp in shared memory
    }
    __syncthreads();
    float sum_exp = s_vals[K_plus_G + 1]; // All threads read the computed sum_exp

    // 4. Divide by sum_exp and store the first K elements (slicing)
    for (int col_idx = threadIdx.x; col_idx < K; col_idx += blockDim.x) { // Only iterate up to K
        output[row_idx * K + col_idx] = s_vals[col_idx] / sum_exp;
    }
}
"""

batch_norm_softmax_slice_cpp_source = (
    "torch::Tensor batch_norm_softmax_slice_cuda("
    "torch::Tensor assignment_raw, "
    "torch::Tensor bn_weight, "
