# Custom CUDA kernel for VLAD finalize (subtraction, intra-normalization, and global-normalization)
vlad_finalize_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void vlad_finalize_kernel(
    const float* __restrict__ vlad_raw,   // Input: (B, K, D)
    const float* __restrict__ a_sum,      // Input: (B, K)
    const float* __restrict__ clusters2,  // Input: (D, K)
    float* __restrict__ out,              // Output: (B, D*K)
    int B, int K, int D)
{
    int b = blockIdx.x;
    int tid = threadIdx.x;

    // Shared memory for warp reductions
    __shared__ float s_reduction[32]; 

    float total_global_sq_sum_local = 0.0f;

    for (int k = 0; k < K; ++k) {
        float intra_sq_sum = 0.0f;
        // Step 1: Subtraction and intra-squared-sum accumulation
        for (int d = tid; d < D; d += blockDim.x) {
            // vlad_raw: b*K*D + k*D + d
            // clusters2: d*K + k
            float val = vlad_raw[b * K * D + k * D + d] - a_sum[b * K + k] * clusters2[d * K + k];
            // Store in output in (B, D, K) layout: b*D*K + d*K + k
            out[b * D * K + d * K + k] = val;
            intra_sq_sum += val * val;
        }

        // Intra-cluster reduction within warp
        for (int offset = 16; offset > 0; offset /= 2)
            intra_sq_sum += __shfl_down_sync(0xffffffff, intra_sq_sum, offset);

        if (tid % 32 == 0) s_reduction[tid / 32] = intra_sq_sum;
        __syncthreads();

        if (tid == 0) {
            float total = 0;
            for (int i = 0; i < (blockDim.x + 31) / 32; ++i) total += s_reduction[i];
            s_reduction[0] = rsqrtf(total + 1e-12f);
        }
        __syncthreads();

        // Step 2: Intra-normalization and global-squared-sum accumulation
        float inv_norm = s_reduction[0];
        for (int d = tid; d < D; d += blockDim.x) {
            float val = out[b * D * K + d * K + k] * inv_norm;
            out[b * D * K + d * K + k] = val;
            total_global_sq_sum_local += val * val;
        }
        __syncthreads();
    }

    // Step 3: Global reduction across the entire batch element
    float global_sq_sum = total_global_sq_sum_local;
    for (int offset = 16; offset > 0; offset /= 2)
        global_sq_sum += __shfl_down_sync(0xffffffff, global_sq_sum, offset);

    if (tid % 32 == 0) s_reduction[tid / 32] = global_sq_sum;
    __syncthreads();

    if (tid == 0) {
        float total = 0;
        for (int i = 0; i < (blockDim.x + 31) / 32; ++i) total += s_reduction[i];
        s_reduction[0] = rsqrtf(total + 1e-12f);
    }
    __syncthreads();

    // Final Step: Global normalization
    float inv_gnorm = s_reduction[0];
    for (int i = tid; i < D * K; i += blockDim.x) {
        out[b * D * K + i] *= inv_gnorm;
    }
}

torch::Tensor vlad_finalize_cuda(torch::Tensor vlad_raw, torch::Tensor a_sum, torch::Tensor clusters2) {
    int B = vlad_raw.size(0);
    int K = vlad_raw.size(1);
    int D = vlad_raw.size(2);

    auto out = torch::empty({B, D * K}, vlad_raw.options());

    const int block_size = 256;
    vlad_finalize_kernel<<<B, block_size>>>(
        vlad_raw.data_ptr<float>(),
        a_sum.data_ptr<float>(),
        clusters2.data_ptr<float>(),
        out.data_ptr<float>(),
        B, K, D
    );

    return out;
}
"""

vlad_finalize_cpp_source = (
    "torch::Tensor vlad_finalize_cuda(torch::Tensor vlad_raw, torch::Tensor a_sum, torch::Tensor clusters2);"
