    cpp_sources=vlad_finalize_cpp_source,
    cuda_sources=vlad_finalize_cuda_source,
    functions=["vlad_finalize_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, cluster_size, feature_size, ghost_clusters):
        super(ModelNew, self).__init__()

        self.feature_size = feature_size
        self.cluster_size = cluster_size
        self.ghost_clusters = ghost_clusters

        init_sc = (1 / math.sqrt(feature_size))
        clusters = cluster_size + ghost_clusters

        # The `clusters` weights are the `(w,b)` in the paper
        self.clusters = nn.Parameter(init_sc * torch.randn(feature_size, clusters))
        self.batch_norm = nn.BatchNorm1d(clusters)
        # The `clusters2` weights are the visual words `c_k` in the paper
        self.clusters2 = nn.Parameter(init_sc * torch.randn(1, feature_size, cluster_size))
        self.out_dim = self.cluster_size * feature_size
        self.vlad_lib = vlad_lib

    def forward(self, x, mask=None):
        """Aggregates feature maps into a fixed size representation.
        B = batch_size, N = num_features, K = num_clusters, D = feature_size.
        """
        B, N, D = x.shape
        x_flat = x.view(-1, D)

        # 1. First Matmul + BN + Softmax
        # assignment: (BN x (K+G))
        assignment = self.batch_norm(torch.matmul(x_flat, self.clusters))
        assignment = F.softmax(assignment, dim=1)

        # 2. Slice ghost clusters and prepare for summation/matmul
        # assignment_sliced: (BN x K)
        assignment_sliced = assignment[:, :self.cluster_size].contiguous()
        assignment_reshaped = assignment_sliced.view(B, N, self.cluster_size)

        # a_sum: (B, K)
        a_sum = assignment_reshaped.sum(dim=1)

        # 3. Second Matmul to get aggregated cluster features
        # (B x K x N) x (B x N x D) -> (B x K x D)
        vlad_raw = torch.matmul(assignment_reshaped.transpose(1, 2), x)

        # 4. Custom VLAD finalize (subtraction, intra-norm, flatten, global-norm)
        # clusters2 is reshaped from (1, D, K) to (D, K)
        vlad = self.vlad_lib.vlad_finalize_cuda(
            vlad_raw.contiguous(), 
            a_sum.contiguous(), 
            self.clusters2.view(D, self.cluster_size).contiguous()
        )

        return vlad

