import torch
import torch.nn as nn
import torch.nn.functional as F
from einops import rearrange
from torch.utils.cpp_extension import load_inline

# Custom CUDA Kernel for Fused Diagonal SSM Computation
# This kernel fuses the segment sum, exponentiation, kernel materialization, and matrix multiplication
# for the diagonal block (intra-chunk) computation Y_diag.
# It replaces the O(L^2) memory complexity with O(L) shared memory and avoids materializing large masks.

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void ssm_diag_kernel(
    const float* __restrict__ A_cumsum, // (B, H, C, L)
    const float* __restrict__ B_blocks, // (B, C, L, H, N)
    const float* __restrict__ C_blocks, // (B, C, L, H, N)
    const float* __restrict__ X_blocks, // (B, C, L, H, P)
    float* __restrict__ Y_out,          // (B, C, L, H, P)
    int B_size, int C_size, int H_size, int L_size, int N_size, int P_size
) {
    // Dynamic shared memory configuration
    // Layout:
    // A_smem: L
    // B_smem: L * N
    // C_smem: L * N
    // K_smem: L * L  (Triangular kernel matrix)
    // X_smem: L * P  (Optional, but helps if P is small. Here P=64, fits)

    extern __shared__ float smem[];
    float* s_A = smem;
    float* s_B = s_A + L_size;
    float* s_C = s_B + L_size * N_size;
    float* s_K = s_C + L_size * N_size;
    float* s_X = s_K + L_size * L_size; 

    // Grid Mapping
    // flat_idx covers (B, C, H)
    int idx = blockIdx.x;
    int total_blocks = B_size * C_size * H_size;
    if (idx >= total_blocks) return;

    // Decode indices
    int h = idx % H_size;
    int temp = idx / H_size;
    int c = temp % C_size;
    int b = temp / C_size;

    int tid = threadIdx.x;
    int block_dim = blockDim.x;

    // Pointers offsets
    // A: (b, h, c, l) -> stride(c)=L, stride(h)=C*L, stride(b)=H*C*L
    long long offset_A = (long long)b * H_size * C_size * L_size + (long long)h * C_size * L_size + (long long)c * L_size;

    // B, C, X: (b, c, l, h, ...)
    // Strides for l dimension involve H and inner dim
    long long stride_l_B = H_size * N_size;
    long long stride_l_X = H_size * P_size;

    // Base offsets for the chunk (b, c, 0, h, 0)
    long long base_B = ((long long)b * C_size * L_size + (long long)c * L_size) * stride_l_B + (long long)h * N_size;
    long long base_C = ((long long)b * C_size * L_size + (long long)c * L_size) * stride_l_B + (long long)h * N_size;
    long long base_X = ((long long)b * C_size * L_size + (long long)c * L_size) * stride_l_X + (long long)h * P_size;
    long long base_Y = base_X; // Y has same shape as X

    // 1. Load A (L)
    for (int i = tid; i < L_size; i += block_dim) {
        s_A[i] = A_cumsum[offset_A + i];
    }

    // 2. Load B and C (L * N)
    // Flattened loop for B and C
    int total_BN = L_size * N_size;
    for (int i = tid; i < total_BN; i += block_dim) {
        int l = i / N_size;
        int n = i % N_size;
        s_B[i] = B_blocks[base_B + l * stride_l_B + n];
        s_C[i] = C_blocks[base_C + l * stride_l_B + n];
    }

    // 3. Load X (L * P)
    int total_XP = L_size * P_size;
    for (int i = tid; i < total_XP; i += block_dim) {
        int l = i / P_size;
        int p = i % P_size;
        s_X[i] = X_blocks[base_X + l * stride_l_X + p];
    }

    __syncthreads();

    // 4. Compute K matrix (L * L)
    // K[l, s] = (sum_n C[l,n]*B[s,n]) * exp(A[l] - A[s]) if s <= l else 0
    int total_LL = L_size * L_size;
    for (int i = tid; i < total_LL; i += block_dim) {
        int l = i / L_size;
        int s = i % L_size;

        float val = 0.0f;
        if (s <= l) {
            // Dot product C[l] . B[s]
            float dot = 0.0f;
            for (int n = 0; n < N_size; ++n) {
                dot += s_C[l * N_size + n] * s_B[s * N_size + n];
            }

            // Decay
            float decay_val = s_A[l] - s_A[s];
            val = dot * expf(decay_val);
        }
        s_K[l * L_size + s] = val;
    }

    __syncthreads();

    // 5. Compute Y = K * X (L * P)
    // Y[l, p] = sum_s K[l, s] * X[s, p]
    for (int i = tid; i < total_XP; i += block_dim) {
        int l = i / P_size;
        int p = i % P_size;

        float acc = 0.0f;
        // Optimization: s loop only needs to go up to l because K is triangular
        for (int s = 0; s <= l; ++s) {
            acc += s_K[l * L_size + s] * s_X[s * P_size + p];
        }

        // Write global
        Y_out[base_Y + l * stride_l_X + p] = acc;
