# which is equivalent to the chunked segment-sum recurrence in the original model.
ssd_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void ssd_final_state_kernel(
    const float* __restrict__ X,      // (B, L, H, P)
    const float* __restrict__ A,      // (B, L, H)
    const float* __restrict__ B,      // (B, L, H, N)
    const float* __restrict__ initial_states, // (B, 1, H, P, N) or nullptr
    float* __restrict__ out,          // (B, H, P, N)
    int B_sz, int L_sz, int H_sz, int P_sz, int N_sz) 
{
    // Each block handles one (batch, head) pair.
    int bh = blockIdx.x;
    if (bh >= B_sz * H_sz) return;
    int b = bh / H_sz;
    int h = bh % H_sz;

    // Parallelize over d_head (P) and d_state (N) dimensions.
    for (int p = threadIdx.x; p < P_sz; p += blockDim.x) {
        for (int n = threadIdx.y; n < N_sz; n += blockDim.y) {
            float state = 0.0f;
            if (initial_states != nullptr) {
                // Initial state shape is (B, 1, H, P, N)
                state = initial_states[((b * H_sz + h) * P_sz + p) * N_sz + n];
            }

            // Linear recurrence over the sequence length L.
            for (int t = 0; t < L_sz; ++t) {
                // Flattened index for A(b, t, h)
                int base_idx = (b * L_sz + t) * H_sz + h;
