# NewGELU Kernel Source
new_gelu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h> // For tanhf, powf

// Define constants for NewGELU
#define M_SQRT2_F 1.41421356237309504880f
#define M_SQRTPI_F 1.77245385090551602729f
#define GELU_CONST_1 (M_SQRT2_F / M_SQRTPI_F) // sqrt(2.0 / pi)
#define GELU_CONST_2 0.044715f

__global__ void new_gelu_kernel(const float* in, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x_val = in[idx];
        float term2 = x_val + GELU_CONST_2 * powf(x_val, 3.0f);
        float tanh_arg = GELU_CONST_1 * term2;
        float tanh_val = tanhf(tanh_arg);
        out[idx] = 0.5f * x_val * (1.0f + tanh_val);
    }
}

torch::Tensor new_gelu_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");

    auto out = torch::empty_like(x);
    int size = x.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    new_gelu_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );
    return out;
}
"""

new_gelu_cpp_source = (
    "torch::Tensor new_gelu_cuda(torch::Tensor x);"
)

