    functions=["new_gelu_cuda"],
    verbose=False, # Set to True for debugging compilation
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

# Causal Masked ReLU Kernel Source (fuses masked_fill and F.relu)
causal_masked_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h> // For fmaxf

__global__ void causal_masked_relu_kernel(
    const float* in_scores, const float* causal_mask, float* out_att,
    int B, int nh, int T_seq
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = B * nh * T_seq * T_seq;

    if (idx < total_elements) {
        float score = in_scores[idx];
        // The causal_mask is (1, 1, T_seq, T_seq) and contiguous.
        // Its elements are indexed as [0, 0, i, j].
        // The flat index for mask is i * T_seq + j.
        int i_mask = (idx / T_seq) % T_seq;
        int j_mask = idx % T_seq;
        float mask_val = causal_mask[i_mask * T_seq + j_mask];

        // Original logic: att = att.masked_fill(self.bias == 0, float('-inf')) then att = F.relu(att)
        // If mask_val is 0.0f (meaning bias was 0), it would be filled with -inf, then ReLU makes it 0.
        // If mask_val is 1.0f (meaning bias was 1), ReLU is applied directly.
        out_att[idx] = (mask_val == 0.0f) ? 0.0f : fmaxf(0.0f, score);
    }
}

torch::Tensor causal_masked_relu_cuda(torch::Tensor input_scores, torch::Tensor causal_mask) {
    TORCH_CHECK(input_scores.is_cuda(), "input_scores must be a CUDA tensor");
    TORCH_CHECK(causal_mask.is_cuda(), "causal_mask must be a CUDA tensor");
    TORCH_CHECK(input_scores.is_contiguous(), "input_scores must be contiguous");
    TORCH_CHECK(causal_mask.is_contiguous(), "causal_mask must be contiguous");
    TORCH_CHECK(input_scores.dtype() == torch::kFloat32, "input_scores must be float32");
    TORCH_CHECK(causal_mask.dtype() == torch::kFloat32, "causal_mask must be float32");

    // input_scores: (B, nh, T, T)
    // causal_mask: (1, 1, T, T)
    TORCH_CHECK(input_scores.dim() == 4, "input_scores must be 4D");
    TORCH_CHECK(causal_mask.dim() == 4, "causal_mask must be 4D");
    TORCH_CHECK(causal_mask.size(0) == 1 && causal_mask.size(1) == 1, "causal_mask must have batch and head dim of 1");
    TORCH_CHECK(input_scores.size(2) == causal_mask.size(2) && input_scores.size(3) == causal_mask.size(3), "T dimensions must match");

    auto out_att = torch::empty_like(input_scores);

    int B = input_scores.size(0);
    int nh = input_scores.size(1);
    int T_seq = input_scores.size(2); // T

    int total_elements = input_scores.numel();

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    causal_masked_relu_kernel<<<num_blocks, block_size>>>(
